!
      remain = nrec * recsiz
      addr   = baddr + ( first - 1 )*recsiz
      move   = min( 50, remain )

      do while ( remain > 0 )

         call dafgda ( ctx, handle, addr, addr + move - 1, data )
         call dafada ( ctx, data, move )
         remain = remain - move
         addr   = addr   + move
         move   = min( 50, remain )

      end do

!
