      !>
      !>-    SPICELIB Version 2.0.0, 04-APR-2017 (NJB)
      !>
      !>        Typo in comment fixed.
      !>
      !>        11-MAY-2015 (NJB)
      !>
      !>        Updated to support subtype 2.
      !>
      !>-    SPICELIB Version 1.0.0, 17-OCT-2011 (NJB) (BVS) (WLT) (IMU) (EDW)
      module subroutine spks19 ( ctx, handle, baddr, eaddr, begin, end )
      use pepper_kinds, only: ip, wp
      use pepper_arrays, only: lstled, lstltd
      use pepper_inc_spk19
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of file containing source segment.
      integer(ip), intent(in) :: baddr  !! Beginning address in file of source segment.
      integer(ip), intent(in) :: eaddr  !! Ending address in file of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.
      real(wp) :: ivlbeg_1(1)  !! one-element copy of ivlbeg (array argument)
      real(wp) :: ivlend_1(1)  !! one-element copy of ivlend (array argument)
      integer(ip), parameter :: ctrlsz = 3
      integer(ip), parameter :: pktszs ( 0 : s19nst-1 ) = &
         [ s19ps0, s19ps1, s19ps2 ]
      integer(ip) :: npad
      integer(ip) :: ub
      integer(ip) :: eepidx
      integer(ip) :: start
      real(wp) :: data     ( bufsiz )
      logical :: final
      real(wp) :: contrl   ( ctrlsz )
      integer(ip) :: ndir
      integer(ip) :: subtyp
      integer(ip) :: bepidx
      integer(ip) :: npkt
      real(wp) :: ivlend
      integer(ip) :: curivl
      integer(ip) :: ivlbas
      integer(ip) :: wndsiz
      integer(ip) :: minie
      integer(ip) :: l
      integer(ip) :: i
      integer(ip) :: minnpk
      integer(ip) :: nintvl
      integer(ip) :: minndr
      integer(ip) :: isel
      real(wp) :: ivlbeg
      integer(ip) :: begidx
      integer(ip) :: bufbas
      integer(ip) :: nsdir
      integer(ip) :: pktsiz
      integer(ip) :: noivl
      integer(ip) :: remain
      integer(ip) :: nread
      integer(ip) :: minib
      integer(ip) :: minbep
      integer(ip) :: ptrbas
      integer(ip) :: endidx
      integer(ip) :: min1sz
      if ( .not. allocated ( ctx%spks19_state ) ) allocate ( ctx%spks19_state )
      associate ( iv1beg => ctx%spks19_state%iv1beg, &
                  iv1end => ctx%spks19_state%iv1end, &
                  ivfbeg => ctx%spks19_state%ivfbeg, &
                  ivfend => ctx%spks19_state%ivfend, &
                  minfsz => ctx%spks19_state%minfsz, &
                  shift => ctx%spks19_state%shift )
      if ( ctx%failed() ) return

!
!     Terminology
!     ===========
!
!       - A point P is in the "interior" of a set S if P is
!         an element of S and P is not contained in the boundary
!         of S. If S is a discrete set of distinct times, then
!         the interior points of S are greater than the earliest
!         time in S and earlier than the latest time in S. If
!         S is the closed interval [A, B], that is, if S is the set of
!         points P such that
!
!            A  <  P  <  B
!               -     -
!
!         then the interior of S is the set of points P such that
!
!            A  <  P  <  B
!
!       - A subset S2 of a set S1 is in the "interior" of S1 if
!         every point of S2 is contained in the interior of S1.
!
!       - SPK type 19 interpolation intervals are often simply
!         called "intervals."
!
!       - The data set corresponding to a type 19 interpolation
!         interval is called a "mini-segment."
!
!       - "Padding" consists of a sequence of contiguous data packets
!         and a corresponding sequence of epochs provided to enable
!         correct interpolation near interval boundaries, where the
!         epochs lie outside of the interval's coverage time range.
!         Padding data and epochs are always drawn only from the same
!         input mini-segment that provides data for the output
!         mini-segment under construction.
!
!       - A "base address" of a structure is the DAF address preceding
!         the first address occupied by the structure.
!
!     Algorithm
!     =========
!
!     The algorithm below transfers to the output segment sufficient
!     data to cover the time range BEGIN : END, such that the output
!     segment yields interpolation behavior identical to that of the
!     selected portion of the input segment.
!
!     No use is made of the selection order attribute other than to
!     transfer it to the output segment. This simplifies the algorithm,
!     at the expense of making the output segment larger than necessary
!     by at most a small, bounded amount. Specifically, when either
!     BEGIN or END coincides with an interior interval boundary, a
!     small additional output interval is created so as to make that
!     boundary an interior point of the output segment's coverage
!     interval. This guarantees that the correct interval can be
!     selected when a request time coincides with the boundary of
!     interest.
!
!     The overall approach is:
!
!        1)  Obtain attribute information from the input segment.
!
!        2)  Create a first output mini-segment. This mini-segment is
!            created using data from the first input mini-segment
!            having an end time greater than or equal to BEGIN.
!
!            The first output mini-segment contains padding, if needed,
!            on both the left and right sides. On the left side, given
!            a nominal interpolation window width W (W must be even),
!            the nominal pad size NPAD is (W/2) - 1. If I is the index
!            of the last time tag (in the selected input mini-segment)
!            less than or equal to BEGIN, the pad starts at I-NPAD or
!            1, whichever is greater.
!
!            On the right side, if END is greater than or equal to the
!            last epoch of the input mini-segment, all epochs and
!            packets of the input mini-segment following the first ones
!            selected are transferred to the output mini-segment.
!
!            The first mini-segment requires padding on the right only
!            if END precedes the end time of the input mini-segment. In
!            this case the pad size is chosen so that the output
!            mini-segment contains W/2 epochs greater than or equal to
!            END, if possible. If I is the index of the first time tag
!            in the mini-segment greater than or equal to END, then the
!            pad ends at I + (W/2) - 1 or NPKT, whichever is smaller.
!
!            Note that due to the asymmetry of the search techniques
!            used (there are no SPICELIB right-to-left search routines
!            analogous to LSTLTD and LSTLED), the implementation of the
!            pad computation for the right side is not as similar to
!            that for the left side as one might expect.
!
!            The first output mini-segment and all subsequent output
!            mini-segments have the structure of an SPK type 18
!            segment. They consist of
!
!               a) A sequence of data packets
!
!               b) A sequence of epochs
!
!               c) An epoch directory, if needed
!
!               d) A control area, consisting of
!
!                    - A subtype code
!                    - An interpolation window size
!                    - A packet count
!
!        3)  All input mini-segments whose interpolation intervals
!            follow that of the first used mini-segment and whose stop
!            times are less than or equal to END are copied whole
!            to the output segment. We refer to this sequence of
!            mini-segments as the "middle group." The middle group may
!            be empty.
!
!        4)  If necessary, a final output mini-segment is written. This
!            mini-segment will be required unless either
!
!               - The interval of the first mini-segment contains in
!                 its interior the interval BEG : END.
!
!               - The middle group ends at the end of the input segment.
!
!            Note that if the last interval of the middle group ends at
!            END, but END is less than the final input interval's stop
!            time, a final mini-segment is still needed to ensure
!            correct interval selection. If there is no middle group
!            and the first used interpolation interval ends at END, and
!            if END is less than the final input interval's stop time,
!            a final mini-segment is required as well.
!
!            The interpolation interval of the final output
!            mini-segment always starts at an input interval boundary.
!            This interval has padding on the left only if the
!            corresponding input interval has padding on the left; any
!            existing left side padding from the input mini-segment is
!            simply copied to the output mini-segment. On the right
!            side, padding is created if it is necessary and possible
!            to do so. When right side padding is used, the pad size
!            and placement follow the same rules used for the right
!            side padding of the first output mini-segment.
!
!        5)  After all output mini-segments have been written, the
!            following segment-level structures are written to the
!            output segment:
!
!               a) The output segment interpolation interval
!                  boundaries. This list includes the start time of
!                  each output interval and the stop time of the final
!                  output interval.
!
!               b) The output segment interpolation interval boundary
!                  directory, if needed.
!
!               c) The output segment's mini-segment begin and "end"
!                  pointers. This list consists of the segment
!                  base-relative first address of each mini-segment,
!                  plus the relative address following the final output
!                  mini-segment.
!
!               d) The output segment control area. This consists of:
!
!                    - The interval selection order flag. This is copied
!                      from the input segment.
!
!                    - The output segment interval count
!
!     See whether there's any work to do; return immediately if not.
!
      if (  begin  >  end  ) return
!
!     We don't check BEGIN and END against the time bounds of the
!     descriptor of the input file because, according to the
!     SPK subsetting subsystem design, the calling routine SPKSUB
!     has done this already. Note that the descriptor of the source
!     segment is not even an input to this routine. If we wanted to,
!     we could search the input DAF for a descriptor that mapped to
!     the address range BADDR : EADDR. but we're not going to do
!     that.
!
!     Initialize the flag indicating the existence of the "final"
!     output mini-segment.
!
      final  = .false.

!***********************************************************************
!
!     Part 1: Obtain attributes of the input segment
!
!***********************************************************************

!
!     Read the input segment structure control area.
!
      call dafgda ( ctx, handle, eaddr-1, eaddr, data )

      if ( ctx%failed() ) return

!
!     Fetch the interval selection order flag and the
!     number of interpolation intervals.
!
      isel   = nint ( data(1) )
      nintvl = nint ( data(2) )

!
!     Compute the number of interval boundary directories. Recall that
!     the final interval stop time must be accounted for, so the
!     directory count is
!
!        ( ( NINTVL + 1) - 1 ) / DIRSIZ
!

      ndir = nintvl / dirsiz

!
!     Find the base address IVLBAS of the interval start times. First
!     set PTRBAS, which is the address preceding the interval pointers.
!
!     The interval base precedes the interval bounds, the interval
!     directories, the interval pointers, and the control area.
!
      ptrbas = eaddr  -  ( 2    +  nintvl + 1 )
      ivlbas = ptrbas -  ( ndir +  nintvl + 1 )

!***********************************************************************
!
!     Part 2: Create the first output mini-segment
!
!***********************************************************************

!
!     Search for the first interval that will contribute data to the
!     output segment. We first find the last interval boundary that is
!     strictly less than the epoch BEGIN. The final interval stop time
!     need not be considered, since the segment covers the interval
!     [BEGIN : END]. Note however there is a "corner case" in which
!
!        BEGIN == END == <final interval stop time>
!
!     Since we're only examining interval start times, the last one
!     we may need to read is at index NINTVL.
!
      nread  = min ( bufsiz, nintvl )

      bufbas = ivlbas

!
!     NREAD is at least 1 here.
!
      call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

      if ( ctx%failed() ) return

      remain = nintvl - nread

!
!     The variable NREAD is the array index of the last
!     item read into the buffer on the previous read
!     operation. On the first pass NREAD is at least 1.
!
      do while (       ( remain      > 0     ) &
                 .and. ( data(nread) < begin )  )

         bufbas = bufbas + nread

         nread  = min ( bufsiz, remain )
!
!        NREAD is at least 1 here.
!
         call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

         if ( ctx%failed() ) return

         remain = remain - nread

      end do
!
!     Let I be the index of the last interval boundary time that
!     precedes BEGIN. If there are no such boundary times, I will be
!     zero. This latter case can happen only when the first interval
!     start time is equal to BEGIN.
!
!     At this point BUFBAS - IVLBAS is the number of boundaries we
!     examined before the final call above to DAFGDA. All of those
!     boundary times were strictly less than BEGIN.
!
      i  =  ( bufbas - ivlbas )  +  lstltd ( begin, nread, data )

!
!     Let BEGIDX be the index of the last interval start time that
!     precedes BEGIN, unless BEGIN coincides with the first interval
!     start time; in this case, BEGIDX must be 1.
!
      begidx = max ( 1, i )

!
!     In order to extract data from the mini-segment, we'll need its
!     address range.
!
      call dafgda ( ctx, handle, ptrbas+begidx, ptrbas+begidx+1, data )

      if ( ctx%failed() ) return

!
!     Convert the segment-base-relative mini-segment begin and end
!     pointers to absolute DAF addresses.
!
      minib = ( baddr - 1 ) + nint( data(1) )
      minie = ( baddr - 1 ) + nint( data(2) ) - 1

!
!     Read the control area of the mini-segment.
!
      bufbas = minie - ctrlsz

      call dafgda ( ctx, handle, bufbas+1, bufbas+ctrlsz, contrl )

      if ( ctx%failed() ) return

!
!     Fetch the control area parameters for the mini-segment.
!
      subtyp  =  nint ( contrl(1) )
      wndsiz  =  nint ( contrl(2) )
      npkt    =  nint ( contrl(3) )

!
!     Set the packet size, which is a function of the subtype.
!
      if ( ( subtyp < 0 ) .or. ( subtyp >= s19nst ) ) then

         call ctx%setmsg ( 'Unexpected SPK type 19 subtype # found in ' &
         //            'type 19 segment within mini-segment #.'     )
         call ctx%errint ( '#',  subtyp                                 )
         call ctx%errint ( '#',  begidx                                 )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                        )
         return

      end if

      pktsiz = pktszs( subtyp )

!
!     Determine how much of the mini-segment we need to transfer. The
!     first step is to find the last epoch less than or equal to BEGIN
!     in the mini-segment's epoch list. Let MINBEP be the base address
!     of the epoch list (that is, the start address minus 1).
!
      minbep = ( minib - 1 )  +  ( npkt * pktsiz )

!
!     Read epochs until we find one greater than or equal to BEGIN.
!
!     It's possible that only the last epoch of the input mini-segment
!     satisfies this criterion, but at least one epoch must satisfy it.
!
      nread  = min ( bufsiz, npkt )

      bufbas = minbep

      call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

      if ( ctx%failed() ) return

      remain = npkt - nread

!
!     The variable NREAD is the array index of the last
!     item read into the buffer on the previous read
!     operation.
!
      do while (       ( remain      > 0     ) &
                 .and. ( data(nread) < begin )  )
!
!        Advance the buffer base to account for the NREAD
!        epochs fetched on the previous DAFGDA call.
!
         bufbas = bufbas + nread

         nread  = min ( bufsiz, remain )
!
!        Since REMAIN was positive at the beginning of this
!        loop iteration, NREAD is positive here.
!
         call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

         if ( ctx%failed() ) return

         remain = remain - nread

      end do
!
!     At this point BUFBAS - MINBEP is the number of epochs in the
!     input mini-segment we've examined before the final call above to
!     DAFGDA. All of those epochs were strictly less than BEGIN.
!
!     Let BEPIDX be the index of the last epoch that precedes or is
!     equal to BEGIN. That epoch is contained in the last buffer we
!     read.
!
      bepidx =  ( bufbas - minbep )  +  lstled ( begin, nread, data )

!
!     BEPIDX is at least 1 and may be as large as NPKT.
!
!     Compute the number of pad epochs we need to maintain proper
!     interpolation behavior in the neighborhood of the epoch at
!     index BEPIDX.
!
      npad   =  ( wndsiz / 2 ) - 1

!
!     Shift BEPIDX by the pad amount, if possible. The minimum value
!     of BEPIDX is 1.
!
      bepidx =  max ( 1,  bepidx - npad )

!
!     The output mini-segment can never have fewer than two epochs.
!     When the window size is 2 and BEPIDX is equal to NPKT, we
!     must extend the window on the left.
!
      bepidx = min ( bepidx,  npkt-1 )

!
!     If the input interval end time is less than or equal to END, we
!     need to use the rest of the data from this interval. Otherwise
!     find out how much data from this interval we need to transfer.
!
      bufbas = ivlbas + begidx

      call dafgda ( ctx, handle, bufbas+1, bufbas+1, ivlend_1 )
      ivlend = ivlend_1(1)

      if ( ctx%failed() ) return

!
!     Let EEPIDX be the index of the last epoch we select from
!     the current input mini-segment. We'll set EEPIDX below.
!
      if ( ivlend <= end ) then
!
!        The requested subset coverage is either equal to or extends
!        beyond the right boundary of this interval. We'll use all data
!        from this interval.
!
         eepidx = npkt

      else
!
!        IVLEND is strictly greater than END. This interval covers
!
!           [BEGIN, END].
!
!        Read epochs from this mini-segment until we find one greater
!        than or equal to END. We have an error if we run out of
!        epochs.
!
!        The input mini-segment contains ( NPKT - BEPIDX + 1 ) epochs
!        following and including the one at BEPIDX.
!
         remain = npkt - bepidx + 1
!
!        REMAIN is at least 2 at this point, since in this case,
!        some epoch exceeds END, and that epoch must have index
!        greater than BEPIDX.
!
         nread  = min ( bufsiz, remain )
!
!        NREAD is at least 2.
!
         if ( nread < 2 ) then
!
!           This code should not be reached.
!

            call ctx%setmsg ( 'Input file: #. Segment address range: ' &
            //            '#:#. Structural error found: NREAD ' &
            //            'is #; end time of interval # is #.'      )
            call ctx%errch  ( '#', file_name ( ctx%spice, handle ) )
            call ctx%errint ( '#', baddr                                )
            call ctx%errint ( '#', eaddr                                )
            call ctx%errint  ( '#', nread                                )
            call ctx%errint ( '#', begidx                               )
            call ctx%errdp  ( '#', ivlend                               )
            call ctx%sigerr ( 'SPICE(SPKSTRUCTUREERROR)'                )
            return

         end if
!
!        Set the buffer base address so that we start reading at
!        address MINBEP + BEPIDX.
!
         bufbas = minbep + bepidx - 1

         call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

         if ( ctx%failed() ) return

         remain = remain - nread

!
!        NREAD is (still) at least 2.
!
         do while (  ( remain > 0 ) .and. ( data(nread) <= end )  )

            bufbas = bufbas + nread

            nread  = min ( remain, bufsiz )
!
!           NREAD is at least 1 since REMAIN was positive
!           at the top of the loop.
!
            call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

            if ( ctx%failed() ) return

            remain = remain - nread

         end do
!
!        At this point BUFBAS - MINBEP is the number of epochs in the
!        input mini-segment we've examined before the final call above
!        to DAFGDA. If this set of epochs is non-empty, all of these
!        epochs are less than or equal to END. Note that it's possible
!        for END and BEGIN to be equal to the first epoch.
!
!        Let EEPIDX be the index of the first epoch that is strictly
!        greater than END. As asserted above, in this branch of the
!        code, such an epoch must exist. That epoch is contained in the
!        last buffer we read.
!
!        EEPIDX exceeds by 1 the index of the last epoch less than or
!        equal to END.
!
         l      = lstled ( end, nread, data )

         eepidx = ( bufbas - minbep ) + l + 1

!
!        EEPIDX is at least 2 and is less than or equal to NPKT.
!
         if (  ( eepidx < 2 ) .or. ( eepidx > npkt ) ) then
!
!           This code should not be reached.
!

            call ctx%setmsg ( 'Input file: #. Segment address range: ' &
            //            '#:#. Structural error found: last epoch ' &
            //            'is #; end time of interval # is #.'      )
            call ctx%errch  ( '#', file_name ( ctx%spice, handle ) )
            call ctx%errint ( '#', baddr                                )
            call ctx%errint ( '#', eaddr                                )
            call ctx%errdp  ( '#', data(nread)                          )
            call ctx%errint ( '#', begidx                               )
            call ctx%errdp  ( '#', ivlend                               )
            call ctx%sigerr ( 'SPICE(SPKSTRUCTUREERROR)'                )
            return

         end if

!
!        Compute the number of pad epochs we need to maintain proper
!        interpolation behavior in the neighborhood of the epoch at
!        index EEPIDX.
!
         if ( data(l) == end ) then
!
!           The epochs at indices EEPIDX-1 and EEPIDX comprise the
!           first two epochs of the right half of an interpolation
!           window of size WNDSIZ. We need two fewer pad epochs to
!           complete the right half of the window.
!
            npad = ( wndsiz / 2 ) - 2

         else
!
!           The epoch at EEPIDX is the first of the pad.
!
            npad = ( wndsiz / 2 ) - 1

         end if

!
!        The maximum allowed value of EEPIDX is NPKT.
!
         eepidx =  min ( npkt,  eepidx + npad )

      end if

!
!     At this point BEPIDX and EEPIDX are both set.
!
!     Look up the input interval's start time at index BEGIDX.
!     We'll use this below when we compute the interval start
!     time of the first output mini-segment.
!
      call dafgda ( ctx, handle, ivlbas+begidx, ivlbas+begidx, ivlbeg_1 )
      ivlbeg = ivlbeg_1(1)

      if ( ctx%failed() ) return

!     We're ready to start transferring data to the output segment. The
!     first mini-segment of the output segment will contain packets
!     BEPIDX through EEPIDX of the input mini-segment at index BEGIDX.
!
      do i = bepidx, eepidx

         bufbas = minib - 1 + ( (i-1) * pktsiz )

         call dafgda ( ctx, handle, bufbas+1, bufbas+pktsiz, data )

         call dafada ( ctx, data, pktsiz )

         if ( ctx%failed() ) return

      end do

!
!     Now transfer the epochs at indices BEPIDX : EEPIDX.
!
!     Inside this loop, determine the bounds of the first output
!     interpolation interval. Each bound is either the corresponding
!     bound of the input interval, or a boundary epoch (first or last)
!     of the output epoch list, whichever is most restrictive.
!
      do i = bepidx, eepidx

         bufbas  =  ( minib - 1 ) + ( npkt * pktsiz ) + ( i - 1 )

         call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

         call dafada ( ctx, data, 1 )

         if ( ctx%failed() ) return

!
!        Let IV1BEG be the start time of the first output
!        interpolation interval. Determine IV1BEG on the first loop
!        pass. IVLBEG has already been set to the start time of the
!        input interval at index BEGIDX.
!
         if ( i == bepidx ) then
!
!           The first output interval cannot start earlier than
!           the interval from which its data are taken. It may
!           start later.
!
            iv1beg = max ( ivlbeg, data(1) )

         end if

!
!        Determine IV1END on the final loop pass.
!
         if ( i == eepidx ) then
!
!           The first output interval cannot end later than
!           the interval from which its data are taken. It may
!           end earlier.
!
            iv1end = min ( ivlend, data(1) )

         end if

      end do

!
!     Create the epoch directory for the first output mini-segment.
!
      minnpk = eepidx - bepidx + 1

      minndr = ( minnpk - 1 ) / dirsiz

      do i = 1, minndr
!
!        Set BUFBAS to the address that immediately precedes the
!        element we're about to read. We must skip over the data
!        packets and the first (BEPIDX-1) epochs before starting our
!        count.
!
         bufbas  =   ( minib  - 1 ) + ( npkt * pktsiz ) + &
                     ( bepidx - 1 ) + ( i    * dirsiz ) - 1

         call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

         call dafada ( ctx, data, 1 )

         if ( ctx%failed() ) return

      end do

!
!     Finally, write out the control area for the first mini-segment.
!
      call dafada ( ctx, [ real( subtyp, wp ) ], 1 )
      call dafada ( ctx, [ real( wndsiz, wp ) ], 1 )
      call dafada ( ctx, [ real( minnpk, wp ) ], 1 )

      if ( ctx%failed() ) return

!
!     Compute the size of the first output mini-segment; we'll need
!     this later to compute the second mini-segment start pointer.
!     The size is the sum of the sizes of the packet set, the
!     epochs, the epoch directories, and the control area.
!
      min1sz = (  minnpk * ( pktsiz + 1 )  ) + minndr + ctrlsz

!***********************************************************************
!
!     Part 3: Transfer the middle group of mini-segments to the
!             output segment, if this group is non-empty
!
!***********************************************************************

!
!     At this point, we might already be done with copying
!     mini-segments. If the coverage interval of the mini-segment we
!     just processed contains [BEGIN, END] in its interior, we're done.
!     If there are no more input mini-segments, we're also done.
!     Otherwise, we'll continue to transfer data from subsequent
!     input mini-segments.
!
!     At this point IVLEND is the end time of the first input
!     interval. Note that this time may differ from IV1END, which
!     is the end time of the first output interval.
!
      if (  ( ivlend > end ) .or. ( begidx == nintvl )  ) then
!
!        We've transferred all the data we need. We don't need
!        to obtain data from other mini-segments.
!
         endidx = begidx

!
!        FINAL is already set to .FALSE.
!
      else
!
!        We need more data, and there are more data to be had.
!
!        Things get a bit easier here: all mini-segments that follow
!        the one we just wrote, and that have end times less than or
!        equal to END, get copied without modification to the output
!        file. Note that this sequence of mini-segments could be empty.

         curivl = begidx + 1

!
!        Initialize the start time of the final output mini-segment.
!        We'll update this if we produce more output mini-segments.
!
         ivfbeg = ivlend

!
!        Get the end time of the interval at index CURIVL.
!
         bufbas = ivlbas + curivl

         call dafgda ( ctx, handle, bufbas+1, bufbas+1, ivlend_1 )
         ivlend = ivlend_1(1)

         if ( ctx%failed() ) return

!
!        CURIVL is the index of the interval we're about to process,
!        and if CURIVL is in range, IVLEND is its end time.
!
         do while (  ( ivlend <= end ) .and. ( curivl <= nintvl )  )
!
!           Entering this loop means the "middle" component of the
!           output segment is non-empty.
!
!           Get the begin and end pointers for the current mini-segment.
!
            bufbas = ptrbas + curivl - 1

            call dafgda ( ctx, handle, bufbas+1, bufbas+2, data )

            if ( ctx%failed() ) return

            minib = ( baddr - 1 ) + nint ( data(1) )
            minie = ( baddr - 1 ) + nint ( data(2) ) - 1

!
!           Transfer all data from DAF address MINIB through DAF
!           address MINIE to the target SPK segment.
!
            remain = minie - minib + 1

            bufbas = minib - 1

            nread  = min ( bufsiz, remain )

            do while ( remain > 0 )

               call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

               call dafada ( ctx, data, nread )

               if ( ctx%failed() ) return

               remain = remain - nread

               bufbas = bufbas + nread

               nread  = min ( bufsiz, remain )

            end do
!
!           We've copied the mini-segment at index CURIVL.
!
!           Save the end time of this mini-segment in case
!           this one turns out NOT to be the last; in that
!           case this is the final interval's start time.
!
            ivfbeg = ivlend

!
!           Get the end time of the next interval, if there
!           is one.
!
            curivl = curivl + 1

            if ( curivl <= nintvl ) then

               bufbas = ivlbas + curivl

               call dafgda ( ctx, handle, bufbas+1, bufbas+1, ivlend_1 )
               ivlend = ivlend_1(1)

               if ( ctx%failed() ) return

            end if

         end do
!
!        We've transferred the middle group, if it exists, to the
!        output segment.
!
!        If the last mini-segment we transferred isn't the last of the
!        input segment, we're going to copy at least a portion of the
!        next mini-segment to the output file.
!
!        At this point CURIVL is the index of the next interval to
!        process, if any. If CURIVL is valid, IVLEND is the interval's
!        end time.
!

!***********************************************************************
!
!     Part 4: Create the final output mini-segment, if necessary
!
!***********************************************************************

         if ( curivl > nintvl ) then
!
!           The coverage of the middle group extends to the end of
!           the coverage of the input segment. There's no more data to
!           transfer.
!
!           FINAL is already set to .FALSE.
!
            endidx = nintvl

         else
!
!           We're going to create one last output mini-segment.
!
            final  = .true.
!
!           The input segment contains at least one more interpolation
!           interval, and the end time of this interval is greater than
!           END. Note that if this interval's end time were equal to
!           END, the interval would have been processed in the loop
!           above.
!
            endidx = curivl

!
!           In order to extract data from the mini-segment, we'll need
!           its address range.
!
            call dafgda ( ctx, handle, ptrbas+endidx, ptrbas+endidx+1, data )

            if ( ctx%failed() ) return

            minib = ( baddr - 1 ) + nint( data(1) )
            minie = ( baddr - 1 ) + nint( data(2) ) - 1

!
!           Read the control area of the mini-segment.
!
            bufbas = minie - ctrlsz

            call dafgda ( ctx, handle, bufbas+1, bufbas+ctrlsz, contrl )

            if ( ctx%failed() ) return

!
!           Fetch the control area parameters for the mini-segment.
!
            subtyp  =  nint ( contrl(1) )
            wndsiz  =  nint ( contrl(2) )
            npkt    =  nint ( contrl(3) )

!
!           Set the packet size, which is a function of the subtype.
!
            if ( ( subtyp < 0 ) .or. ( subtyp >= s19nst ) ) then

               call ctx%setmsg ( 'Unexpected SPK type 19 subtype # found ' &
               //            'in type 19 segment within mini-segment ' &
               //            '#.'                                      )
               call ctx%errint ( '#',  subtyp                              )
               call ctx%errint ( '#',  curivl                              )
               call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                     )
               return

            end if

            pktsiz = pktszs( subtyp )

!
!           Determine how much of the mini-segment we need to transfer.
!           The first step is to find the last epoch less than or equal
!           to END in the mini-segment's epoch list. Let MINBEP be the
!           base address of the epoch list (that is, the start address
!           minus 1).
!
            minbep = minib  -  1  +  ( npkt * pktsiz )

!
!           Read epochs until we find one strictly greater than END.
!           The previous interval was the last one with an end time
!           less than or equal to END, so the epoch we seek should
!           exist. We have an error condition if it doesn't.
!
            nread  = min ( bufsiz, npkt )

            bufbas = minbep

            call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

            if ( ctx%failed() ) return

            remain = npkt - nread

!
!           The variable NREAD is the array index of the last item read
!           into the buffer on the previous read operation.
!
            do while (       ( remain      > 0   ) &
                       .and. ( data(nread) <= end )  )

               bufbas = bufbas + nread

               nread  = min ( bufsiz, remain )

               call dafgda ( ctx, handle, bufbas+1, bufbas+nread, data )

               if ( ctx%failed() ) return

               remain = remain - nread

            end do
!
!           At this point BUFBAS - MINBEP is the number of epochs in
!           the input mini-segment we've examined before the final call
!           above to DAFGDA. If this set of epochs is non-empty, all of
!           these epochs are less than or equal to END. Note that it's
!           possible for END and BEGIN to be equal to the first epoch.
!
!           Let EEPIDX be the index of the first epoch that is strictly
!           greater than END. As asserted above, in this branch of the
!           code, such an epoch must exist. That epoch is contained in
!           the last buffer we read.
!
!           EEPIDX exceeds by 1 the index of the last epoch less than
!           or equal to END.
!
            l      =  lstled ( end, nread, data )

            eepidx =  ( bufbas - minbep ) + l + 1

!
!           EEPIDX is at least 2 and is less than or equal to NPKT.
!
            if ( eepidx < 2 ) then
!
!              This code should not be reached, since getting here
!              implies the first epoch of the interval is greater than
!              END.
!

               call ctx%setmsg ( 'Input file: #. Segment address range: ' &
               //            '#:#. Structural error found: no epochs ' &
               //            'in final input interval exceed END. ' &
               //            'Interval index is #; END is #.'          )
               call ctx%errch  ( '#', file_name ( ctx%spice, handle ) )
               call ctx%errint ( '#', baddr                                )
               call ctx%errint ( '#', eaddr                                )
               call ctx%errint ( '#', endidx                               )
               call ctx%errdp  ( '#', end                                  )
               call ctx%sigerr ( 'SPICE(SPKSTRUCTUREERROR)'                )
               return

            end if

!
!           Compute the number of pad epochs we need to maintain proper
!           interpolation behavior in the neighborhood of the epoch at
!           index EEPIDX.
!
            if ( data(l) == end ) then
!
!              The epochs at indices EEPIDX-1 and EEPIDX comprise
!              the first two epochs of the right half of an
!              interpolation window of size WNDSIZ. We need two
!              fewer pad epochs to complete the right half of the
!              window.
!
               npad = ( wndsiz / 2 ) - 2

            else
!
!              The epoch at EEPIDX is the first of the pad.
!
               npad = ( wndsiz / 2 ) - 1

            end if

!
!           Update the final epoch index to include the pad. The index
!           cannot exceed the mini-segment's packet count.
!
            eepidx = min ( npkt,  eepidx + npad )

!
!           EEPIDX must always exceed BEPIDX; no interpolation
!           interval may have zero length.
!
!           When BEGIN is equal to END, and both are equal to the
!           first epoch, and the window size is 2, NPAD will be
!           -1, and EEPIDX will be 1. We don't want to allow
!           EEPIDX to be less than 2.
!
            eepidx = max ( eepidx, 2 )

!
!           EEPIDX should always be in range at this point.
!
            if ( ( eepidx < 2 ) .or. ( eepidx > npkt ) ) then
!
!              This code should not be reached, since getting here
!              implies the first epoch of the interval is greater than
!              END.
!

               call ctx%setmsg ( 'Input file: #. Segment address range: ' &
               //            '#:#. BEPIDX = #; EEPIDX = #; NPKT = #.' &
               //            'Interval index is #; END is #.'          )
               call ctx%errch  ( '#', file_name ( ctx%spice, handle ) )
               call ctx%errint ( '#', baddr                                )
               call ctx%errint ( '#', eaddr                                )
               call ctx%errint ( '#', bepidx                               )
               call ctx%errint ( '#', eepidx                               )
               call ctx%errint ( '#', npkt                                 )
               call ctx%errint ( '#', endidx                               )
               call ctx%errdp  ( '#', end                                  )
               call ctx%sigerr ( 'SPICE(SPKSTRUCTUREERROR)'                )
               return

            end if

!
!           Write the packets of the last mini-segment.
!
            do i = 1, eepidx

               bufbas  =  ( minib - 1 ) + ( (i-1) * pktsiz )

               call dafgda ( ctx, handle, bufbas+1, bufbas+pktsiz, data )

               call dafada ( ctx, data, pktsiz )

               if ( ctx%failed() ) return

            end do

!
!           Write the epochs of the last mini-segment. Save the
!           final epoch; we'll need it later.
!
            do i = 1, eepidx

               bufbas  =  ( minib - 1 ) + ( npkt * pktsiz ) + ( i - 1 )

               call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

               call dafada ( ctx, data, 1 )

               if ( ctx%failed() ) return

               if ( i == eepidx ) then
!
!                 The current interval is the last of the output
!                 segment. The interval end must be greater than or
!                 equal to END. It's safe to simply choose the final
!                 epoch as the interval end.
!
                  ivfend = data(1)

               end if

            end do

!
!           Create epoch directories for the last mini-segment.
!
            minnpk = eepidx

            minndr = ( minnpk - 1 ) / dirsiz

            do i = 1, minndr

               bufbas  =     ( minib - 1  ) + ( npkt * pktsiz ) &
                          +  ( i * dirsiz ) -   1

               call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

               call dafada ( ctx, data, 1 )

               if ( ctx%failed() ) return

            end do

!
!           Finally, write out the control area for the last
!           mini-segment.
!
            call dafada ( ctx, [ real( subtyp, wp ) ], 1 )
            call dafada ( ctx, [ real( wndsiz, wp ) ], 1 )
            call dafada ( ctx, [ real( minnpk, wp ) ], 1 )

            if ( ctx%failed() ) return

!
!           Compute the size in DAF addresses of the last mini-segment.
!           This is the sum of the sizes of the packet space, the
!           epochs, the directories, and the control area.
!
            minfsz = ( minnpk * ( pktsiz + 1 ) )  +  minndr  +  ctrlsz

         end if
!
!        We're done with the final mini-segment.
!
      end if
!
!     We've transferred all of the data we need from mini-segments at
!     indices BEGIDX : ENDIDX.

!***********************************************************************
!
!     Part 5: Create segment-level data structures in the output segment
!
!***********************************************************************

!
!     Write out the interval bounds for the new segment.
!
!     Let NOIVL be the number of intervals in the output subset
!     segment.
!
      noivl = endidx - begidx + 1

!
!     The first interval start time is IV1BEG.
!
      call dafada ( ctx, [ iv1beg ], 1 )

      if ( ctx%failed() ) return

!
!     Write the remaining interval boundaries.
!
      if ( noivl == 1 ) then
!
!        The final interval boundary is the stop time of
!        the first interval.
!
         call dafada ( ctx, [ iv1end ], 1 )

         if ( ctx%failed() ) return

      else
!
!        There are multiple output mini-segments. There is either
!        a non-empty middle group, a final mini-segment, or both.
!
!        Set the upper bound of the interval boundary transfer loop.
!
         if ( final ) then
!
!           We'll transfer all interval start times up to,
!           but not including, the final one.
!
            ub = noivl - 1

         else
!
!           There's no mini-segment following the middle group.
!
!           Transfer all start times of the middle group, plus
!           the end time of the last interval of the middle
!           group.
!
            ub = noivl + 1

         end if

!
!        Transfer interval boundaries from the middle group.
!
         do i = 2, ub

            bufbas = ivlbas + ( begidx - 1 ) + ( i - 1 )

            call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

            call dafada ( ctx, data(1), 1 )

            if ( ctx%failed() ) return

         end do

!
!        If the "final" mini-segment exists, we haven't
!        transferred its interval boundaries. Do it now.
!
         if ( final ) then
!
!           The start and end times of the last output interpolation
!           interval are stored in IVFBEG and IVFEND.
!
!           Note that IVFBEG was initialized after the first output
!           mini-segment was written, and it was updated if necessary
!           in the block of code that transferred the middle group.
!
            call dafada ( ctx, [ ivfbeg ], 1 )
            call dafada ( ctx, [ ivfend ], 1 )

            if ( ctx%failed() ) return

         end if

      end if
!
!     The interval boundaries have been written.
!
!     Create an interval boundary directory for the new segment. Every
!     boundary whose index relative to BEGIDX-1 is multiple of DIRSIZ
!     becomes a directory entry, unless that entry has no successors.
!     This implies that the interval bounds to be read belong to the
!     range
!
!        BEGIDX + 1  :  ENDIDX - 1
!
!     This implies that we can read all of the directory entries
!     from the input segment; we won't use as directory entries
!     the initial or final interval bounds of the output segment.
!
!     Since the number of epoch boundaries is NOIVL + 1, the directory
!     count is
!
!        ( ( NOIVL + 1 ) - 1 ) / DIRSIZ
!
      nsdir = noivl / dirsiz

      do i = 1, nsdir
!
!        Look up the interval boundary at offset I*DIRSIZ from
!        the boundary index BEGIDX-1.
!
         bufbas = ivlbas + ( begidx - 1 ) + ( i * dirsiz ) - 1

         call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )

!
!        Write this directory entry to the output segment.
!
         call dafada ( ctx, data, 1 )

         if ( ctx%failed() ) return

      end do

!
!     Write out mini-segment pointers for the new segment.
!
!     The first output mini-segment ranges from relative
!     addresses 1 : MIN1SZ.
!
      call dafada ( ctx, [ real( 1, wp ) ], 1 )

      if ( noivl == 1 ) then
!
!        The next pointer indicates the first address after the
!        mini-segment, whether or not there is another mini-segment.
!
!        Note that MIN1SZ was initialized after the first output
!        mini-segment was written.
!
         call dafada ( ctx, [ real( min1sz + 1, wp) ], 1 )

      else
!
!        There are multiple output mini-segments. There is either
!        a non-empty middle group, a final mini-segment, or both.
!
!        We can obtain from the input segment the sizes of the
!        mini-segments that were copied whole.
!
         start = min1sz + 1

!
!        Set the upper bound of the mini-segment pointer transfer loop.
!
         if ( final ) then
!
!           We'll transfer all mini-segment start pointers up to and
!           including the start pointer of the final output
!
            ub = noivl

         else
!
!           The middle group is non-empty, and there's no mini-segment
!           following the middle group.
!
!           Write all start pointers of the middle group, plus the end
!           pointer of the last mini-segment of the middle group. The
!           end pointer is the successor of the last DAF address
!           occupied by the mini-segment.
!
            ub = noivl + 1

         end if

!
!        Write mini-segment pointers from the middle group.
!
!        All of the middle group pointers of the output segment will be
!        shifted relative to the corresponding pointers of the input
!        segment. The shift reflects the sum of the sizes of the input
!        mini-segments preceding the first one from which data were
!        transferred, as well as the amount by which the first output
!        mini-segment "shrank" relative to the mini-segment from which
!        it was created. The shift equals the difference between the
!        final address of the first output mini-segment and the final
!        address of the input mini-segment at index BEGIDX.
!
         do i = 2, ub
!
!           Look up the Ith start pointer.
!
            bufbas = ptrbas + ( begidx - 1 ) + ( i - 1 )

            call dafgda ( ctx, handle, bufbas+1, bufbas+1, data )
!
!           On the first pass, compute the pointer shift amount.
!
            if ( i == 2 ) then

               shift = ( min1sz + 1 ) - nint( data(1) )

            end if

            start = nint( data(1) )  +  shift

            call dafada ( ctx, [ real( start, wp ) ], 1 )

            if ( ctx%failed() ) return

         end do

!
!        If the "final" mini-segment exists, we haven't
!        transferred its end pointer. Do it now.
!
         if ( final ) then
!
!           MINFSZ is the size of the final output mini-segment.
!
!           The end pointer of the last output mini-segment is
!           START+MINFSZ. The end pointer is the successor of the last
!           DAF address of the mini-segment.
!
!           Write the pointer.
!
            call dafada ( ctx, [ real( start + minfsz, wp ) ], 1 )

         end if

      end if

!
!     Write the interval count and selection flag to the
!     new segment.
!
      call dafada ( ctx, [ real( isel, wp  ) ], 1 )
      call dafada ( ctx, [ real( noivl, wp ) ], 1 )

      return
      end associate
      end subroutine spks19

      !> Extract a subset of the data in a SPK segment of type 20
      !> into a new segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE,
      !>     BADDR,
      !>     EADDR    are the file handle assigned to a SPK file, and the
      !>              beginning and ending addresses of a segment within
      !>              the file. Together they determine a complete set of
      !>              ephemeris data, from which a subset is to be
      !>              extracted.
      !>
      !>     BEGIN,
      !>     END      are the initial and final epochs (ephemeris time)
      !>              of the subset to be extracted.
      !>
      !>## Detailed Output
      !>
      !>     None. This routine writes data to the SPK file currently
      !>     open for write access.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs while reading data from the source SPK
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     2)  If an error occurs while writing data to the output SPK file,
      !>         the error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See argument HANDLE.
      !>
      !>## Particulars
      !>
      !>     The exact structure of a segment of data type 20 is detailed in
      !>     the SPK Required Reading file.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     R.E. Thurman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 14-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Moved SPK
      !>        required reading from $Literature_References to
      !>        $Required_Reading section.
      !>
      !>-    SPICELIB Version 1.0.0, 23-DEC-2013 (NJB) (RET)
      module subroutine spks20 ( ctx, handle, baddr, eaddr, begin, end )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: j2000, spd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of source segment.
      integer(ip), intent(in) :: baddr  !! Beginning address of source segment.
      integer(ip), intent(in) :: eaddr  !! Ending address of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.
      real(wp) :: btime
      real(wp) :: data   ( bufsiz )
      real(wp) :: dscale
      real(wp) :: tscale
      real(wp) :: initjd
      real(wp) :: initfr
      real(wp) :: intlen
      real(wp) :: intrvl
      real(wp) :: subbeg
      real(wp) :: subifr
      real(wp) :: subijd
      integer(ip) :: recsiz
      integer(ip) :: nrec
      integer(ip) :: first
      integer(ip) :: last
      integer(ip) :: remain
      integer(ip) :: addr
      integer(ip) :: move
      if ( ctx%failed() ) return

!
!     The segment is made up of a number of logical records, each
!     having the same size, and covering the same length of time.
!
!     We can determine which record to return using the input epoch,
!     the integer and fractional parts of the initial time of the first
!     record's coverage interval, and the length of the interval
!     covered by each record. These constants are located at the end of
!     the segment, along with the size of each logical record and the
!     total number of records.
!
!     For convenience, we'll fetch the segment's distance and time
!     scales in the same call.
!
      call dafgda ( ctx, handle, eaddr-6, eaddr, data )

      dscale =      data( 1 )
      tscale =      data( 2 )
      initjd =      data( 3 )
      initfr =      data( 4 )
      intlen =      data( 5 )
      recsiz = int( data( 6 ) )
      nrec   = int( data( 7 ) )

      btime  = ( ( initjd - j2000 ) + initfr ) * spd
      intrvl = intlen * spd

      first = int( (begin - btime) / intrvl ) + 1
      first = max( 1,  min( first, nrec )  )

      last  = int( (end   - btime) / intrvl ) + 1
      last  = max( 1,  min( last,  nrec )  )

!
!     The number of records to be moved.
!
      nrec = last - first + 1

!
!     We're going to move the data in chunks of BUFSIZ d.p. words.
!     Compute the number of words left to move, the address of the
!     beginning of the records to move, and the number to move this
!     time.
!
      remain = nrec * recsiz
      addr   = baddr + ( first - 1 )*recsiz
      move   = min( bufsiz, remain )

      do while ( remain > 0 )

         call dafgda ( ctx, handle, addr, addr + move - 1, data )
         call dafada ( ctx, data, move )
         remain = remain - move
         addr   = addr   + move
         move   = min( bufsiz, remain )

      end do

!
!     That's all the records we have to move. But there are still seven
!     final numbers left to write:
!
!        1)  The distance scale (DSCALE).
!        2)  The time scale (TSCALE).
!        3)  The initial integer Julian date of the start time of the
!            first record.
!        4)  The fractional part of the state time of the first
!            record.
!        5)  The time interval length for each polynomial in days
!            (INTLEN).
!        6)  The record size (RECSIZ).
!        7)  The number of records (NREC).
!
!     Let SUBBEG be the subset begin time expressed as a TDB Julian
!     date.
!
      subbeg =  j2000  +  (  btime + ( first - 1 )*intrvl  ) / spd

      subijd =  aint( subbeg )
      subifr =  subbeg - subijd

      data( 1 ) = dscale
      data( 2 ) = tscale
      data( 3 ) = subijd
      data( 4 ) = subifr
      data( 5 ) = intlen
      data( 6 ) = real( recsiz, wp )
      data( 7 ) = real( nrec, wp   )

      call dafada ( ctx, data, 7 )

      return
      end subroutine spks20

      !> Extract a subset of the data in a SPK segment of type 21
      !> into a new segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE,
      !>     BADDR,
      !>     EADDR    are the file handle assigned to a SPK file, and the
      !>              beginning and ending addresses of a segment within
      !>              the file. Together they determine a complete set of
      !>              ephemeris data, from which a subset is to be
      !>              extracted.
      !>
      !>     BEGIN,
      !>     END      are the initial and final epochs (ephemeris time)
      !>              of the subset to be extracted.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs while reading data from the source SPK
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     2)  If an error occurs while writing data to the output SPK file,
      !>         the error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See argument HANDLE.
      !>
      !>## Particulars
      !>
      !>     The exact structure of a segment of data type 21 is detailed in
      !>     the SPK Required Reading file.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     F.T. Krogh         (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 14-OCT-2021 (JDR) (BVS)
      !>
      !>        Bug fix: fixed routine name in CHKIN/CHKOUT calls (SPKS01
      !>        -> SPKS21).
      !>
      !>        Edited the header to comply with NAIF standard. Moved SPK
      !>        required reading from $Literature_References to
      !>        $Required_Reading section.
      !>
      !>-    SPICELIB Version 1.0.0, 16-JAN-2014 (NJB) (FTK) (WLT) (IMU)
      module subroutine spks21 ( ctx, handle, baddr, eaddr, begin, end )
      use pepper_kinds, only: ip, wp
      use pepper_inc_spk21
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of source segment.
      integer(ip), intent(in) :: baddr  !! Beginning address of source segment.
      integer(ip), intent(in) :: eaddr  !! Ending address of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.
      integer(ip), parameter :: maxdsz = (4 * maxtrm) + 11
      real(wp) :: data     ( maxdsz )
      integer(ip) :: dlsize
      integer(ip) :: maxdim
      integer(ip) :: nrec
      integer(ip) :: ndir
      integer(ip) :: offe
      integer(ip) :: first
      integer(ip) :: last
      integer(ip) :: offset
      integer(ip) :: i
      if ( ctx%failed() ) return

!
!     Get the number of records in the segment. From that, we can
!     compute
!
!        NDIR      The number of directory epochs.
!
!        OFFE      The offset of the first epoch.
!
!     the number of directory epochs.
!
      call dafgda ( ctx, handle, eaddr-1, eaddr, data )

      maxdim = nint( data(1) )
      nrec   = nint( data(2) )

      ndir   = nrec / dirsiz
      offe   = eaddr - ndir - nrec - 2

!
!     Well, the new segment has already been begun. We just have to
!     decide what to move, and move it (using DAFADA).
!
!     Let's agree right now that speed is not of the greatest
!     importance here. We can probably do this with two passes
!     through the record epochs, and one pass through the records.
!
!        1) Determine the first and last records to be included
!           in the subset.
!
!        2) Move the records.
!
!        3) Write the epochs.
!
!     We can leap through the epochs one last time to get the
!     directory epochs.
!
!     First pass: which records are to be moved?
!
      first = 0
      last  = 0

      do i = 1, nrec

         call dafgda ( ctx, handle, offe+i, offe+i, data )

         if (       (  first   == 0     ) &
              .and. (  data(1) >= begin ) ) then

             first = i

         end if

         if (        ( first   /= 0   ) &
              .and.  ( last    == 0   ) &
              .and.  ( data(1) >= end )  ) then

            last = i

         end if

      end do

!
!     Second pass. Move the records.
!
      dlsize = ( 4 * maxdim ) + 11

      offset = (baddr - 1) + (first - 1) * dlsize

      do i = first, last

         call dafgda ( ctx, handle, offset+1, offset+dlsize, data         )
         call dafada ( ctx,                                  data, dlsize )

         offset = offset + dlsize

      end do

!
!     Third pass. Move the epochs.
!
      do i = first, last

         call dafgda ( ctx, handle, offe+i, offe+i, data    )
         call dafada ( ctx,                         data, 1 )

      end do

!
!     Get every DIRSIZ'th epoch for the directory.
!
      do i = (first + dirsiz - 1), last, dirsiz

         call dafgda ( ctx, handle, offe+i, offe+i, data    )
         call dafada ( ctx,                         data, 1 )

      end do

!
!     Add the maximum difference line dimension and the
!     number of records, and we're done.
!
      call dafada ( ctx, [ real( maxdim, wp ) ], 1 )

      data(1) = real( last - first + 1, wp )

      call dafada ( ctx, data, 1 )

      return
      end subroutine spks21

      !> Unpack the contents of an SPK segment descriptor.
      !>
      !>## Detailed Input
      !>
      !>     DESCR    is an SPK segment descriptor.
      !>
      !>## Detailed Output
      !>
      !>     BODY     is the NAIF ID code for the body of the segment.
      !>
      !>     CENTER   is the center of motion for BODY.
      !>
      !>     FRAME    is the SPICE integer code for the frame to which states
      !>              for the body are be referenced.
      !>
      !>     TYPE     is the type of SPK segment.
      !>
      !>     FIRST    is the first epoch for which the segment has
      !>              ephemeris data.
      !>
      !>     LAST     is the last epoch for which the segment has
      !>              ephemeris data.
      !>
      !>     BADDRS   is the starting address of the data associated
      !>              with this descriptor.
      !>
      !>     EADDRS   is the last address of the data associated with
      !>              this descriptor.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>     1)  If the input descriptor DESCR is invalid, it's possible for
      !>         the output times to contain bit patterns that don't represent
      !>         normal double precision values. This error is not diagnosed.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine extracts the contents of an SPK segment
      !>     descriptor into the components needed for reading and
      !>     evaluating the data stored in the segment. It serves
      !>     as a macro for expanding the SPK segment descriptor.
      !>
      !>## Examples
      !>
      !>     Suppose you wished to summarize a particular SPK segment
      !>     and that you have the descriptor for that segment in hand.
      !>     The following code fragment shows how you might use this
      !>     routine to create a summary message concerning the segment.
      !>
      !>        CALL SPKUDS ( DESCR, BODY,  CENTER, FRAME,
      !>       .              TYPE,  FIRST, LAST,   BADDR, EADDR )
      !>
      !>     Convert the start and stop times to ephemeris calendar strings
      !>
      !>        CALL ETCAL ( FIRST, FSTCAL )
      !>        CALL ETCAL ( LAST,  LSTCAL )
      !>
      !>        WRITE (*,*)
      !>        WRITE (*,*) 'Body     : ', BODY
      !>        WRITE (*,*) 'Center   : ', CENTER
      !>        WRITE (*,*) 'Frame ID : ', FRAME
      !>        WRITE (*,*) 'Data Type: ', TYPE
      !>        WRITE (*,*)
      !>        WRITE (*,*) 'Segment Start : ', FSTCAL
      !>        WRITE (*,*) 'Segment Stop  : ', LSTCAL
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 02-OCT-2021 (JDR) (NJB)
      !>
      !>        Changed output argument names "BEGIN" and "END" to "BADDRS" and
      !>        "EADDRS" for consistency with other routines.
      !>
      !>        Edited the header to comply with NAIF standard. Added entry
      !>        #1 to $Exceptions section and declared the routine error free.
      !>
      !>-    SPICELIB Version 1.0.0, 04-JAN-1994 (WLT) (KRG)
      module subroutine spkuds ( ctx, descr, body, center, frame, type, first, last, baddrs, eaddrs )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: descr ( * )  !! An SPK segment descriptor.
      integer(ip), intent(out) :: body  !! The NAIF ID code for the body of the segment.
      integer(ip), intent(out) :: center  !! The center of motion for BODY.
      integer(ip), intent(out) :: frame  !! The code for the frame of this segment.
      integer(ip), intent(out) :: type  !! The type of SPK segment.
      real(wp), intent(out) :: first  !! The first epoch for which the segment is valid.
      real(wp), intent(out) :: last  !! The last  epoch for which the segment is valid.
      integer(ip), intent(out) :: baddrs  !! Beginning DAF address of the segment.
      integer(ip), intent(out) :: eaddrs  !! Ending DAF address of the segment.

      real(wp) :: dppart ( nd )

      integer(ip) :: ipart  ( ni )

!
!     Standard introductory error handling preparations.
!
      if ( ctx%failed() ) return

!
!     No judgments are made about the descriptor when we
!     unpack it.  If things were done right when the descriptor
!     was created, it should be fine now.
!
      call dafus ( ctx, descr, nd, ni, dppart, ipart )

      if ( ctx%failed() ) return

      body   = ipart(1)
      center = ipart(2)
      frame  = ipart(3)
      type   = ipart(4)
      baddrs = ipart(5)
      eaddrs = ipart(6)

      first  = dppart(1)
      last   = dppart(2)

      return

      end subroutine spkuds

      !> Correct a state transformation matrix for the rate of change of
      !> light time.
      !>
      !>## Detailed Input
      !>
      !>     XMIT           is a logical flag indicating the sense of
      !>                    radiation transmission associated with
      !>                    the light time correction: XMIT is .TRUE.
      !>                    for transmission corrections and .FALSE.
      !>                    for reception corrections. See the header
      !>                    of SPKEZR for a detailed discussion of
      !>                    light time corrections.
      !>
      !>     DLT            is the derivative of one way light time measured
      !>                    in TDB seconds with respect to TDB. DLT is
      !>                    signed and unitless.
      !>
      !>     XFORM          is a 6x6 state transformation matrix. XFORM
      !>                    may transform states from an inertial frame to a
      !>                    body-fixed frame or vice versa. XFORM has the form
      !>
      !>                        -               -
      !>                       |         :       |
      !>                       |  R(t)   :   0   |
      !>                       |........ :.......|
      !>                       |         :       |
      !>                       | d(R)/dt :  R(t) |
      !>                       |         :       |
      !>                        -               -
      !>
      !>                    where R(t) is a time-dependent rotation matrix.
      !>
      !>## Detailed Output
      !>
      !>     CORXFM         is the input matrix XFORM after correction for the
      !>                    rate of change of light time indicated by DLT. Let
      !>                    LTSIGN be 1 for transmission corrections and -1
      !>                    for reception corrections. Then CORXFM has the
      !>                    form
      !>
      !>                        -                        -
      !>                       |             :            |
      !>                       |     R(t)    :     0      |
      !>                       |.............:............|
      !>                       |             :            |
      !>                       | S * d(R)/dt :    R(t)    |
      !>                       |             :            |
      !>                        -                        -
      !>
      !>                    where
      !>
      !>                       S = 1 + LTSIGN*DLT
      !>
      !>                    CORXFM may be used to transform state vectors
      !>                    between an inertial reference frame and a
      !>                    body-fixed reference frame associated with a
      !>                    light-time corrected epoch. See the Particulars
      !>                    section for details.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This is a utility routine designed to simplify transformation of
      !>     state vectors between an inertial and a body-fixed reference
      !>     frame, where the evaluation epoch of the body-fixed frame is
      !>     adjusted by a light time value.
      !>
      !>     For example, suppose the aberration-corrected velocity of a
      !>     target relative to an observer is to be transformed from an
      !>     inertial reference frame into a target centered, target
      !>     body-fixed reference frame, where the orientation of this frame
      !>     is to be corrected for one-way light time between a surface point
      !>     on the target body and the observer.
      !>
      !>     In the discussion below, we use ET as a synonym for TDB, since
      !>     this terminology is used throughout the SPICE system.
      !>
      !>     The orientation of the reference frame can be expressed as
      !>
      !>        R ( ET + LTSIGN*LT(ET) )
      !>
      !>     where R is a rotation matrix, ET is the TDB epoch associated with
      !>     an observer, LT(ET) is the light time magnitude associated with
      !>     the epoch ET at the observer, and LTSIGN is the sign of the light
      !>     time; LTSIGN is negative for reception case corrections.
      !>
      !>     The expression
      !>
      !>        ET + LTSIGN*LT(ET)
      !>
      !>     represents the light time corrected epoch. Then, according to the
      !>     chain rule, the derivative with respect to ET of R is
      !>
      !>               |
      !>        d(R)/dt|                   * ( 1 + LTSIGN*d(LT)/d(ET) )
      !>               |ET + LTSIGN*LT(ET)
      !>
      !>     In the expression above, the factor on the left is the rotation
      !>     derivative that could be obtained by calling SXFORM to look up
      !>     the inertial-to-body-fixed state transformation matrix at the
      !>     epoch
      !>
      !>        ET + LTSIGN*LT(ET)
      !>
      !>     This is the rotation derivative that would apply if light
      !>     time were constant.
      !>
      !>     The factor on the right is the scale factor S shown in the
      !>     Detailed Output section above.
      !>
      !>## Examples
      !>
      !>     1) Express the velocity of Mars as seen from Earth in
      !>        the IAU_MARS reference frame, where the frame orientation is
      !>        corrected for light time. Contrast the results obtained
      !>        using uncorrected and corrected state transformation matrices.
      !>        Show that the result obtained using a corrected matrix
      !>        matches that obtained from SPKEZR.
      !>
      !>        Note that, while the velocity we'll compute is not physically
      !>        realistic, it's perfectly usable for computations such as
      !>        finding the velocity of the apparent sub-Earth point on Mars.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: zzcorsxf_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00008.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0008.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00008.tpc',
      !>                                  'naif0008.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      DLT
      !>      DOUBLE PRECISION      XFORM  ( 6, 6 )
      !>      DOUBLE PRECISION      CORXFM ( 6, 6 )
      !>      DOUBLE PRECISION      STATE0 ( 6 )
      !>      DOUBLE PRECISION      STATE1 ( 6 )
      !>      DOUBLE PRECISION      STATE2 ( 6 )
      !>      DOUBLE PRECISION      STATE3 ( 6 )
      !>      DOUBLE PRECISION      VELDIF ( 3 )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'corsxf_ex1.tm' )
      !>
      !>C
      !>C     Convert an observation epoch to TDB.
      !>C
      !>      CALL STR2ET ( '2008 MAR 23', ET )
      !>
      !>C
      !>C     Look up the aberration-corrected state
      !>C     of Mars as seen from the Earth at ET
      !>C     in the J2000 frame. Use SPKACS since this
      !>C     routine returns the light time derivative.
      !>C
      !>      CALL SPKACS ( 499, ET,     'J2000', 'LT+S',
      !>     .              399, STATE0, LT,      DLT     )
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Mars-Earth light time derivative = ', DLT
      !>
      !>C
      !>C     Convert the state into the IAU_MARS frame at
      !>C     ET-LT. This gives us the state without accounting
      !>C     for the rate of change of light time.
      !>C
      !>      CALL SXFORM ( 'J2000', 'IAU_MARS', ET-LT, XFORM  )
      !>      CALL MXVG   ( XFORM,   STATE0,     6,  6, STATE1 )
      !>
      !>C
      !>C     Display the velocity portion of the state.
      !>C
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'IAU_MARS-relative velocity obtained '
      !>      WRITE (*,*) 'using SPKACS and SXFORM (km/s):'
      !>
      !>      WRITE (*, '(E24.16)' ) ( STATE1(I), I = 4, 6 )
      !>
      !>C
      !>C     Obtain the correct state transformation matrix
      !>C     from ZZCORSXF; transform the state using this matrix.
      !>C
      !>      CALL ZZCORSXF ( .FALSE., DLT,     XFORM, CORXFM )
      !>      CALL MXVG     ( CORXFM,   STATE0, 6,  6, STATE2 )
      !>
      !>C
      !>C     Display the velocity portion of the state.
      !>C
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'IAU_MARS-relative velocity obtained '
      !>     .//          'using ZZCORSXF (km/s):'
      !>
      !>      WRITE (*, '(E24.16)' ) ( STATE2(I), I = 4, 6 )
      !>
      !>C
      !>C     Display the velocity difference:
      !>C
      !>      CALL VSUB ( STATE2(4), STATE1(4), VELDIF )
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Velocity difference (km/s):'
      !>      WRITE (*, '(E24.16)' ) ( VELDIF(I), I = 1, 3 )
      !>
      !>C
      !>C     Look up the desired state using SPKEZR for comparison.
      !>C
      !>      CALL SPKEZR ( 'MARS',  ET,     'IAU_MARS', 'LT+S',
      !>     .              'EARTH', STATE3, LT                 )
      !>
      !>C
      !>C     Display the velocity portion of the state.
      !>C
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'IAU_MARS-relative velocity obtained '
      !>     .//          'using SPKEZR (km/s):'
      !>
      !>      WRITE (*, '(E24.16)' ) ( STATE3(I), I = 4, 6 )
      !>
      !>C
      !>C     Display the velocity difference:
      !>C
      !>      CALL VSUB ( STATE3(4), STATE2(4), VELDIF )
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'SPKEZR vs ZZCORSXF velocity difference (km/s):'
      !>      WRITE (*, '(E24.16)' ) ( VELDIF(I), I = 1, 3 )
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a PC/Linux/g77 system, the
      !>        output was
      !>
      !>           Mars-Earth light time derivative =   5.70610116E-05
      !>
      !>           IAU_MARS-relative velocity obtained
      !>           using SPKACS and SXFORM (km/s):
      !>            0.1094230439483713E+05
      !>           -0.7388150695390612E+04
      !>           -0.8550198289693935E+01
      !>
      !>           IAU_MARS-relative velocity obtained using ZZCORSXF (km/s):
      !>            0.1094167989684505E+05
      !>           -0.7387727898874676E+04
      !>           -0.8550198284585768E+01
      !>
      !>           Velocity difference (km/s):
      !>           -0.6244979920775222E+00
      !>            0.4227965159361702E+00
      !>            0.5108166334366615E-08
      !>
      !>           IAU_MARS-relative velocity obtained using SPKEZR (km/s):
      !>            0.1094167989684505E+05
      !>           -0.7387727898874676E+04
      !>           -0.8550198284585768E+01
      !>
      !>           SPKEZR vs ZZCORSXF velocity difference (km/s):
      !>            0.0000000000000000E+00
      !>            0.0000000000000000E+00
      !>            0.0000000000000000E+00
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 06-MAY-2008 (NJB)
      module subroutine zzcorsxf ( ctx, xmit, dlt, xform, corxfm )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      logical, intent(in) :: xmit  !! Radiation direction flag.
      real(wp), intent(in) :: dlt  !! Light time derivative with respect to TDB.
      real(wp), intent(in) :: xform  ( 6, 6 )  !! State transformation matrix.
      real(wp), intent(out) :: corxfm ( 6, 6 )  !! Corrected state transformation matrix.

      real(wp) :: ltsign
      real(wp) :: scale

      integer(ip) :: col

!
!     Determine the sign of the light time correction.
!
      if ( xmit ) then

         ltsign =  1.0_wp
      else
         ltsign = -1.0_wp
      end if

!
!     Since the only block we're changing is
!     the lower left, first copy the input matrix
!     to the output matrix.
!
      corxfm = xform

!
!     Adjust the rotation derivative block for
!     the rate of change of light time. All
!     that's required is to scale the block by
!
!        1 + LTSIGN*DLT
!
      scale = 1.0_wp + ltsign*dlt

      do col = 1, 3
!
!        Scale the vector starting at index
!        (4,COL) in place.
!
         corxfm(4:6,col) = scale*corxfm(4:6,col)

      end do

      end subroutine zzcorsxf

      !> Compute target state relative to its center of motion at
      !> a specified time, in a specified reference frame.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     ET          is the ephemeris time, expressed as seconds past
      !>                 J2000 TDB, at which to evaluate the constant-velocity
      !>                 ephemeris defined by the latest call to ZZCVSSTA.
      !>
      !>     REF         is name of a reference frame with respect to which
      !>                 the output state vector STATE is to be expressed.
      !>
      !>                 Case and leading and trailing blanks in REF are not
      !>                 significant.
      !>
      !>## Detailed Output
      !>
      !>     CENTER      is the NAIF ID code of the center of motion
      !>                 associated with the output state vector.
      !>
      !>     STATE       is a state vector. The contents of STATE are
      !>                 compatible with output states returned by SPKEZR: the
      !>                 first three components of STARG represent the x-, y-
      !>                 and z-components of the target's position; the last
      !>                 three components form the corresponding velocity
      !>                 vector.
      !>
      !>                 Units are always km and km/sec.
      !>
      !>                 STATE is obtained by applying linear extrapolation
      !>                 to the state stored by the latest call to ZZCVSSTA.
      !>                 The extrapolation is performed using the difference
      !>                 between ET and the epoch stored with the saved state.
      !>
      !>                 STATE contains the result of this extrapolation,
      !>                 expressed in the reference frame designated by the
      !>                 input REF. This frame's orientation is evaluated at
      !>                 the epoch ET.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If REF is not recognized, the error will be diagnosed by
      !>         routines in the call tree of this routine.
      !>
      !>     2)  If the loaded kernels provide insufficient data to compute
      !>         the requested state vector, the deficiency will be diagnosed
      !>         by a routine in the call tree of this routine.
      !>
      !>     3)  If an error occurs while reading a kernel file, the error
      !>         will be diagnosed by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data may be required to transform the stored state
      !>     to the output frame REF:
      !>
      !>        - PCK data: rotation data will be needed for
      !>          for any frame in the chain connecting the frame
      !>          of the stored state to that of the output state.
      !>
      !>        - Frame data: any frame definition required to compute
      !>          the transformation to the output frame must be known
      !>          to SPICE. If the definition is not built in, it must
      !>          be provided via a frame kernel.
      !>
      !>        - CK data: if a CK frame is required to compute the
      !>          transformation to the output frame, at least one CK file
      !>          will be needed.
      !>
      !>        - SCLK data: if a CK file is needed, an associated SCLK
      !>          kernel is required to enable conversion between encoded SCLK
      !>          (used to time-tag CK data) and barycentric dynamical time
      !>          (TDB).
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine returns the state vector stored by the entry point
      !>
      !>        ZZCVSSTA
      !>
      !>     after transforming the state to the reference frame REF.
      !>
      !>## Examples
      !>
      !>     See usage in CVOSTA, CVTSTA.
      !>
      !>## Restrictions
      !>
      !>     1) This routine can compute states based only on the most
      !>        recently stored state vector.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.0, 11-JAN-2012 (NJB)
      module subroutine zzcvxsta ( ctx, et, ref, center, state )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: mxvg
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      integer(ip), intent(out) :: center  !! ID code of center of motion.
      real(wp), intent(out) :: state ( 6 )  !! State vector.
      real(wp) :: delta
      real(wp) :: xstate ( 6 )
      real(wp) :: xf     ( 6, 6 )
      if ( .not. allocated ( ctx%zzcvstat_state ) ) then
         allocate ( ctx%zzcvstat_state )
         ctx%zzcvstat_state%svref = ' '
      end if
      associate ( svctr => ctx%zzcvstat_state%svctr, &
                  svet => ctx%zzcvstat_state%svet, &
                  svstat => ctx%zzcvstat_state%svstat )
      if ( ctx%failed() ) return

!
!     Extrapolate the saved state to the input time.
!
      delta = et - svet

      xstate(1:3) = 1.0_wp*svstat(1:3) + delta*svstat(4:6)

      xstate(4:6) = svstat(4:6)

!
!     Convert the extrapolated state to the requested frame
!     at ET.
!
      call sxform ( ctx, ctx%zzcvstat_state%svref, ref, et, xf )

      if ( ctx%failed() ) return

      call mxvg ( xf, xstate, 6, 6,  state )

!
!     Set the output center of motion argument as well.
!
      center = svctr

      return
      end associate
      end subroutine zzcvxsta

      !> Save an object's state and the center, time, and frame associated
      !> with the state.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     STATE       is a state vector. The contents of STATE are
      !>                 compatible with output states returned by SPKEZR.
      !>
      !>     CENTER      is the NAIF ID code of the center of motion associated
      !>                 with the input state vector.
      !>
      !>     ET          is the ephemeris time, expressed as seconds past
      !>                 J2000 TDB, associated with the input state.
      !>
      !>     REF         is name of a reference frame with respect to which
      !>                 the input STATE is expressed. This routine simply
      !>                 stores REF, so there are no restrictions on the
      !>                 contents of this string. However, at the time
      !>                 the companion entry point ZZCVXSTA is called, the
      !>                 frame designated by REF must be recognized by the
      !>                 SPICE system.
      !>
      !>## Detailed Output
      !>
      !>     None. This routine operates by side effects.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine stores its inputs so that they can be
      !>     used for linear extrapolation by the entry point
      !>
      !>        ZZCVXSTA
      !>
      !>## Examples
      !>
      !>     See usage in CVOSTA, CVTSTA.
      !>
      !>## Restrictions
      !>
      !>     1) This routine can store data for only one
      !>        constant-velocity ephemeris.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.0, 11-JAN-2012 (NJB)
      module subroutine zzcvssta ( ctx, state, center, et, ref )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      integer(ip), intent(in) :: center  !! ID code of center of motion.
      real(wp), intent(in) :: state ( 6 )  !! State vector.
      real(wp) :: delta
      real(wp) :: xstate ( 6 )
      real(wp) :: xf     ( 6, 6 )
      if ( .not. allocated ( ctx%zzcvstat_state ) ) then
         allocate ( ctx%zzcvstat_state )
         ctx%zzcvstat_state%svref = ' '
      end if
      associate ( svctr => ctx%zzcvstat_state%svctr, &
                  svet => ctx%zzcvstat_state%svet, &
                  svstat => ctx%zzcvstat_state%svstat )
      if ( ctx%failed() ) return

!
!     No SPICE errors are detected here, so we don't check in.
!
!     Save all inputs.
!
      svstat = state

      svctr = center
      svet  = et
      ctx%zzcvstat_state%svref = ref

      return
      end associate
      end subroutine zzcvssta

      !> Add data to a type 14 SPK segment associated with HANDLE.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the file handle of an SPK file that has been
      !>              opened for writing.
      !>
      !>     NCSETS   is the number of Chebyshev coefficient sets and epochs
      !>              to be stored in the segment.
      !>
      !>     COEFFS   is a time-ordered array of NCSETS of Chebyshev polynomial
      !>              coefficients to be placed in the segment of the SPK file.
      !>              Each set has size SETSZ = 2 + 6*(CHBDEG+1), where CHBDEG
      !>              is the degree of the Chebyshev polynomials used to
      !>              represent the ephemeris information.
      !>
      !>              These sets are used to compute the state vector, which
      !>              consists of position components X, Y, Z and velocity
      !>              components dX/dt, dY/dt, dZ/dt, of a body relative to
      !>              a center of motion.
      !>
      !>              See the $Particulars section for details on how to store
      !>              the coefficient sets in the array.
      !>
      !>     EPOCHS   contains the initial epochs (ephemeris seconds past
      !>              J2000) corresponding to the Chebyshev coefficients in
      !>              COEFFS. The I'th epoch is associated with the I'th
      !>              Chebyshev coefficient set. The epochs must form a
      !>              strictly increasing sequence.
      !>
      !>## Detailed Output
      !>
      !>     None. The ephemeris data is stored in a segment in the SPK file
      !>     associated with HANDLE.
      !>
      !>     See the $Particulars section for details about the structure of a
      !>     type 14 SPK segment.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the number of coefficient sets and epochs is not positive,
      !>         the error SPICE(INVALIDARGUMENT) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine adds data to a type 14 SPK segment that is associated
      !>     with HANDLE. The segment must have been started by a call to the
      !>     routine SPK14B, the routine which begins a type 14 SPK segment.
      !>
      !>     This routine is one of a set of three routines for creating and
      !>     adding data to type 14 SPK segments. These routines are:
      !>
      !>        SPK14B: Begin a type 14 SPK segment. This routine must be
      !>                called before any data may be added to a type 14
      !>                segment.
      !>
      !>        SPK14A: Add data to a type 14 SPK segment. This routine may be
      !>                called any number of times after a call to SPK14B to
      !>                add type 14 records to the SPK segment that was
      !>                started.
      !>
      !>        SPK14E: End a type 14 SPK segment. This routine is called to
      !>                make the type 14 segment a permanent addition to the
      !>                SPK file. Once this routine is called, no further type
      !>                14 records may be added to the segment. A new segment
      !>                must be started.
      !>
      !>     A type 14 SPK segment consists of coefficient sets for fixed order
      !>     Chebyshev polynomials over consecutive time intervals, where the
      !>     time intervals need not all be of the same length. The Chebyshev
      !>     polynomials represent the position, X, Y, and Z coordinates, and
      !>     the velocities, dX/dt, dY/dt, and dZ/dt, of BODY relative to
      !>     CENTER.
      !>
      !>     The ephemeris data supplied to the type 14 SPK writer is packed
      !>     into an array as a sequence of logical records,
      !>
      !>        -----------------------------------------------------
      !>        | Record 1 | Record 2 | ... | Record N-1 | Record N |
      !>        -----------------------------------------------------
      !>
      !>     with each record has the following format.
      !>
      !>           ------------------------------------------------
      !>           |  The midpoint of the approximation interval  |
      !>           ------------------------------------------------
      !>           |  The radius of the approximation interval    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the X coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Y coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Z coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the X velocity    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Y velocity    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Z velocity    |
      !>           ------------------------------------------------
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) This example demonstrates how to create an SPK type 14 kernel
      !>        containing only one segment, given a set of Chebyshev
      !>        coefficients and their associated epochs, if all of the data
      !>        for the segment is available at one time.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPK14A_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 42 )
      !>
      !>C
      !>C     Define the segment identifier parameters.
      !>C
      !>      CHARACTER*(*)         SPK14
      !>      PARAMETER           ( SPK14  = 'spk14a_ex1.bsp' )
      !>
      !>      CHARACTER*(*)         REF
      !>      PARAMETER           ( REF    = 'J2000'          )
      !>
      !>      INTEGER               BODY
      !>      PARAMETER           ( BODY   = 3  )
      !>
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER = 10 )
      !>
      !>      INTEGER               CHBDEG
      !>      PARAMETER           ( CHBDEG = 2  )
      !>
      !>      INTEGER               NRECS
      !>      PARAMETER           ( NRECS  = 4  )
      !>
      !>      INTEGER               RECSIZ
      !>      PARAMETER           ( RECSIZ = 2 + 6*(CHBDEG+1) )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(NAMLEN)    SEGID
      !>
      !>      DOUBLE PRECISION      EPOCHS ( NRECS + 1 )
      !>      DOUBLE PRECISION      FIRST
      !>      DOUBLE PRECISION      LAST
      !>      DOUBLE PRECISION      RECRDS ( RECSIZ, NRECS )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               NCOMCH
      !>
      !>C
      !>C     Define the epochs and coefficients.
      !>C
      !>      DATA                  EPOCHS /
      !>     .                100.D0, 200.D0, 300.D0, 400.D0, 500.D0 /
      !>
      !>      DATA                  RECRDS /
      !>     .     150.0D0, 50.0D0, 1.0101D0, 1.0102D0, 1.0103D0,
      !>     .                      1.0201D0, 1.0202D0, 1.0203D0,
      !>     .                      1.0301D0, 1.0302D0, 1.0303D0,
      !>     .                      1.0401D0, 1.0402D0, 1.0403D0,
      !>     .                      1.0501D0, 1.0502D0, 1.0503D0,
      !>     .                      1.0601D0, 1.0602D0, 1.0603D0,
      !>     .     250.0D0, 50.0D0, 2.0101D0, 2.0102D0, 2.0103D0,
      !>     .                      2.0201D0, 2.0202D0, 2.0203D0,
      !>     .                      2.0301D0, 2.0302D0, 2.0303D0,
      !>     .                      2.0401D0, 2.0402D0, 2.0403D0,
      !>     .                      2.0501D0, 2.0502D0, 2.0503D0,
      !>     .                      2.0601D0, 2.0602D0, 2.0603D0,
      !>     .     350.0D0, 50.0D0, 3.0101D0, 3.0102D0, 3.0103D0,
      !>     .                      3.0201D0, 3.0202D0, 3.0203D0,
      !>     .                      3.0301D0, 3.0302D0, 3.0303D0,
      !>     .                      3.0401D0, 3.0402D0, 3.0403D0,
      !>     .                      3.0501D0, 3.0502D0, 3.0503D0,
      !>     .                      3.0601D0, 3.0602D0, 3.0603D0,
      !>     .     450.0D0, 50.0D0, 4.0101D0, 4.0102D0, 4.0103D0,
      !>     .                      4.0201D0, 4.0202D0, 4.0203D0,
      !>     .                      4.0301D0, 4.0302D0, 4.0303D0,
      !>     .                      4.0401D0, 4.0402D0, 4.0403D0,
      !>     .                      4.0501D0, 4.0502D0, 4.0503D0,
      !>     .                      4.0601D0, 4.0602D0, 4.0603D0 /
      !>
      !>C
      !>C     Set the start and end times of interval covered by
      !>C     segment.
      !>C
      !>      FIRST = EPOCHS(1)
      !>      LAST  = EPOCHS(NRECS + 1)
      !>
      !>C
      !>C     NCOMCH is the number of characters to reserve for the
      !>C     kernel's comment area. This example doesn't write
      !>C     comments, so set to zero.
      !>C
      !>      NCOMCH = 0
      !>
      !>C
      !>C     Internal file name and segment ID.
      !>C
      !>      IFNAME = 'Type 14 SPK internal file name.'
      !>      SEGID  = 'SPK type 14 test segment'
      !>
      !>C
      !>C     Open a new SPK file.
      !>C
      !>      CALL SPKOPN( SPK14, IFNAME, NCOMCH, HANDLE )
      !>
      !>C
      !>C     Begin the segment.
      !>C
      !>      CALL SPK14B ( HANDLE, SEGID, BODY, CENTER, REF,
      !>     .              FIRST,  LAST,  CHBDEG            )
      !>
      !>C
      !>C     Add the data to the segment all at once.
      !>C
      !>      CALL SPK14A ( HANDLE, NRECS, RECRDS, EPOCHS )
      !>
      !>C
      !>C     End the segment, making the segment a permanent addition
      !>C     to the SPK file.
      !>C
      !>      CALL SPK14E ( HANDLE )
      !>
      !>C
      !>C     Close the SPK file.
      !>C
      !>      CALL SPKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new SPK type 14 exists in
      !>        the output directory.
      !>
      !>     2) This example demonstrates how to add type 14 SPK records to the
      !>        segment being written, one at a time. The ability to write the
      !>        records in this way is useful if computer memory is limited. It
      !>        may also be convenient from a programming perspective to write
      !>        the records this way.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPK14A_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 42 )
      !>
      !>C
      !>C     Define the segment identifier parameters.
      !>C
      !>      CHARACTER*(*)         SPK14
      !>      PARAMETER           ( SPK14  = 'spk14a_ex2.bsp' )
      !>
      !>      CHARACTER*(*)         REF
      !>      PARAMETER           ( REF    = 'J2000'          )
      !>
      !>      INTEGER               BODY
      !>      PARAMETER           ( BODY   = 3  )
      !>
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER = 10 )
      !>
      !>      INTEGER               CHBDEG
      !>      PARAMETER           ( CHBDEG = 2  )
      !>
      !>      INTEGER               NRECS
      !>      PARAMETER           ( NRECS  = 4  )
      !>
      !>      INTEGER               RECSIZ
      !>      PARAMETER           ( RECSIZ = 2 + 6*(CHBDEG+1) )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(NAMLEN)    SEGID
      !>
      !>      DOUBLE PRECISION      EPOCHS ( NRECS + 1 )
      !>      DOUBLE PRECISION      FIRST
      !>      DOUBLE PRECISION      LAST
      !>      DOUBLE PRECISION      RECRDS ( RECSIZ, NRECS )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               NCOMCH
      !>
      !>C
      !>C     Define the epochs and coefficients.
      !>C
      !>      DATA                  EPOCHS /
      !>     .                100.D0, 200.D0, 300.D0, 400.D0, 500.D0 /
      !>
      !>      DATA                  RECRDS /
      !>     .     150.0D0, 50.0D0, 1.0101D0, 1.0102D0, 1.0103D0,
      !>     .                      1.0201D0, 1.0202D0, 1.0203D0,
      !>     .                      1.0301D0, 1.0302D0, 1.0303D0,
      !>     .                      1.0401D0, 1.0402D0, 1.0403D0,
      !>     .                      1.0501D0, 1.0502D0, 1.0503D0,
      !>     .                      1.0601D0, 1.0602D0, 1.0603D0,
      !>     .     250.0D0, 50.0D0, 2.0101D0, 2.0102D0, 2.0103D0,
      !>     .                      2.0201D0, 2.0202D0, 2.0203D0,
      !>     .                      2.0301D0, 2.0302D0, 2.0303D0,
      !>     .                      2.0401D0, 2.0402D0, 2.0403D0,
      !>     .                      2.0501D0, 2.0502D0, 2.0503D0,
      !>     .                      2.0601D0, 2.0602D0, 2.0603D0,
      !>     .     350.0D0, 50.0D0, 3.0101D0, 3.0102D0, 3.0103D0,
      !>     .                      3.0201D0, 3.0202D0, 3.0203D0,
      !>     .                      3.0301D0, 3.0302D0, 3.0303D0,
      !>     .                      3.0401D0, 3.0402D0, 3.0403D0,
      !>     .                      3.0501D0, 3.0502D0, 3.0503D0,
      !>     .                      3.0601D0, 3.0602D0, 3.0603D0,
      !>     .     450.0D0, 50.0D0, 4.0101D0, 4.0102D0, 4.0103D0,
      !>     .                      4.0201D0, 4.0202D0, 4.0203D0,
      !>     .                      4.0301D0, 4.0302D0, 4.0303D0,
      !>     .                      4.0401D0, 4.0402D0, 4.0403D0,
      !>     .                      4.0501D0, 4.0502D0, 4.0503D0,
      !>     .                      4.0601D0, 4.0602D0, 4.0603D0 /
      !>
      !>C
      !>C     Set the start and end times of interval covered by
      !>C     segment.
      !>C
      !>      FIRST = EPOCHS(1)
      !>      LAST  = EPOCHS(NRECS + 1)
      !>
      !>C
      !>C     NCOMCH is the number of characters to reserve for the
      !>C     kernel's comment area. This example doesn't write
      !>C     comments, so set to zero.
      !>C
      !>      NCOMCH = 0
      !>
      !>C
      !>C     Internal file name and segment ID.
      !>C
      !>      IFNAME = 'Type 14 SPK internal file name.'
      !>      SEGID  = 'SPK type 14 test segment'
      !>
      !>C
      !>C     Open a new SPK file.
      !>C
      !>      CALL SPKOPN( SPK14, IFNAME, NCOMCH, HANDLE )
      !>
      !>C
      !>C     Begin the segment.
      !>C
      !>      CALL SPK14B ( HANDLE, SEGID, BODY, CENTER, REF,
      !>     .              FIRST,  LAST,  CHBDEG            )
      !>
      !>C
      !>C     Write the records to the segment in the
      !>C     SPK file one at at time.
      !>C
      !>      DO I = 1, NRECS
      !>
      !>         CALL SPK14A ( HANDLE, 1, RECRDS(1,I), EPOCHS(I) )
      !>
      !>      END DO
      !>
      !>C
      !>C     End the segment, making the segment a permanent addition
      !>C     to the SPK file.
      !>C
      !>      CALL SPK14E ( HANDLE )
      !>
      !>C
      !>C     Close the SPK file.
      !>C
      !>      CALL SPKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new SPK type 14 exists in
      !>        the output directory.
      !>
      !>## Restrictions
      !>
      !>     1)  The type 14 SPK segment to which we are adding data must have
      !>         been started by the routine SPK14B, the routine which begins a
      !>         type 14 SPK segment.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 27-AUG-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard. Added
      !>        complete examples code from existing fragments.
      !>
      !>        Extended COEFFS argument description to provide the size of
      !>        the Chebyshev polynomials sets.
      !>
      !>        Re-ordered header sections. Removed references to other
      !>        routines from $Abstract section (present in $Particulars).
      !>
      !>-    SPICELIB Version 1.1.0, 07-SEP-2001 (EDW)
      !>
      !>        Removed DAFHLU call; replaced ERRFN call with ERRHAN.
      !>
      !>-    SPICELIB Version 1.0.0, 06-MAR-1995 (KRG)
      module subroutine spk14a ( ctx, handle, ncsets, coeffs, epochs )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! The handle of an SPK file open for writing.
      integer(ip), intent(in) :: ncsets  !! The number of coefficient sets and epochs.
      real(wp), intent(in) :: coeffs ( * )  !! The collection of coefficient sets.
      real(wp), intent(in) :: epochs ( * )  !! The epochs associated with the coefficient sets.

!
!     Standard SPICELIB error handling.
!
      if ( ctx%failed() ) return

!
!     First, check to see if the number of coefficient sets and epochs
!     is positive.
!
      if ( ncsets <= 0 ) then

         call ctx%setmsg ( 'The number of coefficient sets and epochs' &
         //            ' to be added to the SPK segment in the file' &
         //            ' ''#'' was not positive. Its value was: #.'  )
         call ctx%errhan ( '#', handle                                   )
         call ctx%errint ( '#', ncsets                                   )
         call ctx%sigerr ( 'SPICE(INVALIDARGUMENT)'                      )
         return

      end if

!
!     Add the data.
!
      call sgwfpk ( ctx, handle, ncsets, coeffs, ncsets, epochs )

!
!     No need to check FAILED() here, since all we do is check out.
!     Leave it up to the caller.
!

      return

      end subroutine spk14a

      !> Begin a type 14 SPK segment in the SPK file associated with
      !> HANDLE.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the file handle of an SPK file that has been
      !>              opened for writing.
      !>
      !>     SEGID    is the segment identifier. An SPK segment identifier
      !>              may contain up to 40 printing ASCII characters.
      !>
      !>     BODY     is the SPICE ID for the body whose states are
      !>              to be recorded in an SPK file.
      !>
      !>     CENTER   is the SPICE ID for the center of motion associated
      !>              with BODY.
      !>
      !>     FRAME    is the reference frame that states are referenced to,
      !>              for example 'J2000'.
      !>
      !>     FIRST    is the starting epoch, in seconds past J2000, for
      !>              the ephemeris data to be placed into the segment.
      !>
      !>     LAST     is the ending epoch, in seconds past J2000, for
      !>              the ephemeris data to be placed into the segment.
      !>
      !>     CHBDEG   is the degree of the Chebyshev Polynomials used to
      !>              represent the ephemeris information stored in the
      !>              segment.
      !>
      !>## Detailed Output
      !>
      !>     None. The input data is used to create the segment summary for the
      !>     segment being started in the SPK file associated with HANDLE.
      !>
      !>     See the $Particulars section for details about the structure of a
      !>     type 14 SPK segment.
      !>
      !>## Parameters
      !>
      !>     This subroutine makes use of parameters defined in the file
      !>     'sgparam.inc'.
      !>
      !>## Exceptions
      !>
      !>     1)  If the degree of the Chebyshev Polynomial to be used for this
      !>         segment is negative, the error SPICE(INVALIDARGUMENT) is
      !>         signaled.
      !>
      !>     2)  If there are issues in the structure or content of the inputs
      !>         other than the degree of the Chebyshev Polynomial, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     3)  If a file access error occurs, the error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     See HANDLE in the $Detailed_Input section.
      !>
      !>## Particulars
      !>
      !>     This routine begins writing a type 14 SPK segment to the open SPK
      !>     file that is associated with HANDLE. The file must have been
      !>     opened with write access.
      !>
      !>     This routine is one of a set of three routines for creating and
      !>     adding data to type 14 SPK segments. These routines are:
      !>
      !>        SPK14B: Begin a type 14 SPK segment. This routine must be
      !>                called before any data may be added to a type 14
      !>                segment.
      !>
      !>        SPK14A: Add data to a type 14 SPK segment. This routine may be
      !>                called any number of times after a call to SPK14B to
      !>                add type 14 records to the SPK segment that was
      !>                started.
      !>
      !>        SPK14E: End a type 14 SPK segment. This routine is called to
      !>                make the type 14 segment a permanent addition to the
      !>                SPK file. Once this routine is called, no further type
      !>                14 records may be added to the segment. A new segment
      !>                must be started.
      !>
      !>     A type 14 SPK segment consists of coefficient sets for fixed order
      !>     Chebyshev polynomials over consecutive time intervals, where the
      !>     time intervals need not all be of the same length. The Chebyshev
      !>     polynomials represent the position, X, Y, and Z coordinates, and
      !>     the velocities, dX/dt, dY/dt, and dZ/dt, of BODY relative to
      !>     CENTER.
      !>
      !>     The ephemeris data supplied to the type 14 SPK writer is packed
      !>     into an array as a sequence of records,
      !>
      !>        -----------------------------------------------------
      !>        | Record 1 | Record 2 | ... | Record N-1 | Record N |
      !>        -----------------------------------------------------
      !>
      !>     with each record has the following format.
      !>
      !>           ------------------------------------------------
      !>           |  The midpoint of the approximation interval  |
      !>           ------------------------------------------------
      !>           |  The radius of the approximation interval    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the X coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Y coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Z coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the X velocity    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Y velocity    |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Z velocity    |
      !>           ------------------------------------------------
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) This example demonstrates how to create an SPK type 14 kernel
      !>        containing only one segment, given a set of Chebyshev
      !>        coefficients and their associated epochs.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPK14B_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 42 )
      !>
      !>C
      !>C     Define the segment identifier parameters.
      !>C
      !>      CHARACTER*(*)         SPK14
      !>      PARAMETER           ( SPK14  = 'spk14b_ex1.bsp' )
      !>
      !>      CHARACTER*(*)         REF
      !>      PARAMETER           ( REF    = 'J2000'          )
      !>
      !>      INTEGER               BODY
      !>      PARAMETER           ( BODY   = 3  )
      !>
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER = 10 )
      !>
      !>      INTEGER               CHBDEG
      !>      PARAMETER           ( CHBDEG = 2  )
      !>
      !>      INTEGER               NRECS
      !>      PARAMETER           ( NRECS  = 4  )
      !>
      !>      INTEGER               RECSIZ
      !>      PARAMETER           ( RECSIZ = 2 + 6*(CHBDEG+1) )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(NAMLEN)    SEGID
      !>
      !>      DOUBLE PRECISION      EPOCHS ( NRECS + 1 )
      !>      DOUBLE PRECISION      FIRST
      !>      DOUBLE PRECISION      LAST
      !>      DOUBLE PRECISION      RECRDS ( RECSIZ, NRECS )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               NCOMCH
      !>
      !>C
      !>C     Define the epochs and coefficients.
      !>C
      !>      DATA                  EPOCHS /
      !>     .                100.D0, 200.D0, 300.D0, 400.D0, 500.D0 /
      !>
      !>      DATA                  RECRDS /
      !>     .     150.0D0, 50.0D0, 1.0101D0, 1.0102D0, 1.0103D0,
      !>     .                      1.0201D0, 1.0202D0, 1.0203D0,
      !>     .                      1.0301D0, 1.0302D0, 1.0303D0,
      !>     .                      1.0401D0, 1.0402D0, 1.0403D0,
      !>     .                      1.0501D0, 1.0502D0, 1.0503D0,
      !>     .                      1.0601D0, 1.0602D0, 1.0603D0,
      !>     .     250.0D0, 50.0D0, 2.0101D0, 2.0102D0, 2.0103D0,
      !>     .                      2.0201D0, 2.0202D0, 2.0203D0,
      !>     .                      2.0301D0, 2.0302D0, 2.0303D0,
      !>     .                      2.0401D0, 2.0402D0, 2.0403D0,
      !>     .                      2.0501D0, 2.0502D0, 2.0503D0,
      !>     .                      2.0601D0, 2.0602D0, 2.0603D0,
      !>     .     350.0D0, 50.0D0, 3.0101D0, 3.0102D0, 3.0103D0,
      !>     .                      3.0201D0, 3.0202D0, 3.0203D0,
      !>     .                      3.0301D0, 3.0302D0, 3.0303D0,
      !>     .                      3.0401D0, 3.0402D0, 3.0403D0,
      !>     .                      3.0501D0, 3.0502D0, 3.0503D0,
      !>     .                      3.0601D0, 3.0602D0, 3.0603D0,
      !>     .     450.0D0, 50.0D0, 4.0101D0, 4.0102D0, 4.0103D0,
      !>     .                      4.0201D0, 4.0202D0, 4.0203D0,
      !>     .                      4.0301D0, 4.0302D0, 4.0303D0,
      !>     .                      4.0401D0, 4.0402D0, 4.0403D0,
      !>     .                      4.0501D0, 4.0502D0, 4.0503D0,
      !>     .                      4.0601D0, 4.0602D0, 4.0603D0 /
      !>
      !>C
      !>C     Set the start and end times of interval covered by
      !>C     segment.
      !>C
      !>      FIRST = EPOCHS(1)
      !>      LAST  = EPOCHS(NRECS + 1)
      !>
      !>C
      !>C     NCOMCH is the number of characters to reserve for the
      !>C     kernel's comment area. This example doesn't write
      !>C     comments, so set to zero.
      !>C
      !>      NCOMCH = 0
      !>
      !>C
      !>C     Internal file name and segment ID.
      !>C
      !>      IFNAME = 'Type 14 SPK internal file name.'
      !>      SEGID  = 'SPK type 14 test segment'
      !>
      !>C
      !>C     Open a new SPK file.
      !>C
      !>      CALL SPKOPN( SPK14, IFNAME, NCOMCH, HANDLE )
      !>
      !>C
      !>C     Begin the segment.
      !>C
      !>      CALL SPK14B ( HANDLE, SEGID, BODY, CENTER, REF,
      !>     .              FIRST,  LAST,  CHBDEG            )
      !>
      !>C
      !>C     Add the data to the segment all at once.
      !>C
      !>      CALL SPK14A ( HANDLE, NRECS, RECRDS, EPOCHS )
      !>
      !>C
      !>C     End the segment, making the segment a permanent addition
      !>C     to the SPK file.
      !>C
      !>      CALL SPK14E ( HANDLE )
      !>
      !>C
      !>C     Close the SPK file.
      !>C
      !>      CALL SPKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new SPK type 14 exists in
      !>        the output directory.
      !>
      !>## Restrictions
      !>
      !>     1)  The SPK file must be open with write access.
      !>
      !>     2)  Only one segment may be written to a particular SPK file at a
      !>         time. All of the data for the segment must be written and the
      !>         segment must be ended before another segment may be started in
      !>         the file.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.3, 27-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Added
      !>        complete example code from existing fragment.
      !>
      !>        Removed references to other routines from $Abstract section
      !>        (present in $Particulars).
      !>
      !>-    SPICELIB Version 1.0.2, 10-FEB-2014 (BVS)
      !>
      !>        Removed comments from the $Declarations section.
      !>
      !>-    SPICELIB Version 1.0.1, 30-OCT-2006 (BVS)
      !>
      !>        Deleted "inertial" from the FRAME description in the $Brief_I/O
      !>        section of the header.
      !>
      !>-    SPICELIB Version 1.0.0, 06-MAR-1995 (KRG)
      module subroutine spk14b ( ctx, handle, segid, body, center, frame, first, last, chbdeg )
      use pepper_kinds, only: ip, wp
      use pepper_inc_sgparam
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! The handle of an SPK file open for writing.
      character(*), intent(in) :: segid  !! The string to use for segment identifier.
      integer(ip), intent(in) :: body  !! The NAIF ID code for the body of the segment.
      integer(ip), intent(in) :: center  !! The center of motion for BODY.
      character(*), intent(in) :: frame  !! The reference frame for this segment.
      real(wp), intent(in) :: first  !! The first epoch for which the segment is valid.
      real(wp), intent(in) :: last  !! The last epoch for which the segment is valid.
      integer(ip), intent(in) :: chbdeg  !! The degree of the Chebyshev Polynomial used.

!
!     Length of an SPK descriptor.
!
      integer(ip), parameter :: ndescr = nd + (ni+1)/2
!
!     The type of this segment
!
      integer(ip), parameter :: type = 14
!
!     The number of constants:
!
      integer(ip), parameter :: nconst = 1
      real(wp) :: dcoeff
      real(wp) :: descr(ndescr)

      integer(ip) :: ncoeff
      integer(ip) :: pktsiz
!
!     Standard SPICELIB error handling.
!
      if ( ctx%failed() ) return
!
!     First, check the degree of the polynomial to be sure that it is
!     not negative.
!
      if ( chbdeg < 0 ) then

         call ctx%setmsg ( 'The degree of the Chebyshev Polynomial'  // &
                       ' was negative, #. The degree of the'     // &
                       ' polynomial must be greater than or'     // &
                       ' equal to zero.'                          )
         call ctx%errint ( '#', chbdeg                                )
         call ctx%sigerr ( 'SPICE(INVALIDARGUMENT)'                   )
         return

      end if
!
!     Create a descriptor for the segment we are about to write.
!
      call spkpds ( ctx, body,  center, frame, type, first, last, descr )

      if ( ctx%failed() ) return
!
!     We've got a valid descriptor, so compute a few things and begin
!     the segment.
!
      ncoeff = chbdeg + 1
      pktsiz = nstate * ncoeff + 2
      dcoeff = real( ncoeff, wp )
!
!     For this data type, we want to use an explicit reference value
!     index where the reference epochs are in increasing order. We also
!     want to have as the index for a particular request epoch the index
!     of the greatest reference epoch less than or equal to the request
!     epoch. These characteristics are prescribed by the mnemonic EXPLE.
!     See the include file 'sgparam.inc' for more details.
!
      call sgbwfs ( ctx, handle, descr, segid, nconst, [ dcoeff ], [ pktsiz ], exple )

!
!     No need to check FAILED() here, since all we do is check out.
!     Leave it up to the caller.
!

      return

      end subroutine spk14b

      !> End the type 14 SPK segment currently being written to the SPK
      !> file associated with HANDLE.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the file handle of an SPK file that has been
      !>              opened for writing, and to which a type 14 segment is
      !>              being written.
      !>
      !>## Detailed Output
      !>
      !>     None. The type 14 segment in the SPK file associated with HANDLE
      !>     will be ended, making the addition of the data to the file
      !>     permanent.
      !>
      !>     See the $Particulars section for details about the structure of a
      !>     type 14 SPK segment.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If there are no segments currently being written to the file
      !>         associated with HANDLE, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     2)  If any file access error occurs, the error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     See the argument HANDLE.
      !>
      !>## Particulars
      !>
      !>     This routine ends a type 14 SPK segment which is being written to
      !>     the SPK file associated with HANDLE. Ending the SPK segment is a
      !>     necessary step in the process of making the data a permanent part
      !>     of the SPK file.
      !>
      !>     This routine is one of a set of three routines for creating and
      !>     adding data to type 14 SPK segments. These routines are:
      !>
      !>        SPK14B: Begin a type 14 SPK segment. This routine must be
      !>                called before any data may be added to a type 14
      !>                segment.
      !>
      !>        SPK14A: Add data to a type 14 SPK segment. This routine may be
      !>                called any number of times after a call to SPK14B to
      !>                add type 14 records to the SPK segment that was
      !>                started.
      !>
      !>        SPK14E: End a type 14 SPK segment. This routine is called to
      !>                make the type 14 segment a permanent addition to the
      !>                SPK file. Once this routine is called, no further type
      !>                14 records may be added to the segment. A new segment
      !>                must be started.
      !>
      !>     A type 14 SPK segment consists of coefficient sets for fixed order
      !>     Chebyshev polynomials over consecutive time intervals, where the
      !>     time intervals need not all be of the same length. The Chebyshev
      !>     polynomials represent the position, X, Y, and Z coordinates, and
      !>     the velocities, dX/dt, dY/dt, and dZ/dt, of BODY relative to
      !>     CENTER.
      !>
      !>     The ephemeris data supplied to the type 14 SPK writer is packed
      !>     into an array as a sequence of logical records,
      !>
      !>        -----------------------------------------------------
      !>        | Record 1 | Record 2 | ... | Record N-1 | Record N |
      !>        -----------------------------------------------------
      !>
      !>     with each record has the following format.
      !>
      !>           ------------------------------------------------
      !>           |  the midpoint of the approximation interval  |
      !>           ------------------------------------------------
      !>           |   the radius of the approximation interval   |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the X coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Y coordinate  |
      !>           ------------------------------------------------
      !>           |  CHBDEG+1 coefficients for the Z coordinate  |
      !>           ------------------------------------------------
      !>           |   CHBDEG+1 coefficients for the X velocity   |
      !>           ------------------------------------------------
      !>           |   CHBDEG+1 coefficients for the Y velocity   |
      !>           ------------------------------------------------
      !>           |   CHBDEG+1 coefficients for the Z velocity   |
      !>           ------------------------------------------------
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) This example demonstrates how to create an SPK type 14 kernel
      !>        containing only one segment, given a set of Chebyshev
      !>        coefficients and their associated epochs.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPK14E_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 42 )
      !>
      !>C
      !>C     Define the segment identifier parameters.
      !>C
      !>      CHARACTER*(*)         SPK14
      !>      PARAMETER           ( SPK14  = 'spk14e_ex1.bsp' )
      !>
      !>      CHARACTER*(*)         REF
      !>      PARAMETER           ( REF    = 'J2000'          )
      !>
      !>      INTEGER               BODY
      !>      PARAMETER           ( BODY   = 3  )
      !>
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER = 10 )
      !>
      !>      INTEGER               CHBDEG
      !>      PARAMETER           ( CHBDEG = 2  )
      !>
      !>      INTEGER               NRECS
      !>      PARAMETER           ( NRECS  = 4  )
      !>
      !>      INTEGER               RECSIZ
      !>      PARAMETER           ( RECSIZ = 2 + 6*(CHBDEG+1) )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(NAMLEN)    SEGID
      !>
      !>      DOUBLE PRECISION      EPOCHS ( NRECS + 1 )
      !>      DOUBLE PRECISION      FIRST
      !>      DOUBLE PRECISION      LAST
      !>      DOUBLE PRECISION      RECRDS ( RECSIZ, NRECS )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               NCOMCH
      !>
      !>C
      !>C     Define the epochs and coefficients.
      !>C
      !>      DATA                  EPOCHS /
      !>     .                100.D0, 200.D0, 300.D0, 400.D0, 500.D0 /
      !>
      !>      DATA                  RECRDS /
      !>     .     150.0D0, 50.0D0, 1.0101D0, 1.0102D0, 1.0103D0,
      !>     .                      1.0201D0, 1.0202D0, 1.0203D0,
      !>     .                      1.0301D0, 1.0302D0, 1.0303D0,
      !>     .                      1.0401D0, 1.0402D0, 1.0403D0,
      !>     .                      1.0501D0, 1.0502D0, 1.0503D0,
      !>     .                      1.0601D0, 1.0602D0, 1.0603D0,
      !>     .     250.0D0, 50.0D0, 2.0101D0, 2.0102D0, 2.0103D0,
      !>     .                      2.0201D0, 2.0202D0, 2.0203D0,
      !>     .                      2.0301D0, 2.0302D0, 2.0303D0,
      !>     .                      2.0401D0, 2.0402D0, 2.0403D0,
      !>     .                      2.0501D0, 2.0502D0, 2.0503D0,
      !>     .                      2.0601D0, 2.0602D0, 2.0603D0,
      !>     .     350.0D0, 50.0D0, 3.0101D0, 3.0102D0, 3.0103D0,
      !>     .                      3.0201D0, 3.0202D0, 3.0203D0,
      !>     .                      3.0301D0, 3.0302D0, 3.0303D0,
      !>     .                      3.0401D0, 3.0402D0, 3.0403D0,
      !>     .                      3.0501D0, 3.0502D0, 3.0503D0,
      !>     .                      3.0601D0, 3.0602D0, 3.0603D0,
      !>     .     450.0D0, 50.0D0, 4.0101D0, 4.0102D0, 4.0103D0,
      !>     .                      4.0201D0, 4.0202D0, 4.0203D0,
      !>     .                      4.0301D0, 4.0302D0, 4.0303D0,
      !>     .                      4.0401D0, 4.0402D0, 4.0403D0,
      !>     .                      4.0501D0, 4.0502D0, 4.0503D0,
      !>     .                      4.0601D0, 4.0602D0, 4.0603D0 /
      !>
      !>C
      !>C     Set the start and end times of interval covered by
      !>C     segment.
      !>C
      !>      FIRST = EPOCHS(1)
      !>      LAST  = EPOCHS(NRECS + 1)
      !>
      !>C
      !>C     NCOMCH is the number of characters to reserve for the
      !>C     kernel's comment area. This example doesn't write
      !>C     comments, so set to zero.
      !>C
      !>      NCOMCH = 0
      !>
      !>C
      !>C     Internal file name and segment ID.
      !>C
      !>      IFNAME = 'Type 14 SPK internal file name.'
      !>      SEGID  = 'SPK type 14 test segment'
      !>
      !>C
      !>C     Open a new SPK file.
      !>C
      !>      CALL SPKOPN( SPK14, IFNAME, NCOMCH, HANDLE )
      !>
      !>C
      !>C     Begin the segment.
      !>C
      !>      CALL SPK14B ( HANDLE, SEGID, BODY, CENTER, REF,
      !>     .              FIRST,  LAST,  CHBDEG            )
      !>
      !>C
      !>C     Add the data to the segment all at once.
      !>C
      !>      CALL SPK14A ( HANDLE, NRECS, RECRDS, EPOCHS )
      !>
      !>C
      !>C     End the segment, making the segment a permanent addition
      !>C     to the SPK file.
      !>C
      !>      CALL SPK14E ( HANDLE )
      !>
      !>C
      !>C     Close the SPK file.
      !>C
      !>      CALL SPKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new SPK type 14 exists in
      !>        the output directory.
      !>
      !>## Restrictions
      !>
      !>     1)  The type 14 SPK segment being closed must have been started by
      !>         the routine SPK14B, the routine which begins a type 14 SPK
      !>         segment.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 27-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Added
      !>        complete example code from existing fragment.
      !>
      !>        Updated $Exceptions section.
      !>
      !>        Re-ordered header sections. Removed references to other
      !>        routines from $Abstract section (present in $Particulars).
      !>
      !>-    SPICELIB Version 1.0.0, 06-MAR-1995 (KRG)
      module subroutine spk14e ( ctx, handle )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! The handle of an SPK file open for writing.

!
!     Standard SPICELIB error handling.
!
      if ( ctx%failed() ) return

!
!     This is simple, just call the routine which ends a generic
!     segment.
!
      call sgwes ( ctx, handle )

!
!     No need to check FAILED() here, since all we do is check out.
!     Leave it up to the caller.

      return

      end subroutine spk14e

      !> Return the position of a target body relative to an observer,
      !> optionally corrected for light time and stellar aberration.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a position vector which points
      !>              from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past
      !>              J2000 TDB, at which the position of the target body
      !>              relative to the observer is to be computed. ET
      !>              refers to time at the observer's location.
      !>
      !>     REF      is the inertial reference frame with respect to which
      !>              the observer's state SOBS is expressed. REF must be
      !>              recognized by the SPICE Toolkit. The acceptable
      !>              frames are listed in the Frames Required Reading, as
      !>              well as in the SPICELIB routine CHGIRF.
      !>
      !>              Case and blanks are not significant in the string REF.
      !>
      !>     SOBS     is the geometric (uncorrected) state of the observer
      !>              relative to the solar system barycenter at epoch ET.
      !>              SOBS is a 6-vector:  the first three components of
      !>              SOBS represent a Cartesian position vector; the last
      !>              three components represent the corresponding velocity
      !>              vector. SOBS is expressed relative to the inertial
      !>              reference frame designated by REF.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to
      !>              the position of the target body to account for
      !>              one-way light time and stellar aberration. See the
      !>              discussion in the $Particulars section for
      !>              recommendations on how to choose aberration
      !>              corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric position of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the position of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction involves
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            position obtained with the 'LT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            position of the target---the position
      !>                            of the target as seen by the observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section
      !>                            of SPKEZR for a discussion of precision
      !>                            of light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            position of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            position obtained with the 'XLT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The target position
      !>                            indicates the direction that photons
      !>                            emitted from the observer's location
      !>                            must be "aimed" to hit the target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>## Detailed Output
      !>
      !>     PTARG    is a Cartesian 3-vector representing the position of
      !>              the target body relative to the specified observer.
      !>              PTARG is corrected for the specified aberrations, and
      !>              is expressed with respect to the specified inertial
      !>              reference frame. The components of PTARG represent
      !>              the x-, y- and z-components of the target's position.
      !>
      !>              The vector PTARG points from the observer's position
      !>              at ET to the aberration-corrected location of the
      !>              target. Note that the sense of the position vector is
      !>              independent of the direction of radiation travel
      !>              implied by the aberration correction.
      !>
      !>              Units are always km.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target position is
      !>              corrected for aberrations, then LT is the one-way
      !>              light time between the observer and the light time
      !>              corrected target location.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the value of ABCORR is not recognized, the error
      !>         SPICE(SPKINVALIDOPTION) is signaled.
      !>
      !>     2)  If the reference frame requested is not a recognized
      !>         inertial reference frame, the error SPICE(BADFRAME) is
      !>         signaled.
      !>
      !>     3)  If the position of the target relative to the solar system
      !>         barycenter cannot be computed, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine computes positions using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute PTARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute PTARG. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     In space science or engineering applications one frequently
      !>     wishes to know where to point a remote sensing instrument, such
      !>     as an optical camera or radio antenna, in order to observe or
      !>     otherwise receive radiation from a target. This pointing problem
      !>     is complicated by the finite speed of light: one needs to point
      !>     to where the target appears to be as opposed to where it actually
      !>     is at the epoch of observation. We use the adjectives
      !>     "geometric," "uncorrected," or "true" to refer to an actual
      !>     position or state of a target at a specified epoch. When a
      !>     geometric position or state vector is modified to reflect how it
      !>     appears to an observer, we describe that vector by any of the
      !>     terms "apparent," "corrected," "aberration corrected," or "light
      !>     time and stellar aberration corrected."
      !>
      !>     The SPICE Toolkit can correct for two phenomena affecting the
      !>     apparent location of an object: one-way light time (also called
      !>     "planetary aberration") and stellar aberration. Correcting for
      !>     one-way light time is done by computing, given an observer and
      !>     observation epoch, where a target was when the observed photons
      !>     departed the target's location. The vector from the observer to
      !>     this computed target location is called a "light time corrected"
      !>     vector. The light time correction depends on the motion of the
      !>     target, but it is independent of the velocity of the observer
      !>     relative to the solar system barycenter. Relativistic effects
      !>     such as light bending and gravitational delay are not accounted
      !>     for in the light time correction performed by this routine.
      !>
      !>     The velocity of the observer also affects the apparent location
      !>     of a target: photons arriving at the observer are subject to a
      !>     "raindrop effect" whereby their velocity relative to the observer
      !>     is, using a Newtonian approximation, the photons' velocity
      !>     relative to the solar system barycenter minus the velocity of the
      !>     observer relative to the solar system barycenter. This effect is
      !>     called "stellar aberration." Stellar aberration is independent
      !>     of the motion of the target. The stellar aberration formula used
      !>     by this routine is non- relativistic.
      !>
      !>     Stellar aberration corrections are applied after light time
      !>     corrections: the light time corrected target position vector is
      !>     used as an input to the stellar aberration correction.
      !>
      !>     When light time and stellar aberration corrections are both
      !>     applied to a geometric position vector, the resulting position
      !>     vector indicates where the target "appears to be" from the
      !>     observer's location.
      !>
      !>     As opposed to computing the apparent position of a target, one
      !>     may wish to compute the pointing direction required for
      !>     transmission of photons to the target. This requires correction
      !>     of the geometric target position for the effects of light time and
      !>     stellar aberration, but in this case the corrections are computed
      !>     for radiation traveling from the observer to the target.
      !>
      !>     The "transmission" light time correction yields the target's
      !>     location as it will be when photons emitted from the observer's
      !>     location at ET arrive at the target. The transmission stellar
      !>     aberration correction is the inverse of the traditional stellar
      !>     aberration correction: it indicates the direction in which
      !>     radiation should be emitted so that, using a Newtonian
      !>     approximation, the sum of the velocity of the radiation relative
      !>     to the observer and of the observer's velocity, relative to the
      !>     solar system barycenter, yields a velocity vector that points in
      !>     the direction of the light time corrected position of the target.
      !>
      !>     The traditional aberration corrections applicable to observation
      !>     and those applicable to transmission are related in a simple way:
      !>     one may picture the geometry of the "transmission" case by
      !>     imagining the "observation" case running in reverse time order,
      !>     and vice versa.
      !>
      !>     One may reasonably object to using the term "observer" in the
      !>     transmission case, in which radiation is emitted from the
      !>     observer's location. The terminology was retained for
      !>     consistency with earlier documentation.
      !>
      !>     Below, we indicate the aberration corrections to use for some
      !>     common applications:
      !>
      !>        1) Find the apparent direction of a target for a remote-sensing
      !>           observation.
      !>
      !>              Use 'LT+S' or 'CN+S: apply both light time and stellar
      !>              aberration corrections.
      !>
      !>           Note that using light time corrections alone ('LT' or 'CN')
      !>           is generally not a good way to obtain an approximation to
      !>           an apparent target vector: since light time and stellar
      !>           aberration corrections often partially cancel each other,
      !>           it may be more accurate to use no correction at all than to
      !>           use light time alone.
      !>
      !>        2) Find the corrected pointing direction to radiate a signal
      !>           to a target. This computation is often applicable for
      !>           implementing communications sessions.
      !>
      !>              Use 'XLT+S' or 'XCN+S: apply both light time and stellar
      !>              aberration corrections for transmission.
      !>
      !>        3) Compute the apparent position of a target body relative
      !>           to a star or other distant object.
      !>
      !>              Use 'LT', 'CN', 'LT+S', or 'CN+S' as needed to match the
      !>              correction applied to the position of the distant
      !>              object. For example, if a star position is obtained from
      !>              a catalog, the position vector may not be corrected for
      !>              stellar aberration. In this case, to find the angular
      !>              separation of the star and the limb of a planet, the
      !>              vector from the observer to the planet should be
      !>              corrected for light time but not stellar aberration.
      !>
      !>        4) Obtain an uncorrected state vector derived directly from
      !>           data in an SPK file.
      !>
      !>              Use 'NONE'.
      !>
      !>        5) Use a geometric position vector as a low-accuracy estimate
      !>           of the apparent position for an application where execution
      !>           speed is critical:
      !>
      !>              Use 'NONE'.
      !>
      !>        6) While this routine cannot perform the relativistic
      !>           aberration corrections required to compute positions
      !>           with the highest possible accuracy, it can supply the
      !>           geometric positions required as inputs to these
      !>           computations:
      !>
      !>              Use 'NONE', then apply high-accuracy aberration
      !>              corrections (not available in the SPICE Toolkit).
      !>
      !>     Below, we discuss in more detail how the aberration corrections
      !>     applied by this routine are computed.
      !>
      !>     Geometric case
      !>     ==============
      !>
      !>        SPKAPO begins by computing the geometric position T(ET) of the
      !>        target body relative to the solar system barycenter (SSB).
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the geometric position of the target body relative to the
      !>        observer. The one-way light time, LT, is given by
      !>
      !>                  | T(ET) - O(ET) |
      !>           LT = -------------------
      !>                          c
      !>
      !>        The geometric relationship between the observer, target, and
      !>        solar system barycenter is as shown:
      !>
      !>           SSB ---> O(ET)
      !>            |      /
      !>            |     /
      !>            |    /
      !>            |   /  T(ET) - O(ET)
      !>            V  V
      !>           T(ET)
      !>
      !>        The returned position vector is
      !>
      !>           T(ET) - O(ET)
      !>
      !>     Reception case
      !>     ==============
      !>
      !>        When any of the options 'LT', 'CN', 'LT+S', 'CN+S' are
      !>        selected, SPKAPO computes the position of the target body at
      !>        epoch ET-LT, where LT is the one-way light time. Let T(t)
      !>        and O(t) represent the positions of the target and observer
      !>        relative to the solar system barycenter at time t; then LT
      !>        is the solution of the
      !>        light-time equation
      !>
      !>                  | T(ET-LT) - O(ET) |
      !>           LT = ------------------------                            (1)
      !>                           c
      !>
      !>        The ratio
      !>
      !>            | T(ET) - O(ET) |
      !>          ---------------------                                     (2)
      !>                    c
      !>
      !>        is used as a first approximation to LT; inserting (2) into the
      !>        RHS of the light-time equation (1) yields the "one-iteration"
      !>        estimate of the one-way light time. Repeating the process
      !>        until the estimates of LT converge yields the "converged
      !>        Newtonian" light time estimate.
      !>
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the position of the target body relative to the observer:
      !>        T(ET-LT) - O(ET).
      !>
      !>           SSB ---> O(ET)
      !>            | \     |
      !>            |  \    |
      !>            |   \   | T(ET-LT) - O(ET)
      !>            |    \  |
      !>            V     V V
      !>           T(ET)  T(ET-LT)
      !>
      !>        The light-time corrected position is the vector
      !>
      !>           T(ET-LT) - O(ET)
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated toward the solar system barycenter-relative
      !>        velocity vector of the observer. The magnitude of the rotation
      !>        depends on the magnitude of the observer's velocity relative
      !>        to the solar system barycenter and the angle between
      !>        this velocity and the observer-target vector. The rotation
      !>        is computed as follows:
      !>
      !>           Let r be the light time corrected vector from the observer
      !>           to the object, and v be the velocity of the observer with
      !>           respect to the solar system barycenter. Let w be the angle
      !>           between them. The aberration angle phi is given by
      !>
      !>              sin(phi) = v sin(w) / c
      !>
      !>           Let h be the vector given by the cross product
      !>
      !>              h = r X v
      !>
      !>           Rotate r by phi radians about h to obtain the apparent
      !>           position of the object.
      !>
      !>     Transmission case
      !>     ==================
      !>
      !>        When any of the options 'XLT', 'XCN', 'XLT+S', 'XCN+S' are
      !>        selected, SPKAPO computes the position of the target body T at
      !>        epoch ET+LT, where LT is the one-way light time. LT is the
      !>        solution of the light-time equation
      !>
      !>                  | T(ET+LT) - O(ET) |
      !>           LT = ------------------------                            (3)
      !>                            c
      !>
      !>        Subtracting the geometric position of the observer, O(ET),
      !>        gives the position of the target body relative to the
      !>        observer: T(ET-LT) - O(ET).
      !>
      !>                   SSB --> O(ET)
      !>                  / |    *
      !>                 /  |  *  T(ET+LT) - O(ET)
      !>                /   |*
      !>               /   *|
      !>              V  V  V
      !>          T(ET+LT)  T(ET)
      !>
      !>        The light-time corrected position is
      !>
      !>           T(ET+LT) - O(ET)
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated away from the solar system barycenter-
      !>        relative velocity vector of the observer. The magnitude of the
      !>        rotation depends on the magnitude of the velocity and the
      !>        angle between the velocity and the observer-target vector.
      !>        The rotation is computed as in the reception case, but the
      !>        sign of the rotation angle is negated.
      !>
      !>     Neither special nor general relativistic effects are accounted
      !>     for in the aberration corrections performed by this routine.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, SPKSSB and SPKAPO are used
      !>     to display the position of Io (body 501) as seen from the
      !>     Voyager 2 spacecraft (Body -32) at a series of epochs.
      !>
      !>     Normally, one would call the high-level reader SPKPOS to obtain
      !>     position vectors. The example below illustrates the interface
      !>     of this routine, but is not intended as a recommendation on
      !>     how to use the SPICE SPK subsystem.
      !>
      !>     The use of integer ID codes is necessitated by the low-level
      !>     interface of this routine.
      !>
      !>        IO    = 501
      !>        VGR2  = -32
      !>
      !>        DO WHILE ( EPOCH .LE. END )
      !>
      !>           CALL SPKSSB (  VGR2,  EPOCH, 'J2000', STVGR2  )
      !>           CALL SPKAPO (  IO,    EPOCH, 'J2000', STVGR2,
      !>       .                 'LT+S', STIO,   LT              )
      !>
      !>           CALL RECRAD (  STIO,  RANGE,  RA,     DEC     )
      !>           WRITE (*,*)  RA * DPR(),  DEC * DPR()
      !>
      !>           EPOCH = EPOCH + DELTA
      !>
      !>        END DO
      !>
      !>## Restrictions
      !>
      !>     1)  The ephemeris files to be used by SPKAPO must be loaded
      !>         (normally by the SPICELIB kernel loader FURNSH) before
      !>         this routine is called.
      !>
      !>     2)  Unlike most other SPK position computation routines, this
      !>         routine requires that the input state be relative to an
      !>         inertial reference frame. Non-inertial frames are not
      !>         supported by this routine.
      !>
      !>     3)  In a future version of this routine, the implementation
      !>         of the aberration corrections may be enhanced to improve
      !>         accuracy.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.3.1, 28-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Removed
      !>        unnecessary $Revisions section.
      !>
      !>-    SPICELIB Version 2.3.0, 03-JUL-2014 (NJB) (BVS)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>        Last update was 21-SEP-2013 (BVS)
      !>
      !>           Updated to call LJUCRS instead of CMPRSS/UCASE.
      !>
      !>-    SPICELIB Version 2.2.0, 17-MAY-2010 (NJB)
      !>
      !>        Bug fix: routine now returns immediately after
      !>        state lookup failure.
      !>
      !>-    SPICELIB Version 2.1.0, 31-AUG-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in VSUB call.
      !>
      !>-    SPICELIB Version 2.0.1, 20-OCT-2003 (EDW)
      !>
      !>        Added mention that LT returns in seconds.
      !>        Corrected spelling errors.
      !>
      !>-    SPICELIB Version 2.0.0, 18-DEC-2001 (NJB)
      !>
      !>        Updated to handle aberration corrections for transmission
      !>        of radiation. Formerly, only the reception case was
      !>        supported. The header was revised and expanded to explain
      !>        the functionality of this routine in more detail.
      !>
      !>-    SPICELIB Version 1.0.0, 03-MAR-1999 (WLT)
      recursive module subroutine spkapo ( ctx, targ, et, ref, sobs, abcorr, ptarg, lt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: odd, vnorm
      use pepper_strings, only: ljucrs
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of observer's state.
      real(wp), intent(in) :: sobs     ( 6 )  !! State of observer wrt. solar system barycenter.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(out) :: ptarg    ( 3 )  !! Position of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      logical :: xmit  !! (PEPPER) copy of the saved flag for this call
      logical :: uselt  !! (PEPPER) copy of the saved flag for this call
      logical :: usecn  !! (PEPPER) copy of the saved flag for this call
      logical :: usestl  !! (PEPPER) copy of the saved flag for this call
      character(corlen) :: corr
      real(wp) :: tpos   ( 3 )
      integer(ip) :: i
      integer(ip) :: ltsign
      integer(ip) :: maxitr
      integer(ip) :: refid
      if ( .not. allocated ( ctx%spkapo_state ) ) allocate ( ctx%spkapo_state )
      associate ( first => ctx%spkapo_state%first, &
                  flags => ctx%spkapo_state%flags, &
                  prvcor => ctx%spkapo_state%prvcor, &
                  c_usecn => ctx%spkapo_state%usecn, &
                  c_usestl => ctx%spkapo_state%usestl, &
                  c_uselt => ctx%spkapo_state%uselt, &
                  c_xmit => ctx%spkapo_state%xmit )
      if ( ctx%failed() ) return

      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
!        Remove leading and embedded white space from the aberration
!        correction flag, then convert to upper case.
!
         call ljucrs ( 0, abcorr, corr )

!
!        Locate the flag in our list of flags.
!
         i = findloc(flags, corr, dim=1)

         if ( i == 0 ) then

            call ctx%setmsg ( 'Requested aberration correction was #.' )
            call ctx%errch  ( '#', abcorr                              )
            call ctx%sigerr ( 'SPICE(SPKINVALIDOPTION)'                )
            return

         end if

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction.
!
         c_xmit    =  i > ixcns

         c_uselt   =       ( i == ixlt  ) .or. ( i == ixlts  ) &
                    .or. ( i == ixxlt ) .or. ( i == ixxlts )

         c_usestl  =  ( i > 1 )  .and.  odd(i)

         c_usecn   =       ( i == ixcn  ) .or. ( i == ixcns  ) &
                    .or. ( i == ixxcn ) .or. ( i == ixxcns )

         first   = .false.

      end if
      !
      !     PEPPER: the routine may be called again, for a dynamic frame,
      !     before it returns (SPICELIB had copies per recursion level); the
      !     saved flags are copied here, and only the copies are used below.
      !
      xmit = c_xmit
      uselt = c_uselt
      usecn = c_usecn
      usestl = c_usestl

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Determine the sign of the light time offset.
!
      if ( xmit ) then
         ltsign = 1
      else
         ltsign = -1
      end if

!
!     Find the geometric position of the target body with respect to the
!     solar system barycenter. Subtract the position of the observer
!     to get the relative position. Use this to compute the one-way
!     light time.
!
      call spkgps ( ctx, targ,   et,   ref, ssb, ptarg, lt )

      if ( ctx%failed() ) return

      tpos = ptarg - sobs(1:3)
      ptarg = tpos
      lt = vnorm  ( ptarg ) / clight

!
!     To correct for light time, find the position of the target body
!     at the current epoch minus the one-way light time. Note that
!     the observer remains where he is.
!
      if ( uselt ) then
         maxitr = 1
      else if ( usecn ) then
         maxitr = 3
      else
         maxitr = 0
      end if

      do i = 1, maxitr

         call spkgps ( ctx, targ,   et + ltsign*lt, ref, ssb, ptarg, lt )

         if ( ctx%failed() ) return

         tpos = ptarg - sobs(1:3)
         ptarg = tpos
         lt = vnorm  ( ptarg ) / clight

      end do

!
!     At this point, PTARG contains the geometric or light-time
!     corrected position of the target relative to the observer,
!     depending on the specified correction.
!
!     If stellar aberration correction is requested, perform it now.
!
      if ( usestl ) then

         if ( xmit ) then
!
!           This is the transmission case.
!
!           Compute the position vector obtained by applying
!           "reception" stellar aberration to PTARG.
!
            call stlabx ( ctx, ptarg, sobs(4), tpos )
            ptarg = tpos

         else
!
!           This is the reception case.
!
!           Compute the position vector obtained by applying
!           "reception" stellar aberration to PTARG.
!
            call stelab ( ctx, ptarg, sobs(4), tpos )
            ptarg = tpos

         end if

      end if

      return
      end associate
      end subroutine spkapo

      !> Return the state (position and velocity) of a target body
      !> relative to an observer, optionally corrected for light time,
      !> expressed relative to an inertial reference frame.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a state vector whose position
      !>              component points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past
      !>              J2000 TDB, at which the state of the target body
      !>              relative to the observer is to be computed. ET
      !>              refers to time at the observer's location.
      !>
      !>     REF      is the inertial reference frame with respect to which
      !>              the input state STOBS and the output state STARG are
      !>              expressed. REF must be recognized by the SPICE
      !>              Toolkit. The acceptable frames are listed in the
      !>              Frames Required Reading, as well as in the SPICELIB
      !>              routine CHGIRF.
      !>
      !>              Case and blanks are not significant in the string
      !>              REF.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to
      !>              the state of the target body to account for one-way
      !>              light time. See the discussion in the $Particulars
      !>              section for recommendations on how to choose
      !>              aberration corrections.
      !>
      !>              If ABCORR includes the stellar aberration correction
      !>              symbol '+S', this flag is simply ignored. Aside from
      !>              the possible presence of this symbol, ABCORR may be
      !>              any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric state of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the state of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction involves
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section of
      !>                            SPKEZR for a discussion of precision of
      !>                            light time corrections.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            state of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     STOBS    is the geometric (uncorrected) state of the observer
      !>              relative to the solar system barycenter at epoch ET.
      !>              STOBS is a 6-vector: the first three components of
      !>              STOBS represent a Cartesian position vector; the last
      !>              three components represent the corresponding velocity
      !>              vector. STOBS is expressed relative to the inertial
      !>              reference frame designated by REF.
      !>
      !>              Units are always km and km/sec.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position
      !>              and velocity of the target body relative to the
      !>              specified observer. STARG is corrected for the
      !>              specified aberration, and is expressed with respect
      !>              to the specified inertial reference frame. The first
      !>              three components of STARG represent the x-, y- and
      !>              z-components of the target's position; last three
      !>              components form the corresponding velocity vector.
      !>
      !>              The position component of STARG points from the
      !>              observer's location at ET to the aberration-corrected
      !>              location of the target. Note that the sense of the
      !>              position vector is independent of the direction of
      !>              radiation travel implied by the aberration
      !>              correction.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target state is corrected
      !>              for light time, then LT is the one-way light time
      !>              between the observer and the light time-corrected
      !>              target location.
      !>
      !>     DLT      is the derivative with respect to barycentric
      !>              dynamical time of the one way light time between
      !>              target and observer:
      !>
      !>                 DLT = d(LT)/d(ET)
      !>
      !>              DLT can also be described as the rate of change of
      !>              one way light time. DLT is unitless, since LT and
      !>              ET both have units of TDB seconds.
      !>
      !>              If the observer and target are at the same position,
      !>              then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  For the convenience of the caller, the input aberration
      !>         correction flag can call for stellar aberration correction via
      !>         inclusion of the '+S' suffix. This portion of the aberration
      !>         correction flag is ignored if present.
      !>
      !>     2)  If the value of ABCORR is not recognized, an error
      !>         is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     3)  If the reference frame requested is not a recognized
      !>         inertial reference frame, the error SPICE(BADFRAME)
      !>         is signaled.
      !>
      !>     4)  If the state of the target relative to the solar system
      !>         barycenter cannot be computed, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     5)  If the observer and target are at the same position,
      !>         then DLT is set to zero. This situation could arise,
      !>         for example, when the observer is Mars and the target
      !>         is the Mars barycenter.
      !>
      !>     6)  If a division by zero error would occur in the computation
      !>         of DLT, the error SPICE(DIVIDEBYZERO) is signaled.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level SPK API routines that can
      !>     perform both light time and stellar aberration corrections.
      !>     User applications normally will not need to call this routine
      !>     directly.
      !>
      !>     See the header of the routine SPKEZR for a detailed discussion
      !>     of aberration corrections.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Look up a sequence of states of the Moon as seen from the
      !>        Earth. Use light time corrections. Compute the first state for
      !>        the epoch 2000 JAN 1 12:00:00 TDB; compute subsequent states at
      !>        intervals of 1 hour. For each epoch, display the states, the
      !>        one way light time between target and observer, and the rate of
      !>        change of the one way light time.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: spkltc_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00010.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0010.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0010.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPKLTC_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     Local constants
      !>C
      !>C     The meta-kernel name shown here refers to a file whose
      !>C     contents are those shown above. This file and the kernels
      !>C     it references must exist in your current working
      !>C     directory.
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'spkltc_ex1.tm' )
      !>C
      !>C     Use a time step of 1 hour; look up 5 states.
      !>C
      !>      DOUBLE PRECISION      STEP
      !>      PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>      INTEGER               MAXITR
      !>      PARAMETER           ( MAXITR = 5 )
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      DLT
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      STATE ( 6 )
      !>      DOUBLE PRECISION      STOBS ( 6 )
      !>      INTEGER               I
      !>
      !>C
      !>C     Load the SPK and LSK kernels via the meta-kernel.
      !>C
      !>      CALL FURNSH ( META )
      !>C
      !>C     Convert the start time to seconds past J2000 TDB.
      !>C
      !>      CALL STR2ET ( '2000 JAN 1 12:00:00 TDB', ET0 )
      !>C
      !>C     Step through a series of epochs, looking up a
      !>C     state vector at each one.
      !>C
      !>      DO I = 1, MAXITR
      !>
      !>         ET = ET0 + (I-1)*STEP
      !>
      !>C
      !>C        Look up a state vector at epoch ET using the
      !>C        following inputs:
      !>C
      !>C           Target:                 Moon (NAIF ID code 301)
      !>C           Reference frame:        J2000
      !>C           Aberration correction:  Light time ('LT')
      !>C           Observer:               Earth (NAIF ID code 399)
      !>C
      !>C        Before we can execute this computation, we'll need the
      !>C        geometric state of the observer relative to the solar
      !>C        system barycenter at ET, expressed relative to the
      !>C        J2000 reference frame:
      !>C
      !>         CALL SPKSSB ( 399, ET,    'J2000', STOBS )
      !>C
      !>C        Now compute the desired state vector:
      !>C
      !>         CALL SPKLTC ( 301,   ET,    'J2000', 'LT',
      !>     .                 STOBS, STATE, LT,      DLT     )
      !>
      !>         WRITE (*,*) 'ET = ', ET
      !>         WRITE (*,*) 'J2000 x-position (km):   ', STATE(1)
      !>         WRITE (*,*) 'J2000 y-position (km):   ', STATE(2)
      !>         WRITE (*,*) 'J2000 z-position (km):   ', STATE(3)
      !>         WRITE (*,*) 'J2000 x-velocity (km/s): ', STATE(4)
      !>         WRITE (*,*) 'J2000 y-velocity (km/s): ', STATE(5)
      !>         WRITE (*,*) 'J2000 z-velocity (km/s): ', STATE(6)
      !>         WRITE (*,*) 'One-way light time (s):  ', LT
      !>         WRITE (*,*) 'Light time rate:         ', DLT
      !>         WRITE (*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         ET =    0.0000000000000000
      !>         J2000 x-position (km):     -291569.26516582817
      !>         J2000 y-position (km):     -266709.18671506643
      !>         J2000 z-position (km):     -76099.155290968716
      !>         J2000 x-velocity (km/s):   0.64353061395009092
      !>         J2000 y-velocity (km/s):  -0.66608181647356979
      !>         J2000 z-velocity (km/s):  -0.30132283137339932
      !>         One-way light time (s):     1.3423106103603615
      !>         Light time rate:            1.0731690854241060E-007
      !>
      !>         ET =    3600.0000000000000
      !>         J2000 x-position (km):     -289240.78103223071
      !>         J2000 y-position (km):     -269096.44111447036
      !>         J2000 z-position (km):     -77180.899896450341
      !>         J2000 x-velocity (km/s):   0.65006211592321250
      !>         J2000 y-velocity (km/s):  -0.66016273867753217
      !>         J2000 z-velocity (km/s):  -0.29964267347917639
      !>         One-way light time (s):     1.3426939548981949
      !>         Light time rate:            1.0565259879591478E-007
      !>
      !>         ET =    7200.0000000000000
      !>         J2000 x-position (km):     -286888.88711488992
      !>         J2000 y-position (km):     -271462.30193841457
      !>         J2000 z-position (km):     -78256.555851273239
      !>         J2000 x-velocity (km/s):   0.65653599225917958
      !>         J2000 y-velocity (km/s):  -0.65419657625983696
      !>         J2000 z-velocity (km/s):  -0.29794027264402967
      !>         One-way light time (s):     1.3430713117678452
      !>         Light time rate:            1.0399045674252711E-007
      !>
      !>         ET =    10800.000000000000
      !>         J2000 x-position (km):     -284513.79148214310
      !>         J2000 y-position (km):     -273806.60054129362
      !>         J2000 z-position (km):     -79326.043350853026
      !>         J2000 x-velocity (km/s):   0.66295190125626391
      !>         J2000 y-velocity (km/s):  -0.64818380654817442
      !>         J2000 z-velocity (km/s):  -0.29621577893712070
      !>         One-way light time (s):     1.3434426891028646
      !>         Light time rate:            1.0233066508729246E-007
      !>
      !>         ET =    14400.000000000000
      !>         J2000 x-position (km):     -282115.70342658088
      !>         J2000 y-position (km):     -276129.16999696195
      !>         J2000 z-position (km):     -80389.283131733537
      !>         J2000 x-velocity (km/s):   0.66930950447965998
      !>         J2000 y-velocity (km/s):  -0.64212490750332751
      !>         J2000 z-velocity (km/s):  -0.29446934292511795
      !>         One-way light time (s):     1.3438080956889309
      !>         Light time rate:            1.0067340347415892E-007
      !>
      !>## Restrictions
      !>
      !>     1)  The routine SPKGEO should be used instead of this routine
      !>         to compute geometric states. SPKGEO introduces less
      !>         round-off error when the observer and target have common
      !>         center that is closer to both objects than is the solar
      !>         system barycenter.
      !>
      !>     2)  The kernel files to be used by SPKLTC must be loaded
      !>         (normally by the SPICELIB kernel loader FURNSH) before
      !>         this routine is called.
      !>
      !>     3)  Unlike most other SPK state computation routines, this
      !>         routine requires that the output state be relative to an
      !>         inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.1, 05-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standards.
      !>        Added FRAMES to the list of $Required_Reading
      !>
      !>-    SPICELIB Version 2.0.0, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>     Last update was 02-MAY-2012 (NJB)
      !>
      !>        Updated to ensure convergence when CN or XCN light time
      !>        corrections are used. The new algorithm also terminates early
      !>        (after fewer than three iterations) when convergence is
      !>        attained.
      !>
      !>        Call to ZZPRSCOR was replaced by a call to ZZVALCOR.
      !>
      !>-    SPICELIB Version 1.0.0, 11-JAN-2008 (NJB)
      recursive module subroutine spkltc ( ctx, targ, et, ref, abcorr, stobs, starg, lt, dlt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: vdot, vnorm
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(in) :: stobs  ( 6 )  !! State of the observer relative to the SSB.
      real(wp), intent(out) :: starg  ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
      logical :: xmit  !! (PEPPER) copy of the saved flag for this call
      logical :: uselt  !! (PEPPER) copy of the saved flag for this call
      logical :: usecn  !! (PEPPER) copy of the saved flag for this call
      real(wp) :: a
      real(wp) :: b
      real(wp) :: c
      real(wp) :: dist
      real(wp) :: epoch
      real(wp) :: lterr
      real(wp) :: prvlt
      real(wp) :: ssblt
      real(wp) :: ssbtrg ( 6 )
      integer(ip) :: i
      integer(ip) :: ltsign
      integer(ip) :: numitr
      integer(ip) :: refid
      logical :: attblk ( nabcor )
      logical :: usestl
      if ( .not. allocated ( ctx%spkltc_state ) ) allocate ( ctx%spkltc_state )
      associate ( pass1 => ctx%spkltc_state%pass1, &
                  prvcor => ctx%spkltc_state%prvcor, &
                  c_usecn => ctx%spkltc_state%usecn, &
                  c_uselt => ctx%spkltc_state%uselt, &
                  c_xmit => ctx%spkltc_state%xmit )
      if ( ctx%failed() ) return

      if (  pass1  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USECN indicates converged Newtonian light time correction.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         c_xmit    =  attblk ( xmtidx )
         c_uselt   =  attblk ( ltidx )
         c_usecn   =  attblk ( cnvidx )
         usestl  =  attblk ( stlidx )

         pass1   = .false.

      end if
      !
      !     PEPPER: the routine may be called again, for a dynamic frame,
      !     before it returns (SPICELIB had copies per recursion level); the
      !     saved flags are copied here, and only the copies are used below.
      !
      xmit = c_xmit
      uselt = c_uselt
      usecn = c_usecn

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Find the geometric state of the target body with respect to
!     the solar system barycenter. Subtract the state of the
!     observer to get the relative state. Use this to compute the
!     one-way light time.
!
      call spkgeo ( ctx, targ,   et,    ref, ssb,  ssbtrg, ssblt )

      if ( ctx%failed() ) return

      starg = ssbtrg - stobs

      dist = vnorm(starg)
      lt   = dist / clight

      if ( lt == 0.0_wp ) then
!
!        This can happen only if the observer and target are at the
!        same position. We don't consider this an error, but we're not
!        going to compute the light time derivative.
!
         dlt = 0

         return

      end if

      if ( .not. uselt ) then
!
!        This is a special case: we're not using light time
!        corrections, so the derivative
!        of light time is just
!
!           (1/c) * d(VNORM(STARG))/dt
!
         dlt = vdot( starg, starg(4) ) / ( dist * clight )

!
!        LT and DLT are both set, so we can return.
!
         return

      end if

!
!     To correct for light time, find the state of the target body
!     at the current epoch minus the one-way light time. Note that
!     the observer remains where it is.
!
!     Determine the sign of the light time offset.
!
      if ( xmit ) then
         ltsign =  1
      else
         ltsign = -1
      end if

!
!     Let NUMITR be the number of iterations we'll perform to
!     compute the light time.
!
      if ( usecn ) then
         numitr = maxitr
      else
         numitr = 1
      end if

      i     = 0
      lterr = 1.0_wp

      do while (  ( i < numitr ) .and. ( lterr > cnvlim )  )
!
!        LT was set either prior to this loop or
!        during the previous loop iteration.
!
         epoch  =  et + ( ltsign * lt )

         call spkgeo ( ctx, targ, epoch, ref, ssb, ssbtrg, ssblt )

         if ( ctx%failed() ) return

         starg = ssbtrg - stobs

         prvlt = lt
         lt    = (vnorm( starg ) / clight)

!        LTERR is the magnitude of the change between the current
!        estimate of light time and the previous estimate, relative to
!        the previous light time corrected epoch.
!
         lterr = (abs( lt  - prvlt      )  / max( 1.0_wp, abs(epoch) ))
         i     = i + 1

      end do

!
!     At this point, STARG contains the light time corrected
!     state of the target relative to the observer.
!
!     Compute the derivative of light time with respect
!     to time: dLT/dt.  Below we derive the formula for
!     this quantity for the reception case. Let
!
!        POBS be the position of the observer relative to the
!        solar system barycenter.
!
!        VOBS be the velocity of the observer relative to the
!        solar system barycenter.
!
!        PTARG be the position of the target relative to the
!        solar system barycenter.
!
!        VTARG be the velocity of the target relative to the
!        solar system barycenter.
!
!        S be the sign of the light time correction. S is
!        negative for the reception case.
!
!     The light-time corrected position of the target relative to
!     the observer at observation time ET, given the one-way
!     light time LT is:
!
!         PTARG(ET+S*LT) - POBS(ET)
!
!     The light-time corrected velocity of the target relative to
!     the observer at observation time ET is
!
!         VTARG(ET+S*LT)*( 1 + S*d(LT)/d(ET) ) - VOBS(ET)
!
!     We need to compute dLT/dt. Below, we use the facts that,
!     for a time-dependent vector X(t),
!
!          ||X||     = <X,X> ** (1/2)
!
!        d(||X||)/dt = (1/2)<X,X>**(-1/2) * 2 * <X,dX/dt>
!
!                    = <X,X>**(-1/2) *  <X,dX/dt>
!
!                    = <X,dX/dt> / ||X||
!
!     Newtonian light time equation:
!
!        LT     =   (1/c) * || PTARG(ET+S*LT) - POBS(ET)||
!
!     Differentiate both sides:
!
!        dLT/dt =   (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!                  * < PTARG(ET+S*LT) - POBS(ET),
!                      VTARG(ET+S*LT)*(1+S*d(LT)/d(ET)) - VOBS(ET) >
!
!               = (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!                 * (  < PTARG(ET+S*LT) - POBS(ET),
!                        VTARG(ET+S*LT) - VOBS(ET) >
!
!                   +  < PTARG(ET+S*LT) - POBS(ET),
!                        VTARG(ET+S*LT)           > * (S*d(LT)/d(ET))  )
!
!     Let
!
!        A =   (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!        B =   < PTARG(ET+S*LT) - POBS(ET), VTARG(ET+S*LT) - VOBS(ET) >
!
!        C =   < PTARG(ET+S*LT) - POBS(ET), VTARG(ET+S*LT) >
!
!     Then
!
!        d(LT)/d(ET) =  A * ( B  +  C * S*d(LT)/d(ET) )
!
!     which implies
!
!        d(LT)/d(ET) =  A*B / ( 1 - S*C*A )
!
      a   =  1.0_wp / ( clight*vnorm(starg) )

      b   =  vdot ( starg, starg(4)  )

      c   =  vdot ( starg, ssbtrg(4) )

!
!     For physically realistic target velocities, S*C*A cannot equal 1.
!     We'll check for this case anyway.
!
      if (  ltsign*c*a  >  1.0_wp-tol ) then

         call ctx%setmsg ( 'Target range rate magnitude is ' &
      //               'approximately the speed of light. The ' &
      //               'light time derivative cannot be ' &
      //               'computed.'                            )
         call ctx%sigerr ( 'SPICE(DIVIDEBYZERO)'                  )
         return

      end if

!
!     Compute DLT: the rate of change of light time.
!
      dlt = (a*b)/( 1.0_wp - ltsign*c*a )

!
!     Overwrite the velocity portion of the output state
!     with the light-time corrected velocity.
!
      starg(4:6) = (1.0_wp + ltsign*dlt)*ssbtrg(4:6) + (-1.0_wp)*stobs(4:6)

      return
      end associate
      end subroutine spkltc

      !> Extract a subset of the data in a type 10 SPK segment into a new
      !> type 10 segment.
      !>
      !>## Detailed Input
      !>
      !>     SRCHAN   is the handle of the SPK file containing the source
      !>              segment.
      !>
      !>     SRCDSC   is the SPK descriptor for the source segment.
      !>
      !>     DSTHAN   is the handle of the SPK file containing the new segment.
      !>
      !>     DSTDSC   is the SPK descriptor for the destination segment. It
      !>              contains the desired start and stop times for the
      !>              requested subset.
      !>
      !>     DSTSID   is the segment identifier for the destination segment.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     None.
      !>
      !>## Files
      !>
      !>     See arguments SRCHAN, DSTHAN.
      !>
      !>## Particulars
      !>
      !>     This subroutine copies a subset of the data form one SPK segment
      !>     to another.
      !>
      !>     The exact structure of a segment of SPK type 10 is detailed in
      !>     the SPK Required Reading. Please see this document for details.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     1)  We assume that the source descriptor actually describes a
      !>         segment in the source SPK file containing the time coverage
      !>         that is desired for the subsetting operation.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-JUN-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 30-JUN-1997 (KRG)
      module subroutine spks10 ( ctx, srchan, srcdsc, dsthan, dstdsc, dstsid )
      use pepper_kinds, only: ip, wp
      use pepper_inc_sgparam
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: srchan  !! Handle of the SPK file with the source segment.
      real(wp), intent(in) :: srcdsc(*)  !! Descriptor for the source segment.
      integer(ip), intent(in) :: dsthan  !! Handle of the SPK file for the destination segment.
      real(wp), intent(in) :: dstdsc(*)  !! Descriptor for the destination segment.
      character(*), intent(in) :: dstsid  !! Segment identifier for the new segment.
      real(wp) :: myref_1(1)  !! one-element copy of myref (array argument)
      integer(ip) :: dummy_1(1)  !! one-element copy of dummy (array argument)

      integer(ip), parameter :: wdsize = 40


!
!     The number of geophysical constants:
!
      integer(ip), parameter :: nconst = 8
!
!     The number of elements per two-line set:
!
      integer(ip), parameter :: nelems = 10

      integer(ip), parameter :: nangs = 4

      integer(ip), parameter :: pktsiz = nelems + nangs

      character(wdsize) :: time

      real(wp) :: begtim
      real(wp) :: consts ( nconst )
      real(wp) :: dtemp  ( nd     )
      real(wp) :: endtim
      real(wp) :: myref
      real(wp) :: packet ( pktsiz )

      integer(ip) :: begidx
      integer(ip) :: dummy
      integer(ip) :: endidx
      integer(ip) :: i
      integer(ip) :: itemp  ( ni )
      integer(ip) :: nepoch

      logical :: found

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return
!
!     First, unpack the destination segment descriptor and set some
!     local variables.
!
      call dafus( ctx, dstdsc, nd, ni, dtemp, itemp )

      begtim = dtemp(1)
      endtim = dtemp(2)
!
!     Get the constants for the input segment and send them to the
!     output segment by beginning a fixed packet size segment.
!
      call sgfcon ( ctx, srchan, srcdsc, 1, nconst, consts )
      call sgbwfs ( ctx, dsthan, dstdsc, dstsid, nconst, consts, [ pktsiz ], expcls )

      if ( ctx%failed() ) return

!
!     Get the beginning and ending indices for the packets we need for
!     the destination segment.  Note we need to get the preceding
!     and succeeding packets (if there are any) corresponding to the
!     start and end times of the output segments
!
      call sgfrvi ( ctx, srchan, srcdsc, begtim, myref, begidx, found )

      if ( .not. found ) then

         call etcal  ( ctx, begtim, time )
         call ctx%setmsg ( 'An error has occurred while attempting ' &
         //            'to subset the a type 10 SPK segment. The ' &
         //            'error occurred while attempting to ' &
         //            'locate a packet for the epoch #.  There ' &
         //            'does not appear to be such a packet. ' )
         call ctx%errch  ( '#', time )
         call ctx%sigerr ( 'SPICE(CANNOTGETPACKET)'  )
         return

      end if

      if ( myref > begtim ) then
         begidx = max ( 1, begidx - 1 )
      end if

      call sgfrvi ( ctx, srchan, srcdsc, endtim, myref, endidx, found )

      if ( .not. found ) then

         call etcal  ( ctx, endtim, time )
         call ctx%setmsg ( 'An error has occurred while attempting ' &
         //            'to subset the a type 10 SPK segment. The ' &
         //            'error occurred while attempting to ' &
         //            'locate a packet for the epoch #.  There ' &
         //            'does not appear to be such a packet. ' )
         call ctx%errch  ( '#', time )
         call ctx%sigerr ( 'SPICE(CANNOTGETPACKET)'  )
         return

      end if

!
!     Get the total number of epochs.
!
      call sgmeta ( ctx, srchan, srcdsc, nref, nepoch )

      if ( myref < endtim ) then
         endidx = min ( nepoch, endidx + 1 )
      end if

!
!     Now we get the data one record at a time from the source segment
!     and write it out to the destination segment.
!
      do i = begidx, endidx

         call sgfpkt ( ctx, srchan, srcdsc, i, i, packet, dummy_1 )
         dummy = dummy_1(1)
         call sgfref ( ctx, srchan, srcdsc, i, i, myref_1 )
         myref = myref_1(1)
         call sgwfpk ( ctx, dsthan, 1, packet, 1, [ myref ] )

      end do

!
!     Now all we need to do is end the segment.
!
      call sgwes  ( ctx, dsthan   )

      return

      end subroutine spks10

      !> Extract a subset of the data in an SPK segment of type 12
      !> into a new segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE,
      !>     BADDR,
      !>     EADDR    are the file handle assigned to an SPK file, and the
      !>              beginning and ending addresses of a segment within
      !>              that file. Together they determine a complete set of
      !>              ephemeris data, from which a subset is to be
      !>              extracted.
      !>
      !>     BEGIN,
      !>     END      are the initial and final epochs (ephemeris time)
      !>              of the subset.
      !>
      !>              The output segment will be padded to the left of
      !>              BEGIN and the right of END with sufficient states to
      !>              ensure that the segment yields an ephemeris identical
      !>              to that given by the source segment.
      !>
      !>## Detailed Output
      !>
      !>     See $Files section.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  This routine relies on the caller to ensure that the
      !>         interval [BEGIN, END] is contained in the coverage
      !>         interval of the segment.
      !>
      !>     2)  If BEGIN > END, no data is written to the target file.
      !>
      !>## Files
      !>
      !>     Data is extracted from the file connected to the input
      !>     handle, and written to the current DAF open for writing.
      !>
      !>     The segment descriptor and summary must already have been written
      !>     prior to calling this routine. The segment must be ended
      !>     external to this routine.
      !>
      !>## Particulars
      !>
      !>     This routine is intended solely for use as a utility by the
      !>     routine SPKSUB.
      !>
      !>     It transfers a subset of a type 12 SPK data segment to
      !>     a properly initialized segment of a second SPK file.
      !>
      !>     The exact structure of a segment of data type 12 is described
      !>     in the section on type 12 in the SPK Required Reading.
      !>
      !>## Examples
      !>
      !>     This routine is intended only for use as a utility by SPKSUB.
      !>     To use this routine successfully, you must:
      !>
      !>        Open the SPK file from which to extract data.
      !>        Locate the segment from which data should be extracted.
      !>
      !>        Open the SPK file to which this data should be written.
      !>        Begin a new segment (array).
      !>        Write the summary information for the array.
      !>
      !>        Call this routine to extract the appropriate data from the
      !>        SPK open for read.
      !>
      !>        End the array to which this routine writes data.
      !>
      !>     Much of this procedure is carried out by the routine SPKSUB. The
      !>     examples of that routine illustrate more fully the process
      !>     described above.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-JUN-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 25-FEB-2000 (NJB)
      module subroutine spks12 ( ctx, handle, baddr, eaddr, begin, end )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of file containing source segment.
      integer(ip), intent(in) :: baddr  !! Beginning address in file of source segment.
      integer(ip), intent(in) :: eaddr  !! Ending address in file of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     The type 8 subsetter knows how to do this job.
!
      call spks08 ( ctx, handle, baddr, eaddr, begin, end )

      return
      end subroutine spks12

      !> Extract a subset of the data in an SPK segment of type 13
      !> into a new segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE,
      !>     BADDR,
      !>     EADDR    are the file handle assigned to an SPK file, and the
      !>              beginning and ending addresses of a segment within
      !>              that file. Together they determine a complete set of
      !>              ephemeris data, from which a subset is to be
      !>              extracted.
      !>
      !>     BEGIN,
      !>     END      are the initial and final epochs (ephemeris time)
      !>              of the subset.
      !>
      !>              The output segment will be padded to the left of
      !>              BEGIN and the right of END with sufficient states to
      !>              ensure that the segment yields an ephemeris identical
      !>              to that given by the source segment.
      !>
      !>## Detailed Output
      !>
      !>     See $Files section.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  This routine relies on the caller to ensure that the
      !>         interval [BEGIN, END] is contained in the coverage
      !>         interval of the segment.
      !>
      !>     2)  If BEGIN > END, no data is written to the target file.
      !>
      !>## Files
      !>
      !>     Data is extracted from the file connected to the input
      !>     handle, and written to the current DAF open for writing.
      !>
      !>     The segment descriptor and summary must already have been written
      !>     prior to calling this routine. The segment must be ended
      !>     external to this routine.
      !>
      !>## Particulars
      !>
      !>     This routine is intended solely for use as a utility by the
      !>     routine SPKSUB.
      !>
      !>     It transfers a subset of a type 13 SPK data segment to
      !>     a properly initialized segment of a second SPK file.
      !>
      !>     The exact structure of a segment of data type 13 is described
      !>     in the section on type 13 in the SPK Required Reading.
      !>
      !>## Examples
      !>
      !>     This routine is intended only for use as a utility by SPKSUB.
      !>     To use this routine successfully, you must:
      !>
      !>        Open the SPK file from which to extract data.
      !>        Locate the segment from which data should be extracted.
      !>
      !>        Open the SPK file to which this data should be written.
      !>        Begin a new segment (array).
      !>        Write the summary information for the array.
      !>
      !>        Call this routine to extract the appropriate data from the
      !>        SPK open for read.
      !>
      !>        End the array to which this routine writes data.
      !>
      !>     Much of this procedure is carried out by the routine SPKSUB. The
      !>     examples of that routine illustrate more fully the process
      !>     described above.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-JUN-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 25-FEB-2000 (NJB)
      module subroutine spks13 ( ctx, handle, baddr, eaddr, begin, end )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of file containing source segment.
      integer(ip), intent(in) :: baddr  !! Beginning address in file of source segment.
      integer(ip), intent(in) :: eaddr  !! Ending address in file of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     The type 9 subsetter knows how to do this job.
!
      call spks09 ( ctx, handle, baddr, eaddr, begin, end )

      return
      end subroutine spks13

      !> Return the state (position and velocity) of a target body
      !> relative to the solar system barycenter.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the standard NAIF ID code for a target body.
      !>
      !>     ET       is the epoch (ephemeris time) at which the state of the
      !>              target body is to be computed.
      !>
      !>     REF      is the name of the reference frame relative to which the
      !>              output state vector should be expressed. This may be any
      !>              frame supported by the SPICELIB frame system, including
      !>              dynamic and other non-inertial frames.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position and
      !>              velocity of the target body, relative to the solar system
      !>              barycenter, at epoch ET. This vector is rotated into the
      !>              specified reference frame. Units are always km and
      !>              km/sec.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If sufficient information has not been "loaded" via the
      !>         routine FURNSH, SPKLEF or the PCK kernel loaders, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     See $Restrictions.
      !>
      !>## Particulars
      !>
      !>     In order to compute the state of one body relative to another,
      !>     the states of the two bodies must be known relative to a third
      !>     body. One simple solution is to use the solar system barycenter
      !>     as the third body.
      !>
      !>     Ephemeris data from more than one segment may be required
      !>     to determine the state of a body relative to the barycenter.
      !>     SPKSSB reads as many segments as necessary, from as many
      !>     files as necessary, using files that have been loaded by
      !>     previous calls to FURNSH or SPKLEF (load ephemeris file).
      !>
      !>## Examples
      !>
      !>     In the following code fragment, SPKSSB is used to display
      !>     the distance from Earth (Body 399) to Mars (body 499) at
      !>     a series of epochs.
      !>
      !>        CALL SPKLEF ( 'DE125.SPK', HANDLE )
      !>         .
      !>         .
      !>
      !>        EARTH = 399
      !>        MARS  = 499
      !>
      !>        DO WHILE ( EPOCH .LE. END )
      !>           CALL SPKSSB ( EARTH, EPOCH, 'J2000', SEARTH )
      !>           CALL SPKSSB ( MARS,  EPOCH, 'J2000', SMARS  )
      !>
      !>           CALL VSUB ( SMARS, SEARTH, SMARS )
      !>           WRITE (*,*) EPOCH, VNORM ( SMARS )
      !>
      !>           EPOCH = EPOCH + DELTA
      !>        END DO
      !>
      !>## Restrictions
      !>
      !>     1)  The ephemeris files to be used by SPKSSB must be loaded
      !>         by FURNSH or SPKLEF before SPKSSB is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     H.A. Neilan        (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.4, 13-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Updated
      !>        detailed description of arguments REF and STARG.
      !>
      !>-    SPICELIB Version 2.0.3, 18-MAY-2010 (BVS)
      !>
      !>        Removed "C$" marker from text in the header.
      !>
      !>-    SPICELIB Version 2.0.2, 20-NOV-2004 (NJB)
      !>
      !>        Updated description of input argument REF to indicate all
      !>        frames supported by SPICELIB are allowed.
      !>
      !>-    SPICELIB Version 2.0.1, 24-JUN-1999 (WLT)
      !>
      !>        Corrected code in $Examples section of the headers
      !>
      !>-    SPICELIB Version 2.0.0, 19-SEP-1995 (WLT)
      !>
      !>        The routine was simplified by replacing all of the
      !>        main body of code with a call to SPKGEO. By making
      !>        this change the routine now supports non-inertial frames.
      !>
      !>-    SPICELIB Version 1.0.2, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.1, 22-MAR-1990 (HAN)
      !>
      !>        Literature references added to the header.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 2.0.0, 19-SEP-1995 (WLT)
      !>
      !>        The routine was simplified by replacing all of the
      !>        main body of code with a call to SPKGEO. By making
      !>        this change the routine now supports non-inertial frames.
      recursive module subroutine spkssb ( ctx, targ, et, ref, starg )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Target epoch.
      character(*), intent(in) :: ref  !! Target reference frame.
      real(wp), intent(out) :: starg    ( 6 )  !! State of target.

      real(wp) :: lt
      integer(ip) :: bary

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      bary = 0

      call spkgeo ( ctx, targ, et, ref, bary, starg, lt )

      return
      end subroutine spkssb

      !> **Deprecated:** This routine has been superseded by the SPICELIB
      !> routine [[spkaps]]. This routine is supported for purposes of
      !> backward compatibility only.
      !>
      !> Return the state (position and velocity) of a target body
      !> relative to an observer, optionally corrected for light time and
      !> stellar aberration.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a state vector whose position
      !>              component points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past J2000
      !>              TDB, at which the state of the target body relative to
      !>              the observer is to be computed. ET refers to time at
      !>              the observer's location.
      !>
      !>     REF      is the inertial reference frame with respect to which
      !>              the observer's state SOBS is expressed. REF must be
      !>              recognized by the SPICE Toolkit. The acceptable
      !>              frames are listed in the Frames Required Reading, as
      !>              well as in the SPICELIB routine CHGIRF.
      !>
      !>              Case and blanks are not significant in the string REF.
      !>
      !>     SOBS     is the geometric (uncorrected) state of the observer
      !>              relative to the solar system barycenter at epoch ET.
      !>              SOBS is a 6-vector:  the first three components of
      !>              SOBS represent a Cartesian position vector; the last
      !>              three components represent the corresponding velocity
      !>              vector. SOBS is expressed relative to the inertial
      !>              reference frame designated by REF.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              to the state of the target body to account for one-way
      !>              light time and stellar aberration. See the discussion
      !>              in the $Particulars section for recommendations on
      !>              how to choose aberration corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric state of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the state of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction involves
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            state obtained with the 'LT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            state of the target---the position and
      !>                            velocity of the target as seen by the
      !>                            observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section
      !>                            of SPKEZR for a discussion of precision
      !>                            of light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            state of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            state obtained with the 'XLT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The position component of
      !>                            the computed target state indicates the
      !>                            direction that photons emitted from the
      !>                            observer's location must be "aimed" to
      !>                            hit the target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position
      !>              and velocity of the target body relative to the
      !>              specified observer. STARG is corrected for the
      !>              specified aberrations, and is expressed with respect
      !>              to the specified inertial reference frame. The first
      !>              three components of STARG represent the x-, y- and
      !>              z-components of the target's position; last three
      !>              components form the corresponding velocity vector.
      !>
      !>              The position component of STARG points from the
      !>              observer's location at ET to the aberration-corrected
      !>              location of the target. Note that the sense of the
      !>              position vector is independent of the direction of
      !>              radiation travel implied by the aberration
      !>              correction.
      !>
      !>              The velocity component of STARG is obtained by
      !>              evaluating the target's geometric state at the light
      !>              time corrected epoch, so for aberration-corrected
      !>              states, the velocity is not precisely equal to the
      !>              time derivative of the position.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target state is corrected
      !>              for aberrations, then LT is the one-way light time
      !>              between the observer and the light time corrected
      !>              target location.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the value of ABCORR is not recognized, the error
      !>         SPICE(SPKINVALIDOPTION) is signaled.
      !>
      !>     2)  If the reference frame requested is not a recognized
      !>         inertial reference frame, the error SPICE(BADFRAME)
      !>         is signaled.
      !>
      !>     3)  If the state of the target relative to the solar system
      !>         barycenter cannot be computed, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     In space science or engineering applications one frequently
      !>     wishes to know where to point a remote sensing instrument, such
      !>     as an optical camera or radio antenna, in order to observe or
      !>     otherwise receive radiation from a target. This pointing problem
      !>     is complicated by the finite speed of light: one needs to point
      !>     to where the target appears to be as opposed to where it actually
      !>     is at the epoch of observation. We use the adjectives
      !>     "geometric," "uncorrected," or "true" to refer to an actual
      !>     position or state of a target at a specified epoch. When a
      !>     geometric position or state vector is modified to reflect how it
      !>     appears to an observer, we describe that vector by any of the
      !>     terms "apparent," "corrected," "aberration corrected," or "light
      !>     time and stellar aberration corrected."
      !>
      !>     The SPICE Toolkit can correct for two phenomena affecting the
      !>     apparent location of an object: one-way light time (also called
      !>     "planetary aberration") and stellar aberration. Correcting for
      !>     one-way light time is done by computing, given an observer and
      !>     observation epoch, where a target was when the observed photons
      !>     departed the target's location. The vector from the observer to
      !>     this computed target location is called a "light time corrected"
      !>     vector. The light time correction depends on the motion of the
      !>     target, but it is independent of the velocity of the observer
      !>     relative to the solar system barycenter. Relativistic effects
      !>     such as light bending and gravitational delay are not accounted
      !>     for in the light time correction performed by this routine.
      !>
      !>     The velocity of the observer also affects the apparent location
      !>     of a target: photons arriving at the observer are subject to a
      !>     "raindrop effect" whereby their velocity relative to the observer
      !>     is, using a Newtonian approximation, the photons' velocity
      !>     relative to the solar system barycenter minus the velocity of the
      !>     observer relative to the solar system barycenter. This effect is
      !>     called "stellar aberration." Stellar aberration is independent
      !>     of the velocity of the target. The stellar aberration formula
      !>     used by this routine is non-relativistic.
      !>
      !>     Stellar aberration corrections are applied after light time
      !>     corrections: the light time corrected target position vector is
      !>     used as an input to the stellar aberration correction.
      !>
      !>     When light time and stellar aberration corrections are both
      !>     applied to a geometric position vector, the resulting position
      !>     vector indicates where the target "appears to be" from the
      !>     observer's location.
      !>
      !>     As opposed to computing the apparent position of a target, one
      !>     may wish to compute the pointing direction required for
      !>     transmission of photons to the target. This requires correction
      !>     of the geometric target position for the effects of light time and
      !>     stellar aberration, but in this case the corrections are computed
      !>     for radiation traveling from the observer to the target.
      !>
      !>     The "transmission" light time correction yields the target's
      !>     location as it will be when photons emitted from the observer's
      !>     location at ET arrive at the target. The transmission stellar
      !>     aberration correction is the inverse of the traditional stellar
      !>     aberration correction: it indicates the direction in which
      !>     radiation should be emitted so that, using a Newtonian
      !>     approximation, the sum of the velocity of the radiation relative
      !>     to the observer and of the observer's velocity, relative to the
      !>     solar system barycenter, yields a velocity vector that points in
      !>     the direction of the light time corrected position of the target.
      !>
      !>     The traditional aberration corrections applicable to observation
      !>     and those applicable to transmission are related in a simple way:
      !>     one may picture the geometry of the "transmission" case by
      !>     imagining the "observation" case running in reverse time order,
      !>     and vice versa.
      !>
      !>     One may reasonably object to using the term "observer" in the
      !>     transmission case, in which radiation is emitted from the
      !>     observer's location. The terminology was retained for
      !>     consistency with earlier documentation.
      !>
      !>     Below, we indicate the aberration corrections to use for some
      !>     common applications:
      !>
      !>        1) Find the apparent direction of a target for a remote-sensing
      !>           observation.
      !>
      !>              Use 'LT+S' or 'CN+S: apply both light time and stellar
      !>              aberration corrections.
      !>
      !>           Note that using light time corrections alone ('LT' or 'CN')
      !>           is generally not a good way to obtain an approximation to
      !>           an apparent target vector: since light time and stellar
      !>           aberration corrections often partially cancel each other,
      !>           it may be more accurate to use no correction at all than to
      !>           use light time alone.
      !>
      !>        2) Find the corrected pointing direction to radiate a signal
      !>           to a target. This computation is often applicable for
      !>           implementing communications sessions.
      !>
      !>              Use 'XLT+S' or 'XCN+S: apply both light time and stellar
      !>              aberration corrections for transmission.
      !>
      !>        3) Compute the apparent position of a target body relative
      !>           to a star or other distant object.
      !>
      !>              Use 'LT', 'CN', 'LT+S', or 'CN+S' as needed to match the
      !>              correction applied to the position of the distant
      !>              object. For example, if a star position is obtained from
      !>              a catalog, the position vector may not be corrected for
      !>              stellar aberration. In this case, to find the angular
      !>              separation of the star and the limb of a planet, the
      !>              vector from the observer to the planet should be
      !>              corrected for light time but not stellar aberration.
      !>
      !>        4) Obtain an uncorrected state vector derived directly from
      !>           data in an SPK file.
      !>
      !>              Use 'NONE'.
      !>
      !>        5) Use a geometric state vector as a low-accuracy estimate
      !>           of the apparent state for an application where execution
      !>           speed is critical:
      !>
      !>              Use 'NONE'.
      !>
      !>        6) While this routine cannot perform the relativistic
      !>           aberration corrections required to compute states
      !>           with the highest possible accuracy, it can supply the
      !>           geometric states required as inputs to these computations:
      !>
      !>              Use 'NONE', then apply high-accuracy aberration
      !>              corrections (not available in the SPICE Toolkit).
      !>
      !>     Below, we discuss in more detail how the aberration corrections
      !>     applied by this routine are computed.
      !>
      !>     Geometric case
      !>     ==============
      !>
      !>        SPKAPP begins by computing the geometric position T(ET) of the
      !>        target body relative to the solar system barycenter (SSB).
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the geometric position of the target body relative to the
      !>        observer. The one-way light time, LT, is given by
      !>
      !>                  | T(ET) - O(ET) |
      !>           LT = -------------------
      !>                          c
      !>
      !>        The geometric relationship between the observer, target, and
      !>        solar system barycenter is as shown:
      !>
      !>           SSB ---> O(ET)
      !>            |      /
      !>            |     /
      !>            |    /
      !>            |   /  T(ET) - O(ET)
      !>            V  V
      !>           T(ET)
      !>
      !>        The returned state consists of the position vector
      !>
      !>           T(ET) - O(ET)
      !>
      !>        and a velocity obtained by taking the difference of the
      !>        corresponding velocities.  In the geometric case, the
      !>        returned velocity is actually the time derivative of the
      !>        position.
      !>
      !>     Reception case
      !>     ==============
      !>
      !>        When any of the options 'LT', 'CN', 'LT+S', 'CN+S' is
      !>        selected, SPKAPP computes the position of the target body at
      !>        epoch ET-LT, where LT is the one-way light time. Let T(t) and
      !>        O(t) represent the positions of the target and observer
      !>        relative to the solar system barycenter at time t; then LT is
      !>        the solution of the light-time equation
      !>
      !>                  | T(ET-LT) - O(ET) |
      !>           LT = ------------------------                            (1)
      !>                           c
      !>
      !>        The ratio
      !>
      !>            | T(ET) - O(ET) |
      !>          ---------------------                                     (2)
      !>                    c
      !>
      !>        is used as a first approximation to LT; inserting (2) into the
      !>        RHS of the light-time equation (1) yields the "one-iteration"
      !>        estimate of the one-way light time. Repeating the process
      !>        until the estimates of LT converge yields the "converged
      !>        Newtonian" light time estimate.
      !>
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the position of the target body relative to the observer:
      !>        T(ET-LT) - O(ET).
      !>
      !>           SSB ---> O(ET)
      !>            | \     |
      !>            |  \    |
      !>            |   \   | T(ET-LT) - O(ET)
      !>            |    \  |
      !>            V     V V
      !>           T(ET)  T(ET-LT)
      !>
      !>        The position component of the light-time corrected state
      !>        is the vector
      !>
      !>           T(ET-LT) - O(ET)
      !>
      !>        The velocity component of the light-time corrected state
      !>        is the difference
      !>
      !>           T_vel(ET-LT) - O_vel(ET)
      !>
      !>        where T_vel and O_vel are, respectively, the velocities of
      !>        the target and observer relative to the solar system
      !>        barycenter at the epochs ET-LT and ET.
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated toward the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as follows:
      !>
      !>           Let r be the light time corrected vector from the observer
      !>           to the object, and v be the velocity of the observer with
      !>           respect to the solar system barycenter. Let w be the angle
      !>           between them. The aberration angle phi is given by
      !>
      !>              sin(phi) = v sin(w) / c
      !>
      !>           Let h be the vector given by the cross product
      !>
      !>              h = r X v
      !>
      !>           Rotate r by phi radians about h to obtain the apparent
      !>           position of the object.
      !>
      !>        The velocity component of the output state STARG is
      !>        not corrected for stellar aberration.
      !>
      !>     Transmission case
      !>     ==================
      !>
      !>        When any of the options 'XLT', 'XCN', 'XLT+S', 'XCN+S' are
      !>        selected, SPKAPP computes the position of the target body T at
      !>        epoch ET+LT, where LT is the one-way light time. LT is the
      !>        solution of the light-time equation
      !>
      !>                  | T(ET+LT) - O(ET) |
      !>           LT = ------------------------                            (3)
      !>                            c
      !>
      !>        Subtracting the geometric position of the observer, O(ET),
      !>        gives the position of the target body relative to the
      !>        observer: T(ET-LT) - O(ET).
      !>
      !>                   SSB --> O(ET)
      !>                  / |    *
      !>                 /  |  *  T(ET+LT) - O(ET)
      !>                /   |*
      !>               /   *|
      !>              V  V  V
      !>          T(ET+LT)  T(ET)
      !>
      !>        The position component of the light-time corrected state
      !>        is the vector
      !>
      !>           T(ET+LT) - O(ET)
      !>
      !>        The velocity component of the light-time corrected state
      !>        is the difference
      !>
      !>           T_vel(ET+LT) - O_vel(ET)
      !>
      !>        where T_vel and O_vel are, respectively, the velocities of
      !>        the target and observer relative to the solar system
      !>        barycenter at the epochs ET+LT and ET.
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated away from the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as in the reception case, but the sign of the
      !>        rotation angle is negated.
      !>
      !>        The velocity component of the output state STARG is
      !>        not corrected for stellar aberration.
      !>
      !>     Neither special nor general relativistic effects are accounted
      !>     for in the aberration corrections performed by this routine.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, SPKSSB and SPKAPP are used
      !>     to display the position of Io (body 501) as seen from the
      !>     Voyager 2 spacecraft (Body -32) at a series of epochs.
      !>
      !>     Normally, one would call the high-level reader SPKEZR to obtain
      !>     state vectors. The example below illustrates the interface
      !>     of this routine but is not intended as a recommendation on
      !>     how to use the SPICE SPK subsystem.
      !>
      !>     The use of integer ID codes is necessitated by the low-level
      !>     interface of this routine.
      !>
      !>        IO    = 501
      !>        VGR2  = -32
      !>
      !>        DO WHILE ( EPOCH .LE. END )
      !>
      !>           CALL SPKSSB (  VGR2,   EPOCH,  'J2000',  STVGR2  )
      !>           CALL SPKAPP (  IO,     EPOCH,  'J2000',  STVGR2,
      !>       .                 'LT+S',  STIO,    LT               )
      !>
      !>           CALL RECRAD (  STIO,   RANGE,   RA,      DEC     )
      !>           WRITE (*,*)  RA * DPR(),  DEC * DPR()
      !>
      !>           EPOCH = EPOCH + DELTA
      !>
      !>        END DO
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by SPKAPP must be loaded
      !>         (normally by the SPICELIB kernel loader FURNSH) before
      !>         this routine is called.
      !>
      !>     2)  Unlike most other SPK state computation routines, this
      !>         routine requires that the input state be relative to an
      !>         inertial reference frame. Non-inertial frames are not
      !>         supported by this routine.
      !>
      !>     3)  In a future version of this routine, the implementation
      !>         of the aberration corrections may be enhanced to improve
      !>         accuracy.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     J.M. Lynch         (JPL)
      !>     H.A. Neilan        (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 3.1.1, 26-OCT-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 3.1.0, 04-JUL-2014 (NJB) (BVS)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>     Last update was 21-SEP-2013 (BVS)
      !>
      !>        Updated to call LJUCRS instead of CMPRSS/UCASE.
      !>
      !>-    SPICELIB Version 3.0.3, 18-MAY-2010 (BVS)
      !>
      !>        Index lines now state that this routine is deprecated.
      !>
      !>-    SPICELIB Version 3.0.2, 08-JAN-2008 (NJB)
      !>
      !>        The $Abstract section of the header was updated to
      !>        indicate that this routine has been deprecated.
      !>
      !>-    SPICELIB Version 3.0.1, 20-OCT-2003 (EDW)
      !>
      !>        Added mention that LT returns in seconds.
      !>        Corrected spelling errors.
      !>
      !>-    SPICELIB Version 3.0.0, 18-DEC-2001 (NJB)
      !>
      !>        Updated to handle aberration corrections for transmission
      !>        of radiation. Formerly, only the reception case was
      !>        supported. The header was revised and expanded to explain
      !>        the functionality of this routine in more detail.
      !>
      !>-    SPICELIB Version 2.1.0, 09-JUL-1996 (WLT)
      !>
      !>        Corrected the description of LT in the Detailed Output
      !>        section of the header.
      !>
      !>-    SPICELIB Version 2.0.0, 22-MAY-1995 (WLT)
      !>
      !>        The routine was modified to support the options 'CN' and
      !>        'CN+S' aberration corrections. Moreover, diagnostics were
      !>        added to check for reference frames that are not recognized
      !>        inertial frames.
      !>
      !>-    SPICELIB Version 1.1.2, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.1.1, 06-MAR-1991 (JML)
      !>
      !>        In the example program, the calling sequence of SPKAPP
      !>        was corrected.
      !>
      !>-    SPICELIB Version 1.1.0, 25-MAY-1990 (HAN)
      !>
      !>        The local variable CORR was added to eliminate a
      !>        run-time error that occurred when SPKAPP was determining
      !>        what corrections to apply to the state.
      !>
      !>-    SPICELIB Version 1.0.1, 22-MAR-1990 (HAN)
      !>
      !>        Literature references added to the header.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 2.0.0, 22-MAY-1995 (WLT)
      !>
      !>        The routine was modified to support the options 'CN' and
      !>        'CN+S' aberration corrections. Moreover, diagnostics were
      !>        added to check for reference frames that are not recognized
      !>        inertial frames.
      !>
      !>-    SPICELIB Version 1.1.0, 25-MAY-1990 (HAN)
      !>
      !>        The local variable CORR was added to eliminate a run-time
      !>        error that occurred when SPKAPP was determining what
      !>        corrections to apply to the state. If the literal string
      !>        'LT' was assigned to ABCORR, SPKAPP attempted to look at
      !>        ABCORR(3:4). Because ABCORR is a passed length argument, its
      !>        length is not guaranteed, and those positions may not exist.
      !>        Searching beyond the bounds of a string resulted in a
      !>        run-time error at NAIF because NAIF compiles SPICELIB using the
      !>        CHECK=BOUNDS option for the DEC VAX/VMX DCL FORTRAN command.
      !>        Also, without the local variable CORR, SPKAPP would have to
      !>        modify the value of a passed argument, ABCORR. That's a no no.
      module subroutine spkapp ( ctx, targ, et, ref, sobs, abcorr, starg, lt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: odd, vnorm
      use pepper_strings, only: ljucrs
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of observer's state.
      real(wp), intent(in) :: sobs     ( 6 )  !! State of observer wrt. solar system barycenter.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(out) :: starg    ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
!
!     Local variables
!
      logical :: xmit  !! (PEPPER) copy of the saved flag for this call
      logical :: uselt  !! (PEPPER) copy of the saved flag for this call
      logical :: usecn  !! (PEPPER) copy of the saved flag for this call
      logical :: usestl  !! (PEPPER) copy of the saved flag for this call
      character(corlen) :: corr
      real(wp) :: sapos  ( 3 )
      real(wp) :: tstate ( 6 )
      integer(ip) :: i
      integer(ip) :: ltsign
      integer(ip) :: maxitr
      integer(ip) :: refid
      if ( .not. allocated ( ctx%spkapp_state ) ) allocate ( ctx%spkapp_state )
      associate ( first => ctx%spkapp_state%first, &
                  flags => ctx%spkapp_state%flags, &
                  prvcor => ctx%spkapp_state%prvcor, &
                  c_usecn => ctx%spkapp_state%usecn, &
                  c_usestl => ctx%spkapp_state%usestl, &
                  c_uselt => ctx%spkapp_state%uselt, &
                  c_xmit => ctx%spkapp_state%xmit )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
!        Remove leading and embedded white space from the aberration
!        correction flag and convert to upper case.
!
         call ljucrs ( 0, abcorr, corr )

!
!        Locate the flag in our list of flags.
!
         i = findloc(flags, corr, dim=1)

         if ( i == 0 ) then

            call ctx%setmsg ( 'Requested aberration correction # is ' // &
                          'not supported.'                         )
            call ctx%errch  ( '#', abcorr                              )
            call ctx%sigerr ( 'SPICE(SPKINVALIDOPTION)'                )
            return

         end if

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction.
!
         c_xmit    =  i > ixcns

         c_uselt   =       ( i == ixlt  ) .or. ( i == ixlts  ) &
                    .or. ( i == ixxlt ) .or. ( i == ixxlts )

         c_usestl  =  ( i > 1 )  .and.  odd(i)

         c_usecn   =       ( i == ixcn  ) .or. ( i == ixcns  ) &
                    .or. ( i == ixxcn ) .or. ( i == ixxcns )

         first   = .false.

      end if
      !
      !     PEPPER: the routine may be called again, for a dynamic frame,
      !     before it returns (SPICELIB had copies per recursion level); the
      !     saved flags are copied here, and only the copies are used below.
      !
      xmit = c_xmit
      uselt = c_uselt
      usecn = c_usecn
      usestl = c_usestl

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Determine the sign of the light time offset.
!
      if ( xmit ) then
         ltsign = 1
      else
         ltsign = -1
      end if

!
!     Find the geometric state of the target body with respect to the
!     solar system barycenter. Subtract the state of the observer
!     to get the relative state. Use this to compute the one-way
!     light time.
!
      call spkssb ( ctx, targ,  et,   ref, starg  )
      tstate = starg - sobs
      starg = tstate

      lt = vnorm  ( starg ) / clight

!
!     To correct for light time, find the state of the target body
!     at the current epoch minus the one-way light time. Note that
!     the observer remains where he is.
!
      if ( uselt ) then

         maxitr = 1

      else if ( usecn ) then

         maxitr = 3

      else

         maxitr = 0

      end if

      do i = 1, maxitr

         call spkssb ( ctx, targ,  et + ltsign*lt,  ref,  starg  )
         tstate = starg - sobs
         starg = tstate
         lt = vnorm  ( starg ) / clight

      end do

!
!     At this point, STARG contains the light time corrected
!     state of the target relative to the observer.
!
!     If stellar aberration correction is requested, perform it now.
!
!     Stellar aberration corrections are not applied to the target's
!     velocity.
!
      if ( usestl ) then

         if ( xmit ) then
!
!           This is the transmission case.
!
!           Compute the position vector obtained by applying
!           "reception" stellar aberration to STARG.
!
            call stlabx ( ctx, starg, sobs(4), sapos )
            starg(1:3) = sapos

         else
!
!           This is the reception case.
!
!           Compute the position vector obtained by applying
!           "reception" stellar aberration to STARG.
!
            call stelab ( ctx, starg, sobs(4), sapos )
            starg(1:3) = sapos

         end if

      end if

      return
      end associate
      end subroutine spkapp

      !> Return the state (position and velocity) of a target body
      !> relative to an observer specified by its state and
      !> acceleration relative to the solar system barycenter. The
      !> returned state may be optionally corrected for light time
      !> and stellar aberration. All input and output vectors are
      !> expressed relative to an inertial reference frame.
      !>
      !> This routine supersedes SPKAPP.
      !>
      !> SPICE users normally should call the high-level API routines
      !> SPKEZR or SPKEZ rather than this routine.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a state vector whose position
      !>              component points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past
      !>              J2000 TDB, at which the state of the target body
      !>              relative to the observer is to be computed.  ET
      !>              refers to time at the observer's location.
      !>
      !>     REF      is the inertial reference frame with respect to which
      !>              the input state STOBS, the input acceleration ACCOBS,
      !>              and the output state STARG are expressed. REF must be
      !>              recognized by the SPICE Toolkit. The acceptable
      !>              frames are listed in the Frames Required Reading, as
      !>              well as in the SPICELIB routine CHGIRF.
      !>
      !>              Case and blanks are not significant in the string
      !>              REF.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              to the state of the target body to account for one-way
      !>              light time and stellar aberration. See the discussion
      !>              in the header of SPKEZR for recommendations on
      !>              how to choose aberration corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric state of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the state of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            state obtained with the 'LT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            state of the target---the position and
      !>                            velocity of the target as seen by the
      !>                            observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section of
      !>                            SPKEZR for a discussion of precision of
      !>                            light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            state of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            state obtained with the 'XLT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The position component of
      !>                            the computed target state indicates the
      !>                            direction that photons emitted from the
      !>                            observer's location must be "aimed" to
      !>                            hit the target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     STOBS    is the geometric state of the observer relative to
      !>              the solar system barycenter at ET. STOBS is expressed
      !>              relative to the reference frame designated by REF.
      !>              The target and observer define a state vector whose
      !>              position component points from the observer to the
      !>              target.
      !>
      !>     ACCOBS   is the geometric acceleration of the observer
      !>              relative to the solar system barycenter at ET. This
      !>              is the derivative with respect to time of the
      !>              velocity portion of STOBS. ACCOBS is expressed
      !>              relative to the reference frame designated by REF.
      !>
      !>              ACCOBS is used for computing stellar aberration
      !>              corrected velocity. If stellar aberration corrections
      !>              are not specified by ABCORR, ACCOBS is ignored; the
      !>              caller need not provide a valid input value in this
      !>              case.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position
      !>              and velocity of the target body relative to the
      !>              specified observer. STARG is corrected for the
      !>              specified aberrations, and is expressed with respect
      !>              to the inertial reference frame designated by REF.
      !>              The first three components of STARG represent the x-,
      !>              y- and z-components of the target's position; last
      !>              three components form the corresponding velocity
      !>              vector.
      !>
      !>              The position component of STARG points from the
      !>              observer's location at ET to the aberration-corrected
      !>              location of the target. Note that the sense of the
      !>              position vector is independent of the direction of
      !>              radiation travel implied by the aberration
      !>              correction.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target state is corrected
      !>              for light time, then LT is the one-way light time
      !>              between the observer and the light time-corrected
      !>              target location.
      !>
      !>     DLT      is the derivative with respect to barycentric
      !>              dynamical time of the one way light time between
      !>              target and observer:
      !>
      !>                 DLT = d(LT)/d(ET)
      !>
      !>              DLT can also be described as the rate of change of
      !>              one way light time. DLT is unitless, since LT and
      !>              ET both have units of TDB seconds.
      !>
      !>              If the observer and target are at the same position,
      !>              then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the value of ABCORR is not recognized, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     2)  If ABCORR calls for stellar aberration but not light
      !>         time corrections, the error SPICE(NOTSUPPORTED) is
      !>         signaled.
      !>
      !>     3)  If ABCORR calls for relativistic light time corrections, the
      !>         error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     4)  If the reference frame requested is not a recognized
      !>         inertial reference frame, the error SPICE(BADFRAME)
      !>         is signaled.
      !>
      !>     5)  If the state of the target relative to the solar system
      !>         barycenter cannot be computed, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     6)  If the observer and target are at the same position,
      !>         then DLT is set to zero. This situation could arise,
      !>         for example, when the observer is Mars and the target
      !>         is the Mars barycenter.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any such
      !>     kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level SPK API routines that can
      !>     perform both light time and stellar aberration corrections.
      !>
      !>     User applications normally will not need to call this routine
      !>     directly. However, this routine can improve run-time efficiency
      !>     in situations where many targets are observed from the same
      !>     location at the same time. In such cases, the state and
      !>     acceleration of the observer relative to the solar system
      !>     barycenter need be computed only once per look-up epoch.
      !>
      !>     When apparent positions, rather than apparent states, are
      !>     required, consider using the high-level position-only API
      !>     routines
      !>
      !>        SPKPOS
      !>        SPKEZP
      !>
      !>     or the low-level, position-only analog of this routine
      !>
      !>        SPKAPO
      !>
      !>     In general, the position-only routines are more efficient.
      !>
      !>     See the header of the routine SPKEZR for a detailed discussion
      !>     of aberration corrections.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Look up a sequence of states of the Moon as seen from the
      !>        Earth. Use light time and stellar aberration corrections.
      !>        Compute the first state for the epoch 2000 JAN 1 12:00:00 TDB;
      !>        compute subsequent states at intervals of 1 hour. For each
      !>        epoch, display the states, the one way light time between
      !>        target and observer, and the rate of change of the one way
      !>        light time.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: spkaps_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de418.bsp                     Planetary ephemeris
      !>              pck00008.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0008.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de418.bsp',
      !>                                  'pck00008.tpc',
      !>                                  'naif0008.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPKAPS_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     Local constants
      !>C
      !>C     The meta-kernel name shown here refers to a file whose
      !>C     contents are those shown above. This file and the kernels
      !>C     it references must exist in your current working
      !>C     directory.
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'spkaps_ex1.tm' )
      !>C
      !>C     Use a time step of 1 hour; look up 5 states.
      !>C
      !>      DOUBLE PRECISION      STEP
      !>      PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>      INTEGER               MAXITR
      !>      PARAMETER           ( MAXITR = 5 )
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      ACC    ( 3 )
      !>      DOUBLE PRECISION      DLT
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      STATE  ( 6 )
      !>      DOUBLE PRECISION      STATE0 ( 6 )
      !>      DOUBLE PRECISION      STATE2 ( 6 )
      !>      DOUBLE PRECISION      STOBS  ( 6 )
      !>      DOUBLE PRECISION      TDELTA
      !>      INTEGER               I
      !>
      !>C
      !>C     Load the SPK and LSK kernels via the meta-kernel.
      !>C
      !>      CALL FURNSH ( META )
      !>C
      !>C     Convert the start time to seconds past J2000 TDB.
      !>C
      !>      CALL STR2ET ( '2000 JAN 1 12:00:00 TDB', ET0 )
      !>C
      !>C     Step through a series of epochs, looking up a
      !>C     state vector at each one.
      !>C
      !>      DO I = 1, MAXITR
      !>
      !>         ET = ET0 + (I-1)*STEP
      !>
      !>C
      !>C        Look up a state vector at epoch ET using the
      !>C        following inputs:
      !>C
      !>C           Target:                 Moon (NAIF ID code 301)
      !>C           Reference frame:        J2000
      !>C           Aberration correction:  Light time and stellar
      !>C                                   aberration ('LT+S')
      !>C           Observer:               Earth (NAIF ID code 399)
      !>C
      !>C        Before we can execute this computation, we'll need the
      !>C        geometric state and acceleration of the observer
      !>C        relative to the solar system barycenter at ET,
      !>C        expressed relative to the J2000 reference frame. First
      !>C        find the state:
      !>C
      !>         CALL SPKSSB ( 399, ET, 'J2000', STOBS )
      !>C
      !>C        Next compute the acceleration. We numerically
      !>C        differentiate the velocity using a quadratic
      !>C        approximation:
      !>C
      !>         TDELTA = 1.D0
      !>
      !>         CALL SPKSSB ( 399, ET-TDELTA, 'J2000', STATE0 )
      !>         CALL SPKSSB ( 399, ET+TDELTA, 'J2000', STATE2 )
      !>
      !>         CALL QDERIV ( 3, STATE0(4), STATE2(4), TDELTA, ACC )
      !>C
      !>C        Now compute the desired state vector:
      !>C
      !>         CALL SPKAPS ( 301,   ET,  'J2000', 'LT+S',
      !>     .                 STOBS, ACC, STATE,    LT,   DLT )
      !>
      !>         WRITE (*,*) 'ET = ', ET
      !>         WRITE (*,*) 'J2000 x-position (km):   ', STATE(1)
      !>         WRITE (*,*) 'J2000 y-position (km):   ', STATE(2)
      !>         WRITE (*,*) 'J2000 z-position (km):   ', STATE(3)
      !>         WRITE (*,*) 'J2000 x-velocity (km/s): ', STATE(4)
      !>         WRITE (*,*) 'J2000 y-velocity (km/s): ', STATE(5)
      !>         WRITE (*,*) 'J2000 z-velocity (km/s): ', STATE(6)
      !>         WRITE (*,*) 'One-way light time (s):  ', LT
      !>         WRITE (*,*) 'Light time rate:         ', DLT
      !>         WRITE (*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         ET =    0.0000000000000000
      !>         J2000 x-position (km):     -291584.61369497533
      !>         J2000 y-position (km):     -266693.40583162551
      !>         J2000 z-position (km):     -76095.653209237149
      !>         J2000 x-velocity (km/s):   0.64343915743508395
      !>         J2000 y-velocity (km/s):  -0.66606587365741410
      !>         J2000 z-velocity (km/s):  -0.30131006342946742
      !>         One-way light time (s):     1.3423106103251679
      !>         Light time rate:            1.0731690869897750E-007
      !>
      !>         ET =    3600.0000000000000
      !>         J2000 x-position (km):     -289256.45942322229
      !>         J2000 y-position (km):     -269080.60545907740
      !>         J2000 z-position (km):     -77177.352771302132
      !>         J2000 x-velocity (km/s):   0.64997032016926526
      !>         J2000 y-velocity (km/s):  -0.66014825329341664
      !>         J2000 z-velocity (km/s):  -0.29963041790724715
      !>         One-way light time (s):     1.3426939548635302
      !>         Light time rate:            1.0565259895222426E-007
      !>
      !>         ET =    7200.0000000000000
      !>         J2000 x-position (km):     -286904.89654239739
      !>         J2000 y-position (km):     -271446.41676468350
      !>         J2000 z-position (km):     -78252.965533623050
      !>         J2000 x-velocity (km/s):   0.65644388315539315
      !>         J2000 y-velocity (km/s):  -0.65418355204586442
      !>         J2000 z-velocity (km/s):  -0.29792853294482308
      !>         One-way light time (s):     1.3430713117337547
      !>         Light time rate:            1.0399045689875861E-007
      !>
      !>         ET =    10800.000000000000
      !>         J2000 x-position (km):     -284530.13302756584
      !>         J2000 y-position (km):     -273790.67111559171
      !>         J2000 z-position (km):     -79322.411703917489
      !>         J2000 x-velocity (km/s):   0.66285950473048116
      !>         J2000 y-velocity (km/s):  -0.64817224685146524
      !>         J2000 z-velocity (km/s):  -0.29620455846903732
      !>         One-way light time (s):     1.3434426890693671
      !>         Light time rate:            1.0233066524342374E-007
      !>
      !>         ET =    14400.000000000000
      !>         J2000 x-position (km):     -282132.37807791750
      !>         J2000 y-position (km):     -276113.20159697317
      !>         J2000 z-position (km):     -80385.612030562901
      !>         J2000 x-velocity (km/s):   0.66921684649247459
      !>         J2000 y-velocity (km/s):  -0.64211481528028158
      !>         J2000 z-velocity (km/s):  -0.29445864490384888
      !>         One-way light time (s):     1.3438080956559786
      !>         Light time rate:            1.0067340363005083E-007
      !>
      !>## Restrictions
      !>
      !>     1)  This routine should not be used to compute geometric states.
      !>         Instead, use SPKEZR, SPKEZ, or SPKGEO. SPKGEO, which is called
      !>         by SPKEZR and SPKEZ, introduces less round-off error when the
      !>         observer and target have a common center that is closer to
      !>         both objects than is the solar system barycenter.
      !>
      !>     2)  The kernel files to be used by SPKAPS must be loaded
      !>         (normally by the SPICELIB kernel loader FURNSH) before
      !>         this routine is called.
      !>
      !>     3)  Unlike most other SPK state computation routines, this
      !>         routine requires that the output state be relative to an
      !>         inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 26-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard. Updated
      !>        example's meta-kernel.
      !>
      !>        Bug fix: ABCORR now is parsed using ZZVALCOR. This improves
      !>        error checking. Removed unnecessary in-line error checking
      !>        now provided by ZZVALCOR.
      !>
      !>-    SPICELIB Version 1.1.0, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>     Last update was 15-APR-2014 (NJB)
      !>
      !>        Added a FAILED() call to prevent numeric problems
      !>        resulting from uninitialized values.
      !>
      !>-    SPICELIB Version 1.0.0, 11-JAN-2008 (NJB)
      recursive module subroutine spkaps ( ctx, targ, et, ref, abcorr, stobs, accobs, starg, lt, dlt )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(in) :: stobs  ( 6 )  !! State of the observer relative to the SSB.
      real(wp), intent(in) :: accobs ( 3 )  !! Acceleration of the observer relative to the SSB.
      real(wp), intent(out) :: starg  ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
      logical :: xmit  !! (PEPPER) copy of the saved flag for this call
      logical :: usestl  !! (PEPPER) copy of the saved flag for this call
      real(wp) :: corpos ( 3 )
      real(wp) :: corvel ( 3 )
      real(wp) :: dpcorr ( 3 )
      real(wp) :: pcorr  ( 3 )
      integer(ip) :: refid
      logical :: attblk ( nabcor )
      if ( .not. allocated ( ctx%spkaps_state ) ) allocate ( ctx%spkaps_state )
      associate ( first => ctx%spkaps_state%first, &
                  prvcor => ctx%spkaps_state%prvcor, &
                  c_usestl => ctx%spkaps_state%usestl, &
                  c_xmit => ctx%spkaps_state%xmit )
      if ( ctx%failed() ) return

      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USECN indicates converged Newtonian light time correction.
!
!        The above definitions are consistent with those used by
!        ZZPRSCOR.
!
         c_xmit    =  attblk ( xmtidx )
         c_usestl  =  attblk ( stlidx )

         first   = .false.

      end if
      !
      !     PEPPER: the routine may be called again, for a dynamic frame,
      !     before it returns (SPICELIB had copies per recursion level); the
      !     saved flags are copied here, and only the copies are used below.
      !
      xmit = c_xmit
      usestl = c_usestl

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Get the state of the target relative to the observer,
!     optionally corrected for light time.
!
      call spkltc ( ctx, targ,  et,    ref, abcorr, &
                    stobs, starg, lt,  dlt     )

      if ( ctx%failed() ) return

!
!     If stellar aberration corrections are not needed, we're
!     already done.
!
      if ( .not. usestl ) return

!
!     Get the stellar aberration correction and its time derivative.
!
      call zzstelab ( ctx, xmit, accobs, stobs(4), starg, pcorr, dpcorr )

!
!     Adding the stellar aberration correction to the light
!     time-corrected target position yields the position corrected for
!     both light time and stellar aberration.
!
      corpos = pcorr + starg(1:3)
      starg(1:3) = corpos

!
!     Velocity is treated in an analogous manner.
!
      corvel = dpcorr + starg(4:6)
      starg(4:6) = corvel

      return
      end associate
      end subroutine spkaps

      !> Return the position of a target body relative to an observing
      !> body, optionally corrected for light time (planetary aberration)
      !> and stellar aberration.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a position vector which points
      !>              from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past
      !>              J2000 TDB, at which the position of the target body
      !>              relative to the observer is to be computed. ET
      !>              refers to time at the observer's location.
      !>
      !>     REF      is the name of the reference frame relative to which
      !>              the output position vector should be expressed. This
      !>              may be any frame supported by the SPICE system,
      !>              including built-in frames (documented in the Frames
      !>              Required Reading) and frames defined by a loaded
      !>              frame kernel (FK).
      !>
      !>              When REF designates a non-inertial frame, the
      !>              orientation of the frame is evaluated at an epoch
      !>              dependent on the selected aberration correction. See
      !>              the description of the output position vector PTARG
      !>              for details.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to
      !>              the position of the target body to account for
      !>              one-way light time and stellar aberration. See the
      !>              discussion in the $Particulars section for
      !>              recommendations on how to choose aberration
      !>              corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric position of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the position of the target at
      !>                            the moment it emitted photons arriving
      !>                            at the observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            position obtained with the 'LT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            position of the target---the position
      !>                            as seen by the observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section
      !>                            below for a discussion of precision of
      !>                            light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            position of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            position obtained with the 'XLT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The computed target
      !>                            position indicates the direction that
      !>                            photons emitted from the observer's
      !>                            location must be "aimed" to hit the
      !>                            target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     OBS      is the NAIF ID code for the observing body.
      !>
      !>## Detailed Output
      !>
      !>     PTARG    is a Cartesian 3-vector representing the position of
      !>              the target body relative to the specified observer.
      !>              PTARG is corrected for the specified aberrations, and
      !>              is expressed with respect to the reference frame
      !>              specified by REF. The three components of PTARG
      !>              represent the x-, y- and z-components of the target's
      !>              position.
      !>
      !>              PTARG points from the observer's location at ET to
      !>              the aberration-corrected location of the target.
      !>              Note that the sense of this position vector is
      !>              independent of the direction of radiation travel
      !>              implied by the aberration correction.
      !>
      !>              Units are always km.
      !>
      !>              Non-inertial frames are treated as follows: letting
      !>              LTCENT be the one-way light time between the observer
      !>              and the central body associated with the frame, the
      !>              orientation of the frame is evaluated at ET-LTCENT,
      !>              ET+LTCENT, or ET depending on whether the requested
      !>              aberration correction is, respectively, for received
      !>              radiation, transmitted radiation, or is omitted.
      !>              LTCENT is computed using the method indicated by
      !>              ABCORR.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target position is
      !>              corrected for aberrations, then LT is the one-way
      !>              light time between the observer and the light time
      !>              corrected target location.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If name of target or observer cannot be translated to its
      !>         NAIF ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     2)  If the reference frame REF is not a recognized reference
      !>         frame, the error SPICE(UNKNOWNFRAME) is signaled.
      !>
      !>     3)  If the loaded kernels provide insufficient data to compute the
      !>         requested position vector, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     4)  If an error occurs while reading an SPK or other kernel file,
      !>         the error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     5)  If any of the required attributes of the reference frame REF
      !>         cannot be determined, the error SPICE(UNKNOWNFRAME2) is
      !>         signaled.
      !>
      !>## Files
      !>
      !>     This routine computes positions using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. See the routine FURNSH and the SPK
      !>     and KERNEL Required Reading for further information on loading
      !>     (and unloading) kernels.
      !>
      !>     If the output position PTARG is to be expressed relative to a
      !>     non-inertial frame, or if any of the ephemeris data used to
      !>     compute PTARG are expressed relative to a non-inertial frame in
      !>     the SPK files providing those data, additional kernels may be
      !>     needed to enable the reference frame transformations required to
      !>     compute the position. Normally these additional kernels are PCK
      !>     files or frame kernels. Any such kernels must already be loaded
      !>     at the time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine is part of the user interface to the SPICE ephemeris
      !>     system. It allows you to retrieve position information for any
      !>     ephemeris object relative to any other in a reference frame that
      !>     is convenient for further computations.
      !>
      !>     Aberration corrections
      !>     ======================
      !>
      !>     In space science or engineering applications one frequently
      !>     wishes to know where to point a remote sensing instrument, such
      !>     as an optical camera or radio antenna, in order to observe or
      !>     otherwise receive radiation from a target. This pointing problem
      !>     is complicated by the finite speed of light: one needs to point
      !>     to where the target appears to be as opposed to where it actually
      !>     is at the epoch of observation. We use the adjectives
      !>     "geometric," "uncorrected," or "true" to refer to an actual
      !>     position or state of a target at a specified epoch. When a
      !>     geometric position or state vector is modified to reflect how it
      !>     appears to an observer, we describe that vector by any of the
      !>     terms "apparent," "corrected," "aberration corrected," or "light
      !>     time and stellar aberration corrected." The SPICE Toolkit can
      !>     correct for two phenomena affecting the apparent location of an
      !>     object: one-way light time (also called "planetary aberration")
      !>     and stellar aberration.
      !>
      !>     One-way light time
      !>     ------------------
      !>
      !>     Correcting for one-way light time is done by computing, given an
      !>     observer and observation epoch, where a target was when the
      !>     observed photons departed the target's location. The vector from
      !>     the observer to this computed target location is called a "light
      !>     time corrected" vector. The light time correction depends on the
      !>     motion of the target relative to the solar system barycenter, but
      !>     it is independent of the velocity of the observer relative to the
      !>     solar system barycenter. Relativistic effects such as light
      !>     bending and gravitational delay are not accounted for in the
      !>     light time correction performed by this routine.
      !>
      !>     Stellar aberration
      !>     ------------------
      !>
      !>     The velocity of the observer also affects the apparent location
      !>     of a target: photons arriving at the observer are subject to a
      !>     "raindrop effect" whereby their velocity relative to the observer
      !>     is, using a Newtonian approximation, the photons' velocity
      !>     relative to the solar system barycenter minus the velocity of the
      !>     observer relative to the solar system barycenter. This effect is
      !>     called "stellar aberration." Stellar aberration is independent
      !>     of the velocity of the target. The stellar aberration formula
      !>     used by this routine does not include (the much smaller)
      !>     relativistic effects.
      !>
      !>     Stellar aberration corrections are applied after light time
      !>     corrections: the light time corrected target position vector is
      !>     used as an input to the stellar aberration correction.
      !>
      !>     When light time and stellar aberration corrections are both
      !>     applied to a geometric position vector, the resulting position
      !>     vector indicates where the target "appears to be" from the
      !>     observer's location.
      !>
      !>     As opposed to computing the apparent position of a target, one
      !>     may wish to compute the pointing direction required for
      !>     transmission of photons to the target. This also requires
      !>     correction of the geometric target position for the effects of
      !>     light time and stellar aberration, but in this case the
      !>     corrections are computed for radiation traveling *from* the
      !>     observer to the target.
      !>
      !>     The "transmission" light time correction yields the target's
      !>     location as it will be when photons emitted from the observer's
      !>     location at ET arrive at the target. The transmission stellar
      !>     aberration correction is the inverse of the traditional stellar
      !>     aberration correction: it indicates the direction in which
      !>     radiation should be emitted so that, using a Newtonian
      !>     approximation, the sum of the velocity of the radiation relative
      !>     to the observer and of the observer's velocity, relative to the
      !>     solar system barycenter, yields a velocity vector that points in
      !>     the direction of the light time corrected position of the target.
      !>
      !>     One may object to using the term "observer" in the transmission
      !>     case, in which radiation is emitted from the observer's location.
      !>     The terminology was retained for consistency with earlier
      !>     documentation.
      !>
      !>     Below, we indicate the aberration corrections to use for some
      !>     common applications:
      !>
      !>        1) Find the apparent direction of a target for a remote-sensing
      !>           observation.
      !>
      !>              Use 'LT+S' or 'CN+S: apply both light time and stellar
      !>              aberration corrections.
      !>
      !>           Note that using light time corrections alone ('LT' or 'CN')
      !>           is generally not a good way to obtain an approximation to
      !>           an apparent target vector: since light time and stellar
      !>           aberration corrections often partially cancel each other,
      !>           it may be more accurate to use no correction at all than to
      !>           use light time alone.
      !>
      !>        2) Find the corrected pointing direction to radiate a signal
      !>           to a target. This computation is often applicable for
      !>           implementing communications sessions.
      !>
      !>              Use 'XLT+S' or 'XCN+S: apply both light time and stellar
      !>              aberration corrections for transmission.
      !>
      !>        3) Compute the apparent position of a target body relative
      !>           to a star or other distant object.
      !>
      !>              Use 'LT', 'CN', 'LT+S', or 'CN+S' as needed to match the
      !>              correction applied to the position of the distant
      !>              object. For example, if a star position is obtained from
      !>              a catalog, the position vector may not be corrected for
      !>              stellar aberration. In this case, to find the angular
      !>              separation of the star and the limb of a planet, the
      !>              vector from the observer to the planet should be
      !>              corrected for light time but not stellar aberration.
      !>
      !>        4) Obtain an uncorrected position vector derived directly from
      !>           data in an SPK file.
      !>
      !>              Use 'NONE'.
      !>
      !>        5) Use a geometric position vector as a low-accuracy estimate
      !>           of the apparent position for an application where execution
      !>           speed is critical.
      !>
      !>              Use 'NONE'.
      !>
      !>        6) While this routine cannot perform the relativistic
      !>           aberration corrections required to compute positions
      !>           with the highest possible accuracy, it can supply the
      !>           geometric positions required as inputs to these
      !>           computations.
      !>
      !>              Use 'NONE', then apply high-accuracy aberration
      !>              corrections (not available in the SPICE Toolkit).
      !>
      !>     Below, we discuss in more detail how the aberration corrections
      !>     applied by this routine are computed.
      !>
      !>        Geometric case
      !>        ==============
      !>
      !>        SPKEZP begins by computing the geometric position T(ET) of the
      !>        target body relative to the solar system barycenter (SSB).
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the geometric position of the target body relative to the
      !>        observer. The one-way light time, LT, is given by
      !>
      !>                  | T(ET) - O(ET) |
      !>           LT = -------------------
      !>                          c
      !>
      !>        The geometric relationship between the observer, target, and
      !>        solar system barycenter is as shown:
      !>
      !>           SSB ---> O(ET)
      !>            |      /
      !>            |     /
      !>            |    /
      !>            |   /  T(ET) - O(ET)
      !>            V  V
      !>           T(ET)
      !>
      !>        The returned position vector is
      !>
      !>           T(ET) - O(ET)
      !>
      !>        Reception case
      !>        ==============
      !>
      !>        When any of the options 'LT', 'CN', 'LT+S', 'CN+S' is selected
      !>        for ABCORR, SPKEZP computes the position of the target body at
      !>        epoch ET-LT, where LT is the one-way light time. Let T(t) and
      !>        O(t) represent the positions of the target and observer
      !>        relative to the solar system barycenter at time t; then LT is
      !>        the solution of the light-time equation
      !>
      !>                  | T(ET-LT) - O(ET) |
      !>           LT = ------------------------                            (1)
      !>                           c
      !>
      !>        The ratio
      !>
      !>            | T(ET) - O(ET) |
      !>          ---------------------                                     (2)
      !>                    c
      !>
      !>        is used as a first approximation to LT; inserting (2) into the
      !>        right hand side of the light-time equation (1) yields the
      !>        "one-iteration" estimate of the one-way light time ("LT").
      !>        Repeating the process until the estimates of LT converge
      !>        yields the "converged Newtonian" light time estimate ("CN").
      !>
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the position of the target body relative to the observer:
      !>        T(ET-LT) - O(ET).
      !>
      !>           SSB ---> O(ET)
      !>            | \     |
      !>            |  \    |
      !>            |   \   | T(ET-LT) - O(ET)
      !>            |    \  |
      !>            V     V V
      !>           T(ET)  T(ET-LT)
      !>
      !>        The light time corrected position vector is
      !>
      !>           T(ET-LT) - O(ET)
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated toward the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as follows:
      !>
      !>           Let r be the light time corrected vector from the observer
      !>           to the object, and v be the velocity of the observer with
      !>           respect to the solar system barycenter. Let w be the angle
      !>           between them. The aberration angle phi is given by
      !>
      !>              sin(phi) = v sin(w) / c
      !>
      !>           Let h be the vector given by the cross product
      !>
      !>              h = r X v
      !>
      !>           Rotate r by phi radians about h to obtain the apparent
      !>           position of the object.
      !>
      !>        Transmission case
      !>        ==================
      !>
      !>        When any of the options 'XLT', 'XCN', 'XLT+S', 'XCN+S' is
      !>        selected, SPKEZP computes the position of the target body T at
      !>        epoch ET+LT, where LT is the one-way light time. LT is the
      !>        solution of the light-time equation
      !>
      !>                  | T(ET+LT) - O(ET) |
      !>           LT = ------------------------                            (3)
      !>                            c
      !>
      !>        Subtracting the geometric position of the observer, O(ET),
      !>        gives the position of the target body relative to the
      !>        observer: T(ET-LT) - O(ET).
      !>
      !>                   SSB --> O(ET)
      !>                  / |    *
      !>                 /  |  *  T(ET+LT) - O(ET)
      !>                /   |*
      !>               /   *|
      !>              V  V  V
      !>          T(ET+LT)  T(ET)
      !>
      !>        The light-time corrected position vector is
      !>
      !>           T(ET+LT) - O(ET)
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated away from the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as in the reception case, but the sign of the
      !>        rotation angle is negated.
      !>
      !>     Precision of light time corrections
      !>     ===================================
      !>
      !>        Corrections using one iteration of the light time solution
      !>        ----------------------------------------------------------
      !>
      !>        When the requested aberration correction is 'LT', 'LT+S',
      !>        'XLT', or 'XLT+S', only one iteration is performed in the
      !>        algorithm used to compute LT.
      !>
      !>        The relative error in this computation
      !>
      !>           | LT_ACTUAL - LT_COMPUTED |  /  LT_ACTUAL
      !>
      !>        is at most
      !>
      !>            (V/C)**2
      !>           ----------
      !>            1 - (V/C)
      !>
      !>        which is well approximated by (V/C)**2, where V is the
      !>        velocity of the target relative to an inertial frame and C is
      !>        the speed of light.
      !>
      !>        For nearly all objects in the solar system V is less than 60
      !>        km/sec. The value of C is ~300000 km/sec. Thus the
      !>        one-iteration solution for LT has a potential relative error
      !>        of not more than 4e-8. This is a potential light time error of
      !>        approximately 2e-5 seconds per astronomical unit of distance
      !>        separating the observer and target. Given the bound on V cited
      !>        above:
      !>
      !>           As long as the observer and target are separated by less
      !>           than 50 astronomical units, the error in the light time
      !>           returned using the one-iteration light time corrections is
      !>           less than 1 millisecond.
      !>
      !>           The magnitude of the corresponding position error, given
      !>           the above assumptions, may be as large as (V/C)**2 * the
      !>           distance between the observer and the uncorrected target
      !>           position: 300 km or equivalently 6 km/AU.
      !>
      !>        In practice, the difference between positions obtained using
      !>        one-iteration and converged light time is usually much smaller
      !>        than the value computed above and can be insignificant. For
      !>        example, for the spacecraft Mars Reconnaissance Orbiter and
      !>        Mars Express, the position error for the one-iteration light
      !>        time correction, applied to the spacecraft-to-Mars center
      !>        vector, is at the 1 cm level.
      !>
      !>        Comparison of results obtained using the one-iteration and
      !>        converged light time solutions is recommended when adequacy of
      !>        the one-iteration solution is in doubt.
      !>
      !>        Converged corrections
      !>        ---------------------
      !>
      !>        When the requested aberration correction is 'CN', 'CN+S',
      !>        'XCN', or 'XCN+S', as many iterations as are required for
      !>        convergence are performed in the computation of LT. Usually
      !>        the solution is found after three iterations. The relative
      !>        error present in this case is at most
      !>
      !>            (V/C)**4
      !>           ----------
      !>            1 - (V/C)
      !>
      !>        which is well approximated by (V/C)**4.
      !>
      !>           The precision of this computation (ignoring round-off
      !>           error) is better than 4e-11 seconds for any pair of objects
      !>           less than 50 AU apart, and having speed relative to the
      !>           solar system barycenter less than 60 km/s.
      !>
      !>           The magnitude of the corresponding position error, given
      !>           the above assumptions, may be as large as (V/C)**4 * the
      !>           distance between the observer and the uncorrected target
      !>           position: 1.2 cm at 50 AU or equivalently 0.24 mm/AU.
      !>
      !>        However, to very accurately model the light time between
      !>        target and observer one must take into account effects due to
      !>        general relativity. These may be as high as a few hundredths
      !>        of a millisecond for some objects.
      !>
      !>     Relativistic Corrections
      !>     =========================
      !>
      !>     This routine does not attempt to perform either general or
      !>     special relativistic corrections in computing the various
      !>     aberration corrections. For many applications relativistic
      !>     corrections are not worth the expense of added computation
      !>     cycles. If however, your application requires these additional
      !>     corrections we suggest you consult the astronomical almanac (page
      !>     B36) for a discussion of how to carry out these corrections.
      !>
      !>## Examples
      !>
      !>     1)  Load a planetary ephemeris SPK, then look up a series of
      !>         geometric positions of the moon relative to the earth,
      !>         referenced to the J2000 frame.
      !>
      !>               IMPLICIT NONE
      !>         C
      !>         C     Local constants
      !>         C
      !>               CHARACTER*(*)         FRAME
      !>               PARAMETER           ( FRAME  = 'J2000' )
      !>
      !>               CHARACTER*(*)         ABCORR
      !>               PARAMETER           ( ABCORR = 'NONE' )
      !>
      !>         C
      !>         C     The name of the SPK file shown here is fictitious;
      !>         C     you must supply the name of an SPK file available
      !>         C     on your own computer system.
      !>         C
      !>               CHARACTER*(*)         SPK
      !>               PARAMETER           ( SPK    = 'planet.bsp' )
      !>
      !>         C
      !>         C     ET0 represents the date 2000 Jan 1 12:00:00 TDB.
      !>         C
      !>               DOUBLE PRECISION      ET0
      !>               PARAMETER           ( ET0    = 0.0D0 )
      !>
      !>         C
      !>         C     Use a time step of 1 hour; look up 100 positions.
      !>         C
      !>               DOUBLE PRECISION      STEP
      !>               PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>               INTEGER               MAXITR
      !>               PARAMETER           ( MAXITR = 100 )
      !>
      !>         C
      !>         C     The NAIF IDs of the earth and moon are 399 and 301
      !>         C     respectively.
      !>         C
      !>               INTEGER               OBSRVR
      !>               PARAMETER           ( OBSRVR = 399 )
      !>
      !>               INTEGER               TARGET
      !>               PARAMETER           ( TARGET = 301 )
      !>
      !>         C
      !>         C     Local variables
      !>         C
      !>               DOUBLE PRECISION      ET
      !>               DOUBLE PRECISION      LT
      !>               DOUBLE PRECISION      POS ( 3 )
      !>
      !>               INTEGER               I
      !>
      !>         C
      !>         C     Load the SPK file.
      !>         C
      !>               CALL FURNSH ( SPK )
      !>
      !>         C
      !>         C     Step through a series of epochs, looking up a
      !>         C     position vector at each one.
      !>         C
      !>               DO I = 1, MAXITR
      !>
      !>                  ET = ET0 + (I-1)*STEP
      !>
      !>                  CALL SPKEZP ( TARGET, ET, FRAME, ABCORR, OBSRVR,
      !>              .                 POS,    LT                        )
      !>
      !>                  WRITE (*,*) 'ET = ', ET
      !>                  WRITE (*,*) 'J2000 x-position (km):   ', POS(1)
      !>                  WRITE (*,*) 'J2000 y-position (km):   ', POS(2)
      !>                  WRITE (*,*) 'J2000 z-position (km):   ', POS(3)
      !>                  WRITE (*,*) ' '
      !>
      !>               END DO
      !>
      !>               END
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     C.H. Acton         (JPL)
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 3.2.1, 13-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 3.2.0, 03-JUL-2014 (NJB) (BVS)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>        Bug fix: added a check and an exception for the FOUND flag
      !>        returned by FRINFO.
      !>
      !>        Updated to save the input frame name and POOL state counter
      !>        and to do frame name-ID conversion only if the counter has
      !>        changed.
      !>
      !>-    SPICELIB Version 3.1.1, 04-APR-2008 (NJB)
      !>
      !>        Corrected minor error in description of XLT+S aberration
      !>        correction.
      !>
      !>-    SPICELIB Version 3.1.0, 06-JAN-2005 (NJB)
      !>
      !>        Tests of routine FAILED() were added.
      !>
      !>-    SPICELIB Version 3.0.3, 12-DEC-2004 (NJB)
      !>
      !>        Minor header error was corrected.
      !>
      !>-    SPICELIB Version 3.0.2, 20-OCT-2003 (EDW)
      !>
      !>        Added mention that LT returns in seconds.
      !>
      !>-    SPICELIB Version 3.0.1, 29-JUL-2003 (NJB) (CHA)
      !>
      !>        Various minor header changes were made to improve clarity.
      !>
      !>-    SPICELIB Version 3.0.0, 31-DEC-2001 (NJB)
      !>
      !>        Updated to handle aberration corrections for transmission
      !>        of radiation. Formerly, only the reception case was
      !>        supported. The header was revised and expanded to explain
      !>        the functionality of this routine in more detail.
      !>
      !>-    SPICELIB Version 1.0.0, 03-MAR-1999 (WLT)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 3.1.0, 06-JAN-2005 (NJB)
      !>
      !>        Tests of routine FAILED() were added. The new checks
      !>        are intended to prevent arithmetic operations from
      !>        being performed with uninitialized or invalid data.
      !>
      !>-    SPICELIB Version 3.0.0, 31-DEC-2001 (NJB)
      !>
      !>        Updated to handle aberration corrections for transmission
      !>        of radiation. Formerly, only the reception case was
      !>        supported.
      recursive module subroutine spkezp ( ctx, targ, et, ref, abcorr, obs, ptarg, lt )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: mxv
      use pepper_strings, only: eqchr, eqstr, ltrim
      use pepper_inc_frmtyp, frmtyp_all => all  ! PEPPER: ALL (unused) would hide the intrinsic
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body NAIF ID code.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Reference frame of output position vector.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      integer(ip), intent(in) :: obs  !! Observing body NAIF ID code.
      real(wp), intent(out) :: ptarg    ( 3 )  !! Position of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
!
!     Local variables
!
      real(wp) :: temp     ( 3    )
      real(wp) :: xform    ( 3, 3 )
      logical :: found
      real(wp) :: sobs     ( 6    )
      integer(ip) :: typeid
      real(wp) :: ltcent
      integer(ip) :: center
      integer(ip) :: reqfrm
      integer(ip) :: type
      integer(ip) :: i
      real(wp) :: postn    ( 3    )
      logical :: xmit
      if ( .not. allocated ( ctx%spkezp_state ) ) allocate ( ctx%spkezp_state )
      associate ( fj2000 => ctx%spkezp_state%fj2000, &
                  first => ctx%spkezp_state%first, &
                  svctr1 => ctx%spkezp_state%svctr1, &
                  svref => ctx%spkezp_state%svref, &
                  svreqf => ctx%spkezp_state%svreqf )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Get the frame id for J2000 on the first call to this routine.
!
      if ( first ) then

         call namfrm( ctx, 'J2000', fj2000 )

!
!        Initialize counter.
!
         call zzctruin( ctx, svctr1 )

         first = .false.

      end if

!
!     Decide whether the aberration correction is for received or
!     transmitted radiation.
!
      i    = ltrim(abcorr)
      xmit = eqchr ( abcorr(i:i),  'X' )

!
!     If we only want geometric positions, then compute just that.
!
!     Otherwise, compute the state of the observer relative to
!     the SSB.  Then feed that position into SPKAPO to compute the
!     apparent position of the target body relative to the observer
!     with the requested aberration corrections.
!
      if ( eqstr( abcorr, 'NONE' ) ) then

         call spkgps ( ctx, targ, et, ref, obs, ptarg, lt )

      else
!
!        Get the auxiliary information about the requested output
!        frame.
!
         call zznamfrm ( ctx, svctr1, svref, svreqf, ref, reqfrm )

         if ( reqfrm == 0 ) then
            call ctx%setmsg ( 'The requested output frame ''#'' is ' &
            //            'not recognized by the reference frame ' &
            //            'subsystem. Please check that the ' &
            //            'appropriate kernels have been loaded ' &
            //            'and that you have correctly entered ' &
            //            'the name of the output frame. ' )
            call ctx%errch  ( '#', ref )
            call ctx%sigerr ( 'SPICE(UNKNOWNFRAME)'  )
            return

         end if

         call frinfo ( ctx, reqfrm, center, type, typeid, found )

         if ( ctx%failed() ) return

         if ( .not. found ) then

            call ctx%setmsg ( 'The requested output frame ''#'' is ' &
            //            'not recognized by the reference frame ' &
            //            'subsystem. Please check that the ' &
            //            'appropriate kernels have been loaded ' &
            //            'and that you have correctly entered ' &
            //            'the name of the output frame. ' )
            call ctx%errch  ( '#',  ref )
            call ctx%sigerr ( 'SPICE(UNKNOWNFRAME2)' )

            return

         end if

!
!        If we are dealing with an inertial frame, we can simply
!        call SPKSSB, SPKAPO and return.
!
         if ( type == inertl ) then

            call spkssb ( ctx, obs,  et, ref, sobs )
            call spkapo ( ctx, targ, et, ref, sobs, abcorr, ptarg, lt )
            return

         end if

!
!        Still here?
!
!        We are dealing with a non-inertial frame.  But we need to
!        do light time and stellar aberration in an inertial frame.
!        Get the "apparent" position of TARG in the intermediary
!        inertial reference frame J2000.
!
!        We also need the light time to the center of the frame.
!
         call spkssb ( ctx, obs,  et, 'J2000', sobs )
         call spkapo ( ctx, targ, et, 'J2000', sobs, abcorr, postn, lt )

         if ( ctx%failed() ) return

         if ( center == obs ) then
            ltcent = 0.0_wp
         else if ( center == targ ) then
            ltcent = lt
         else
            call spkapo ( ctx, center, et, 'J2000', sobs, abcorr, temp, &
                          ltcent )
         end if

!
!        If something went wrong (like we couldn't get the position of
!        the center relative to the observer) now it is time to quit.
!
         if ( ctx%failed() ) return

!
!        If the aberration corrections are for transmission, negate
!        the light time, since we wish to compute the orientation
!        of the non-inertial frame at an epoch later than ET by
!        the one-way light time.
!
         if ( xmit ) then
            ltcent = -ltcent
         end if

!
!        Get the rotation from J2000 to the requested frame
!        and convert the position.
!
         call refchg ( ctx, fj2000, reqfrm, et-ltcent, xform )

         if ( ctx%failed() ) return

         call mxv    ( xform,  postn,             ptarg )

      end if

      return
      end associate
      end subroutine spkezp

      !> Extract a subset of the data in a type 14 SPK segment into a new
      !> type 14 segment.
      !>
      !>## Detailed Input
      !>
      !>     SRCHAN   is the handle of the SPK file containing the source
      !>              segment.
      !>
      !>     SRCDSC   is the SPK descriptor for the source segment.
      !>
      !>     DSTHAN   is the handle of the SPK file containing the new segment.
      !>
      !>     DSTDSC   is the SPK descriptor for the destination segment. It
      !>              contains the desired start and stop times for the
      !>              requested subset.
      !>
      !>     DSTSID   is the segment identifier for the destination segment.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the length of the SPK record that is to be moved is larger
      !>         than MAXREC, the error SPICE(SPKRECTOOLARGE) is signaled.
      !>
      !>## Files
      !>
      !>     See arguments SRCHAN, DSTHAN.
      !>
      !>## Particulars
      !>
      !>     This subroutine copies a subset of the data form one SPK segment
      !>     to another.
      !>
      !>     The exact structure of a segment of SPK type 14 is detailed in
      !>     the SPK Required Reading. Please see this document for details.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     1)  We assume that the source descriptor actually describes a
      !>         segment in the source SPK file containing the time coverage
      !>         that is desired for the subsetting operation.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-JUN-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 08-MAR-1995 (KRG)
      module subroutine spks14 ( ctx, srchan, srcdsc, dsthan, dstdsc, dstsid )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: srchan  !! Handle of the SPK file with the source segment.
      real(wp), intent(in) :: srcdsc(*)  !! Descriptor for the source segment.
      integer(ip), intent(in) :: dsthan  !! Handle of the SPK file for the destination segment.
      real(wp), intent(in) :: dstdsc(*)  !! Descriptor for the destination segment.
      character(*), intent(in) :: dstsid  !! Segment identifier for the new segment.
      real(wp) :: myref_1(1)  !! one-element copy of myref (array argument)
      integer(ip) :: dummy_1(1)  !! one-element copy of dummy (array argument)

!     This is the maximum size type 14 record that we can move. This
!     allows a 20th degree Chebyshev Polynomial, which should be more
!     than sufficient. This should be the same as the value in SPKPV.
!
      integer(ip), parameter :: maxrec = 128
!
!     Reference frame name size. See CHGIRF.
!
      integer(ip), parameter :: frmsiz = 16

      character(frmsiz) :: myfram

      real(wp) :: begtim
      real(wp) :: dtemp  ( nd     )
      real(wp) :: endtim
      real(wp) :: myref
      real(wp) :: record ( maxrec )

      integer(ip) :: begidx
      integer(ip) :: body
      integer(ip) :: center
      integer(ip) :: chbdeg
      integer(ip) :: dummy
      integer(ip) :: endidx
      integer(ip) :: i
      integer(ip) :: iframe
      integer(ip) :: itemp  ( ni )
      integer(ip) :: recsiz

      logical :: found

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return
!
!     First, unpack the destination segment descriptor and set some
!     local variables.
!
      call dafus( ctx, dstdsc, nd, ni, dtemp, itemp )

      begtim = dtemp(1)
      endtim = dtemp(2)
      body   = itemp(1)
      center = itemp(2)
      iframe = itemp(3)

      call irfnam ( ctx, iframe, myfram )
!
!     If we can't find the code, it can't be an SPK file.
!
      if ( ctx%failed() ) return
!
!     Get the constants for this segment. There is only one.
!
      call sgfcon ( ctx, srchan, srcdsc, 1, 1, dtemp )

      if ( ctx%failed() ) return
!
!     The first element of DTEMP now contains the number of coefficients
!     used for the Chebyshev polynomials. We need the degree of the
!     polynomial which is one less than the number of coefficients.
!
      chbdeg = int ( dtemp(1) ) - 1
!
!     Compute the size of the SPK record and signal an error if there is
!     not enough room in the variable RECORD to hold it.
!
      recsiz = (chbdeg + 1) * nstate + 2

      if ( recsiz > maxrec ) then
         call ctx%setmsg ( 'Storage for # double precision numbers' &
         //            ' is needed for an SPK data record and' &
         //            ' only # locations were available. Update' &
         //            ' the parameter MAXREC in the subroutine' &
         //            ' SPKS14 and notify the NAIF group of this' &
         //            ' problem.'                                )
         call ctx%errint ( '#', recsiz                                )
         call ctx%errint ( '#', maxrec                                )
         call ctx%sigerr ( 'SPICE(SPKRECTOOLARGE)'                    )
         return
      end if

!
!     Get the beginning and ending indices for the packets we need for
!     the destination segment.
!
      call sgfrvi ( ctx, srchan, srcdsc, begtim, myref, begidx, found )
      call sgfrvi ( ctx, srchan, srcdsc, endtim, myref, endidx, found )
!
!     Begin the destination segment.
!
      call spk14b ( ctx, dsthan, dstsid, body, center, myfram, &
                            begtim, endtim, chbdeg        )

      if ( ctx%failed() ) return
!
!     Now we get the data one record at a time from the source segment
!     and write it out to the destination segment.
!
      do i = begidx, endidx

         call sgfpkt ( ctx, srchan, srcdsc, i, i, record, dummy_1 )
         dummy = dummy_1(1)
         call sgfref ( ctx, srchan, srcdsc, i, i, myref_1 )
         myref = myref_1(1)
         call spk14a ( ctx, dsthan, 1, record, [ myref ] )

         if ( ctx%failed() ) return

      end do
!
!     Now all we need to do is end the segment.
!
      call spk14e ( ctx, dsthan )

      return

      end subroutine spks14

      !> Return the state (position and velocity) of a target body
      !> relative to an observer, optionally corrected for light time,
      !> expressed relative to an inertial reference frame. An input
      !> subroutine provides the state of the target relative to its
      !> center of motion.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     TRGSUB      is the name of an external subroutine that returns
      !>                 the geometric state of the target body relative to a
      !>                 center of motion, expressed in the inertial reference
      !>                 frame REF, at the epoch ET.
      !>
      !>                 The calling sequence of TRGSUB is
      !>
      !>                    SUBROUTINE TRGSUB ( ET, REF, TRGCTR, STATE )
      !>
      !>                    DOUBLE PRECISION      ET
      !>                    CHARACTER*(*)         REF
      !>                    INTEGER               TRGCTR
      !>                    DOUBLE PRECISION      STATE ( 6 )
      !>
      !>                    The inputs of TRGSUB are ET and REF; the outputs
      !>                    are TRGCTR and STATE. STATE is the geometric state
      !>                    of the target relative to the returned center of
      !>                    motion at ET, expressed in the frame REF.
      !>
      !>                 The target and observer define a state vector whose
      !>                 position component points from the observer to the
      !>                 target.
      !>
      !>     ET          is the ephemeris time, expressed as seconds past
      !>                 J2000 TDB, at which the state of the target body
      !>                 relative to the observer is to be computed. ET
      !>                 refers to time at the observer's location.
      !>
      !>     REF         is the inertial reference frame with respect to which
      !>                 the input state STOBS and the output state STARG are
      !>                 expressed. REF must be recognized by the SPICE
      !>                 Toolkit. The acceptable frames are listed in the
      !>                 Frames Required Reading, as well as in the SPICELIB
      !>                 routine CHGIRF.
      !>
      !>                 Case and blanks are not significant in the string
      !>                 REF.
      !>
      !>     ABCORR      indicates the aberration corrections to be applied to
      !>                 the state of the target body to account for one-way
      !>                 light time. See the discussion in the Particulars
      !>                 section for recommendations on how to choose
      !>                 aberration corrections.
      !>
      !>                 If ABCORR includes the stellar aberration correction
      !>                 symbol '+S', this flag is simply ignored. Aside from
      !>                 the possible presence of this symbol, ABCORR may be
      !>                 any of the following:
      !>
      !>                    'NONE'     Apply no correction. Return the
      !>                               geometric state of the target body
      !>                               relative to the observer.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "reception" case in which photons depart from the
      !>                 target's location at the light-time corrected epoch
      !>                 ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                    'LT'       Correct for one-way light time (also
      !>                               called "planetary aberration") using a
      !>                               Newtonian formulation. This correction
      !>                               yields the state of the target at the
      !>                               moment it emitted photons arriving at
      !>                               the observer at ET.
      !>
      !>                               The light time correction involves
      !>                               iterative solution of the light time
      !>                               equation. (See the Particulars section
      !>                               of SPKEZR for details.) The solution
      !>                               invoked by the 'LT' option uses one
      !>                               iteration.
      !>
      !>                    'CN'       Converged Newtonian light time
      !>                               correction. In solving the light time
      !>                               equation, the 'CN' correction iterates
      !>                               until the solution converges (three
      !>                               iterations on all supported platforms).
      !>                               Whether the 'CN+S' solution is
      !>                               substantially more accurate than the
      !>                               'LT' solution depends on the geometry
      !>                               of the participating objects and on the
      !>                               accuracy of the input data. In all
      !>                               cases this routine will execute more
      !>                               slowly when a converged solution is
      !>                               computed. See the Particulars section of
      !>                               SPKEZR for a discussion of precision of
      !>                               light time corrections.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "transmission" case in which photons *depart* from
      !>                 the observer's location at ET and arrive at the
      !>                 target's location at the light-time corrected epoch
      !>                 ET+LT:
      !>
      !>                    'XLT'      "Transmission" case:  correct for
      !>                               one-way light time using a Newtonian
      !>                               formulation. This correction yields the
      !>                               state of the target at the moment it
      !>                               receives photons emitted from the
      !>                               observer's location at ET.
      !>
      !>                    'XCN'      "Transmission" case:  converged
      !>                               Newtonian light time correction.
      !>
      !>                 Neither special nor general relativistic effects are
      !>                 accounted for in the aberration corrections applied
      !>                 by this routine.
      !>
      !>                 Case and blanks are not significant in the string
      !>                 ABCORR.
      !>
      !>     STOBS       is the geometric (uncorrected) state of the observer
      !>                 relative to the solar system barycenter at epoch ET.
      !>                 STOBS is a 6-vector: the first three components of
      !>                 STOBS represent a Cartesian position vector; the last
      !>                 three components represent the corresponding velocity
      !>                 vector. STOBS is expressed relative to the inertial
      !>                 reference frame designated by REF.
      !>
      !>                 Units are always km and km/sec.
      !>
      !>## Detailed Output
      !>
      !>     STARG       is a Cartesian state vector representing the position
      !>                 and velocity of the target body relative to the
      !>                 specified observer. STARG is corrected for the
      !>                 specified aberration, and is expressed with respect
      !>                 to the specified inertial reference frame.  The first
      !>                 three components of STARG represent the x-, y- and
      !>                 z-components of the target's position; last three
      !>                 components form the corresponding velocity vector.
      !>
      !>                 The position component of STARG points from the
      !>                 observer's location at ET to the aberration-corrected
      !>                 location of the target. Note that the sense of the
      !>                 position vector is independent of the direction of
      !>                 radiation travel implied by the aberration
      !>                 correction.
      !>
      !>                 Units are always km and km/sec.
      !>
      !>     LT          is the one-way light time between the observer and
      !>                 target in seconds.  If the target state is corrected
      !>                 for light time, then LT is the one-way light time
      !>                 between the observer and the light time-corrected
      !>                 target location.
      !>
      !>     DLT         is the derivative with respect to barycentric
      !>                 dynamical time of the one way light time between
      !>                 target and observer:
      !>
      !>                    DLT = d(LT)/d(ET)
      !>
      !>                 DLT can also be described as the rate of change of
      !>                 one way light time. DLT is unitless, since LT and
      !>                 ET both have units of TDB seconds.
      !>
      !>                 If the observer and target are at the same position,
      !>                 then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) For the convenience of the caller, the input aberration
      !>        correction flag can call for stellar aberration correction via
      !>        inclusion of the '+S' suffix. This portion of the aberration
      !>        correction flag is ignored if present.
      !>
      !>     2) If ABCORR calls for stellar aberration but not light
      !>        time corrections, the error SPICE(NOTSUPPORTED) is
      !>        signaled.
      !>
      !>     3) If ABCORR calls for relativistic light time corrections, the
      !>        error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     4) If the value of ABCORR is not recognized, the error
      !>        is diagnosed by a routine in the call tree of this
      !>        routine.
      !>
      !>     5) If the reference frame requested is not a recognized
      !>        inertial reference frame, the error SPICE(UNKNOWNFRAME)
      !>        is signaled.
      !>
      !>     6) If the state of the target relative to the solar system
      !>        barycenter cannot be computed, the error will be diagnosed
      !>        by routines in the call tree of this routine.
      !>
      !>     7) If the observer and target are at the same position,
      !>        then DLT is set to zero. This situation could arise,
      !>        for example, when the observer is Mars and the target
      !>        is the Mars barycenter.
      !>
      !>     8) If a division by zero error would occur in the computation
      !>        of DLT, the error SPICE(DIVIDEBYZERO) is signaled.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH.  Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level routines that can
      !>     perform both light time and stellar aberration corrections
      !>     and that use target states provided by subroutines rather
      !>     than by the conventional, public SPK APIs. For example, this
      !>     routine can be used for objects having fixed positions
      !>     on the surfaces of planets.
      !>
      !>## Examples
      !>
      !>     See usage in ZZSPKFAP.
      !>
      !>## Restrictions
      !>
      !>     1) This routine must not be called by routines of the SPICE
      !>        frame subsystem. It must not be called by any portion of
      !>        the SPK subsystem other than the private SPK function-based
      !>        component.
      !>
      !>     2) The input subroutine TRGSUB must not call this routine.
      !>        or any of the supporting, private SPK routines
      !>
      !>     3)  When possible, the routine SPKGEO should be used instead of
      !>         this routine to compute geometric states. SPKGEO introduces
      !>         less round-off error when the observer and target have common
      !>         center that is closer to both objects than is the solar
      !>         system barycenter.
      !>
      !>     4)  Unlike most other SPK state computation routines, this
      !>         routine requires that the output state be relative to an
      !>         inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>     Last update was 22-FEB-2012 (NJB)
      !>
      !>## Revisions
      !>
      !>     None.
      module subroutine zzspkflt (  ctx, trgsub, et, ref, abcorr, stobs, starg, lt, dlt  )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: vdot, vnorm
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      procedure(zzspk_state) :: trgsub  !! routine returning the target's state (relative to the SSB)
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(in) :: stobs  ( 6 )  !! State of the observer relative to the SSB.
      real(wp), intent(out) :: starg  ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
!
!     Local variables
!
      real(wp) :: a
      real(wp) :: b
      real(wp) :: c
      real(wp) :: ctrssb ( 6 )
      real(wp) :: dist
      real(wp) :: epoch
      real(wp) :: prvlt
      real(wp) :: lterr
      real(wp) :: ssbtrg ( 6 )
      real(wp) :: sttctr ( 6 )
      integer(ip) :: i
      integer(ip) :: ltsign
      integer(ip) :: numitr
      integer(ip) :: refid
      integer(ip) :: trgctr
      logical :: attblk ( nabcor )
      logical :: usestl
      if ( .not. allocated ( ctx%zzspkflt_state ) ) allocate ( ctx%zzspkflt_state )
      associate ( pass1 => ctx%zzspkflt_state%pass1, &
                  prvcor => ctx%zzspkflt_state%prvcor, &
                  usecn => ctx%zzspkflt_state%usecn, &
                  uselt => ctx%zzspkflt_state%uselt, &
                  xmit => ctx%zzspkflt_state%xmit )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      if (  pass1  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USECN indicates converged Newtonian light time correction.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         xmit    =  attblk ( xmtidx )
         uselt   =  attblk ( ltidx )
         usecn   =  attblk ( cnvidx )
         usestl  =  attblk ( stlidx )

         pass1   = .false.

      end if

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(UNKNOWNFRAME)'                )
         return

      end if

!
!     Find the geometric state of the target body with respect to
!     the solar system barycenter. Subtract the state of the
!     observer to get the relative state. Use this to compute the
!     one-way light time.
!
      call trgsub ( ctx, et,     ref,    trgctr, sttctr )
      call spkssb ( ctx, trgctr, et,     ref,    ctrssb )

      if ( ctx%failed() ) return

      ssbtrg = ctrssb + sttctr
      starg = ssbtrg - stobs

      dist = vnorm(starg)
      lt   = dist / clight

      if ( lt == 0.0_wp ) then
!
!        This can happen only if the observer and target are at the
!        same position. We don't consider this an error, but we're not
!        going to compute the light time derivative.
!
         dlt = 0

         return

      end if

      if ( .not. uselt ) then
!
!        This is a special case: we're not using light time
!        corrections, so the derivative
!        of light time is just
!
!           (1/c) * d(VNORM(STARG))/dt
!
         dlt = vdot( starg, starg(4) ) / ( dist * clight )

!
!        LT and DLT are both set, so we can return.
!
         return

      end if

!
!     To correct for light time, find the state of the target body
!     at the current epoch minus the one-way light time. Note that
!     the observer remains where it is.
!
!     Determine the sign of the light time offset.
!
      if ( xmit ) then
         ltsign =  1
      else
         ltsign = -1
      end if

!
!     Let NUMITR be the number of iterations we'll perform to
!     compute the light time.
!
      if ( usecn ) then
         numitr = maxitr
      else
         numitr = 1
      end if

      i      = 0
      lterr  = 1.0_wp

      do while (        ( i     < numitr ) &
                  .and. ( lterr > cnvlim )  )
!
!        LT was set either prior to this loop or
!        during the previous loop iteration.
!
         epoch = (et  +  ( ltsign * lt ))

         call trgsub (         ctx, epoch,  ref, trgctr, sttctr )
         call spkssb ( ctx, trgctr, epoch,  ref,         ctrssb )

         if ( ctx%failed() ) return

         ssbtrg = ctrssb + sttctr
         starg = ssbtrg - stobs

         prvlt = lt
         lt    = (vnorm ( starg ) / clight)

!
!        LTERR is the magnitude of the change between the current
!        estimate of light time and the previous estimate, relative to
!        the previous light time corrected epoch.
!
         lterr = (abs ( lt  - prvlt      )  / max ( 1.0_wp, abs(epoch) ))
         i     = i + 1

      end do

!
!     At this point, STARG contains the light time corrected
!     state of the target relative to the observer.
!
!     Compute the derivative of light time with respect
!     to time: dLT/dt.  Below we derive the formula for
!     this quantity for the reception case. Let
!
!        POBS be the position of the observer relative to the
!        solar system barycenter.
!
!        VOBS be the velocity of the observer relative to the
!        solar system barycenter.
!
!        PTARG be the position of the target relative to the
!        solar system barycenter.
!
!        VTARG be the velocity of the target relative to the
!        solar system barycenter.
!
!        S be the sign of the light time correction. S is
!        negative for the reception case.
!
!     The light-time corrected position of the target relative to
!     the observer at observation time ET, given the one-way
!     light time LT is:
!
!         PTARG(ET+S*LT) - POBS(ET)
!
!     The light-time corrected velocity of the target relative to
!     the observer at observation time ET is
!
!         VTARG(ET+S*LT)*( 1 + S*d(LT)/d(ET) ) - VOBS(ET)
!
!     We need to compute dLT/dt. Below, we use the facts that,
!     for a time-dependent vector X(t),
!
!          ||X||     = <X,X> ** (1/2)
!
!        d(||X||)/dt = (1/2)<X,X>**(-1/2) * 2 * <X,dX/dt>
!
!                    = <X,X>**(-1/2) *  <X,dX/dt>
!
!                    = <X,dX/dt> / ||X||
!
!     Newtonian light time equation:
!
!        LT     =   (1/c) * || PTARG(ET+S*LT) - POBS(ET)||
!
!     Differentiate both sides:
!
!        dLT/dt =   (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!                  * < PTARG(ET+S*LT) - POBS(ET),
!                      VTARG(ET+S*LT)*(1+S*d(LT)/d(ET)) - VOBS(ET) >
!
!               = (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!                 * (  < PTARG(ET+S*LT) - POBS(ET),
!                        VTARG(ET+S*LT) - VOBS(ET) >
!
!                   +  < PTARG(ET+S*LT) - POBS(ET),
!                        VTARG(ET+S*LT)           > * (S*d(LT)/d(ET))  )
!
!     Let
!
!        A =   (1/c) * ( 1 / || PTARG(ET+S*LT) - POBS(ET) || )
!
!        B =   < PTARG(ET+S*LT) - POBS(ET), VTARG(ET+S*LT) - VOBS(ET) >
!
!        C =   < PTARG(ET+S*LT) - POBS(ET), VTARG(ET+S*LT) >
!
!     Then
!
!        d(LT)/d(ET) =  A * ( B  +  C * S*d(LT)/d(ET) )
!
!     which implies
!
!        d(LT)/d(ET) =  A*B / ( 1 - S*C*A )
!
      a   =  1.0_wp / ( clight*vnorm(starg) )

      b   =  vdot ( starg, starg(4)  )

      c   =  vdot ( starg, ssbtrg(4) )

!
!     For physically realistic target velocities, S*C*A cannot equal 1.
!     We'll check for this case anyway.
!
      if (  ltsign*c*a  >  1.0_wp-tol ) then

         call ctx%setmsg ( 'Target range rate magnitude is ' &
      //               'approximately the speed of light. The ' &
      //               'light time derivative cannot be ' &
      //               'computed.'                            )
         call ctx%sigerr ( 'SPICE(DIVIDEBYZERO)'                  )
         return

      end if

!
!     Compute DLT: the rate of change of light time.
!
      dlt = (a*b)/( 1.0_wp - ltsign*c*a )

!
!     Overwrite the velocity portion of the output state
!     with the light-time corrected velocity.
!
      starg(4:6) = (1.0_wp + ltsign*dlt)*ssbtrg(4:6) + (-1.0_wp)*stobs(4:6)

      return
      end associate
      end subroutine zzspkflt

      !> Return the state (position and velocity) of a target body
      !> relative to an observer, optionally corrected for light time
      !> and stellar aberration, expressed relative to an inertial
      !> reference frame.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a state vector whose position
      !>              component points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past
      !>              J2000 TDB, at which the state of the target body
      !>              relative to the observer is to be computed.  ET
      !>              refers to time at the observer's location.
      !>
      !>     REF      is the inertial reference frame with respect to which
      !>              the output state STARG is expressed. REF must be
      !>              recognized by the SPICE Toolkit. The acceptable
      !>              frames are listed in the Frames Required Reading, as
      !>              well as in the SPICELIB routine CHGIRF.
      !>
      !>              Case and blanks are not significant in the string
      !>              REF.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              to the state of the target body to account for one-way
      !>              light time and stellar aberration. See the discussion
      !>              in the $Particulars section for recommendations on
      !>              how to choose aberration corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric state of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the state of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            state obtained with the 'LT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            state of the target---the position and
      !>                            velocity of the target as seen by the
      !>                            observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section of
      !>                            SPKEZR for a discussion of precision of
      !>                            light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            state of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            state obtained with the 'XLT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The position component of
      !>                            the computed target state indicates the
      !>                            direction that photons emitted from the
      !>                            observer's location must be "aimed" to
      !>                            hit the target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>     OBS      is the NAIF ID code for the observer body. The
      !>              target and observer define a state vector whose
      !>              position component points from the observer to the
      !>              target.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position
      !>              and velocity of the target body relative to the
      !>              specified observer. STARG is corrected for the
      !>              specified aberrations, and is expressed with respect
      !>              to the specified inertial reference frame. The first
      !>              three components of STARG represent the x-, y- and
      !>              z-components of the target's position; last three
      !>              components form the corresponding velocity vector.
      !>
      !>              The position component of STARG points from the
      !>              observer's location at ET to the aberration-corrected
      !>              location of the target. Note that the sense of the
      !>              position vector is independent of the direction of
      !>              radiation travel implied by the aberration
      !>              correction.
      !>
      !>              Units are always km and km/sec.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target state is corrected
      !>              for aberrations, then LT is the one-way light time
      !>              between the observer and the light time corrected
      !>              target location.
      !>
      !>     DLT      is the derivative with respect to barycentric
      !>              dynamical time of the one way light time between
      !>              target and observer:
      !>
      !>                 DLT = d(LT)/d(ET)
      !>
      !>              DLT can also be described as the rate of change of
      !>              one way light time. DLT is unitless, since LT and
      !>              ET both have units of TDB seconds.
      !>
      !>              If the observer and target are at the same position,
      !>              then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the value of ABCORR is not recognized, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     2)  If the reference frame requested is not a recognized
      !>         inertial reference frame, the error SPICE(BADFRAME)
      !>         is signaled.
      !>
      !>     3)  If the state of the target relative to the solar system
      !>         barycenter cannot be computed, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     4)  If the observer and target are at the same position,
      !>         then DLT is set to zero. This situation could arise,
      !>         for example, when the observer is Mars and the target
      !>         is the Mars barycenter.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level SPK API routines that can
      !>     perform both light time and stellar aberration corrections.
      !>     User applications normally will not need to call this routine
      !>     directly.
      !>
      !>     See the header of the routine SPKEZR for a detailed discussion
      !>     of aberration corrections.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Look up a sequence of states of the Moon as seen from the
      !>        Earth. Use light time and stellar aberration corrections.
      !>        Compute the first state for the epoch 2000 JAN 1 12:00:00 TDB;
      !>        compute subsequent states at intervals of 1 hour. For each
      !>        epoch, display the states, the one way light time between
      !>        target and observer, and the rate of change of the one way
      !>        light time.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: spkacs_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de418.bsp                     Planetary ephemeris
      !>              pck00008.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0008.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de418.bsp',
      !>                                  'pck00008.tpc',
      !>                                  'naif0008.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SPKACS_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     Local constants
      !>C
      !>C     The meta-kernel name shown here refers to a file whose
      !>C     contents are those shown above. This file and the
      !>C     kernels it references must exist in your current working
      !>C     directory.
      !>C
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'spkacs_ex1.tm' )
      !>C
      !>C     Use a time step of 1 hour; look up 5 states.
      !>C
      !>      DOUBLE PRECISION      STEP
      !>      PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>      INTEGER               MAXITR
      !>      PARAMETER           ( MAXITR = 5 )
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      DLT
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      STATE ( 6 )
      !>      INTEGER               I
      !>
      !>C
      !>C     Load the SPK and LSK kernels via the meta-kernel.
      !>C
      !>      CALL FURNSH ( META )
      !>C
      !>C     Convert the start time to seconds past J2000 TDB.
      !>C
      !>      CALL STR2ET ( '2000 JAN 1 12:00:00 TDB', ET0 )
      !>C
      !>C     Step through a series of epochs, looking up a
      !>C     state vector at each one.
      !>C
      !>      DO I = 1, MAXITR
      !>
      !>         ET = ET0 + (I-1)*STEP
      !>C
      !>C        Look up a state vector at epoch ET using the
      !>C        following inputs:
      !>C
      !>C           Target:                 Moon (NAIF ID code 301)
      !>C           Reference frame:        J2000
      !>C           Aberration correction:  Light time and stellar
      !>C                                   aberration ('LT+S')
      !>C           Observer:               Earth (NAIF ID code 399)
      !>C
      !>
      !>         CALL SPKACS ( 301, ET,    'J2000', 'LT+S',
      !>     .                 399, STATE, LT,      DLT     )
      !>
      !>         WRITE (*,*) 'ET = ', ET
      !>         WRITE (*,*) 'J2000 x-position (km):   ', STATE(1)
      !>         WRITE (*,*) 'J2000 y-position (km):   ', STATE(2)
      !>         WRITE (*,*) 'J2000 z-position (km):   ', STATE(3)
      !>         WRITE (*,*) 'J2000 x-velocity (km/s): ', STATE(4)
      !>         WRITE (*,*) 'J2000 y-velocity (km/s): ', STATE(5)
      !>         WRITE (*,*) 'J2000 z-velocity (km/s): ', STATE(6)
      !>         WRITE (*,*) 'One-way light time (s):  ', LT
      !>         WRITE (*,*) 'Light time rate:         ', DLT
      !>         WRITE (*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         ET =    0.0000000000000000
      !>         J2000 x-position (km):     -291584.61369497533
      !>         J2000 y-position (km):     -266693.40583162551
      !>         J2000 z-position (km):     -76095.653209237149
      !>         J2000 x-velocity (km/s):   0.64343915743508395
      !>         J2000 y-velocity (km/s):  -0.66606587365741410
      !>         J2000 z-velocity (km/s):  -0.30131006342946742
      !>         One-way light time (s):     1.3423106103251679
      !>         Light time rate:            1.0731690869897750E-007
      !>
      !>         ET =    3600.0000000000000
      !>         J2000 x-position (km):     -289256.45942322229
      !>         J2000 y-position (km):     -269080.60545907740
      !>         J2000 z-position (km):     -77177.352771302132
      !>         J2000 x-velocity (km/s):   0.64997032016926526
      !>         J2000 y-velocity (km/s):  -0.66014825329341664
      !>         J2000 z-velocity (km/s):  -0.29963041790724715
      !>         One-way light time (s):     1.3426939548635302
      !>         Light time rate:            1.0565259895222426E-007
      !>
      !>         ET =    7200.0000000000000
      !>         J2000 x-position (km):     -286904.89654239739
      !>         J2000 y-position (km):     -271446.41676468350
      !>         J2000 z-position (km):     -78252.965533623050
      !>         J2000 x-velocity (km/s):   0.65644388315539315
      !>         J2000 y-velocity (km/s):  -0.65418355204586442
      !>         J2000 z-velocity (km/s):  -0.29792853294482308
      !>         One-way light time (s):     1.3430713117337547
      !>         Light time rate:            1.0399045689875861E-007
      !>
      !>         ET =    10800.000000000000
      !>         J2000 x-position (km):     -284530.13302756584
      !>         J2000 y-position (km):     -273790.67111559171
      !>         J2000 z-position (km):     -79322.411703917489
      !>         J2000 x-velocity (km/s):   0.66285950473048116
      !>         J2000 y-velocity (km/s):  -0.64817224685146524
      !>         J2000 z-velocity (km/s):  -0.29620455846903732
      !>         One-way light time (s):     1.3434426890693671
      !>         Light time rate:            1.0233066524342374E-007
      !>
      !>         ET =    14400.000000000000
      !>         J2000 x-position (km):     -282132.37807791750
      !>         J2000 y-position (km):     -276113.20159697317
      !>         J2000 z-position (km):     -80385.612030562901
      !>         J2000 x-velocity (km/s):   0.66921684649247459
      !>         J2000 y-velocity (km/s):  -0.64211481528028158
      !>         J2000 z-velocity (km/s):  -0.29445864490384888
      !>         One-way light time (s):     1.3438080956559786
      !>         Light time rate:            1.0067340363005083E-007
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by SPKACS must be loaded
      !>         (normally by the SPICELIB kernel loader FURNSH) before
      !>         this routine is called.
      !>
      !>     2)  Unlike most other SPK state computation routines, this
      !>         routine requires that the output state be relative to an
      !>         inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 23-AUG-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard. Updated
      !>        example's meta-kernel.
      !>
      !>        Bug fix: ABCORR now is parsed using ZZVALCOR. This improves
      !>        error checking.
      !>
      !>-    SPICELIB Version 1.0.1, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>-    SPICELIB Version 1.0.0, 11-JAN-2008 (NJB)
      recursive module subroutine spkacs ( ctx, targ, et, ref, abcorr, obs, starg, lt, dlt )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      integer(ip), intent(in) :: obs  !! Observer.
      real(wp), intent(out) :: starg    ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
      logical :: usestl  !! (PEPPER) copy of the saved flag for this call
      real(wp) :: acc    ( 3 )
      real(wp) :: ltssb
      real(wp) :: ssblt
      real(wp) :: ssbobs ( 6 )
      real(wp) :: stobs  ( 6, 2 )
      real(wp) :: t
      integer(ip) :: i
      integer(ip) :: refid
      logical :: attblk ( nabcor )
      if ( .not. allocated ( ctx%spkacs_state ) ) allocate ( ctx%spkacs_state )
      associate ( first => ctx%spkacs_state%first, &
                  prvcor => ctx%spkacs_state%prvcor, &
                  c_usestl => ctx%spkacs_state%usestl )
      if ( ctx%failed() ) return

      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           USESTL is .TRUE. when stellar aberration correction is
!           specified.
!
!        The above definitions are consistent with those used by
!        ZZPRSCOR.
!
         c_usestl  =  attblk ( stlidx )

         first   = .false.

      end if
      !
      !     PEPPER: the routine may be called again, for a dynamic frame,
      !     before it returns (SPICELIB had copies per recursion level); the
      !     saved flags are copied here, and only the copies are used below.
      !
      usestl = c_usestl

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Prepare to look up the apparent state of the target
!     as seen by the observer. We'll need the geometric
!     state of the observer relative to the solar system
!     barycenter. If we're using stellar aberration
!     corrections, we'll need the observer's acceleration
!     as well.
!
!     Get the geometric state of the observer relative to the SSB,
!     which we'll call SSBOBS.
!
      call spkgeo ( ctx, obs, et, ref, ssb, ssbobs, ssblt )

      if ( usestl ) then
!
!        Numerically differentiate the observer velocity relative to
!        the SSB to obtain acceleration. We first evaluate the
!        geometric state of the observer relative to the solar system
!        barycenter at ET +/- DELTA.

         do i = 1, 2

            t = et + (2*i - 3)*delta

            call spkgeo ( ctx, obs, t, ref, ssb, stobs(1,i), ltssb )

         end do

         call qderiv ( ctx, 3, stobs(4,1), stobs(4,2), delta, acc )

      else

         acc = 0.0_wp

      end if

!
!     Look up the apparent state. The light time and light
!     rate are returned as well.
!
      call spkaps ( ctx, targ,   et,  ref,   abcorr, &
                    ssbobs, acc, starg, lt,     dlt )

      return
      end associate
      end subroutine spkacs

      !> Return the position of a target body relative to an observing
      !> body, optionally corrected for light time (planetary aberration)
      !> and stellar aberration.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the name of a target body. Optionally, you may
      !>              supply the integer ID code for the object as an
      !>              integer string. For example both 'MOON' and '301'
      !>              are legitimate strings that indicate the moon is the
      !>              target body.
      !>
      !>              The target and observer define a position vector
      !>              which points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past J2000
      !>              TDB, at which the position of the target body relative to
      !>              the observer is to be computed. ET refers to time at the
      !>              observer's location.
      !>
      !>     REF      is the name of the reference frame relative to which
      !>              the output position vector should be expressed. This
      !>              may be any frame supported by the SPICE system,
      !>              including built-in frames (documented in the Frames
      !>              Required Reading) and frames defined by a loaded
      !>              frame kernel (FK).
      !>
      !>              When REF designates a non-inertial frame, the
      !>              orientation of the frame is evaluated at an epoch
      !>              dependent on the selected aberration correction. See
      !>              the description of the output position vector PTARG
      !>              for details.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to
      !>              the position of the target body to account for
      !>              one-way light time and stellar aberration. See the
      !>              discussion in the $Particulars section for
      !>              recommendations on how to choose aberration
      !>              corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric position of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the position of the target at
      !>                            the moment it emitted photons arriving
      !>                            at the observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            position obtained with the 'LT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            position of the target---the position
      !>                            as seen by the observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section
      !>                            below for a discussion of precision of
      !>                            light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            position of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            position obtained with the 'XLT' option
      !>                            to account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The computed target
      !>                            position indicates the direction that
      !>                            photons emitted from the observer's
      !>                            location must be "aimed" to hit the
      !>                            target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     OBS      is the name of an observing body. Optionally, you
      !>              may supply the ID code of the object as an integer
      !>              string. For example, both 'EARTH' and '399' are
      !>              legitimate strings to supply to indicate the
      !>              observer is Earth.
      !>
      !>## Detailed Output
      !>
      !>     PTARG    is a Cartesian 3-vector representing the position of
      !>              the target body relative to the specified observer.
      !>              PTARG is corrected for the specified aberrations, and
      !>              is expressed with respect to the reference frame
      !>              specified by REF. The three components of PTARG
      !>              represent the x-, y- and z-components of the target's
      !>              position.
      !>
      !>              PTARG points from the observer's location at ET to
      !>              the aberration-corrected location of the target.
      !>              Note that the sense of this position vector is
      !>              independent of the direction of radiation travel
      !>              implied by the aberration correction.
      !>
      !>              Units are always km.
      !>
      !>              Non-inertial frames are treated as follows: letting
      !>              LTCENT be the one-way light time between the observer
      !>              and the central body associated with the frame, the
      !>              orientation of the frame is evaluated at ET-LTCENT,
      !>              ET+LTCENT, or ET depending on whether the requested
      !>              aberration correction is, respectively, for received
      !>              radiation, transmitted radiation, or is omitted.
      !>              LTCENT is computed using the method indicated by
      !>              ABCORR.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target position is
      !>              corrected for aberrations, then LT is the one-way
      !>              light time between the observer and the light time
      !>              corrected target location.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If name of target or observer cannot be translated to its
      !>         NAIF ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     2)  If the reference frame REF is not a recognized reference
      !>         frame, the error SPICE(UNKNOWNFRAME) is signaled.
      !>
      !>     3)  If the loaded kernels provide insufficient data to compute the
      !>         requested position vector, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     4)  If an error occurs while reading an SPK or other kernel file,
      !>         the error  is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     This routine computes positions using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. See the routine FURNSH and the SPK
      !>     and KERNEL Required Reading for further information on loading
      !>     (and unloading) kernels.
      !>
      !>     If the output position PTARG is to be expressed relative to a
      !>     non-inertial frame, or if any of the ephemeris data used to
      !>     compute PTARG are expressed relative to a non-inertial frame in
      !>     the SPK files providing those data, additional kernels may be
      !>     needed to enable the reference frame transformations required to
      !>     compute the position. These additional kernels may be C-kernels,
      !>     PCK files or frame kernels. Any such kernels must already be
      !>     loaded at the time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine is part of the user interface to the SPICE ephemeris
      !>     system. It allows you to retrieve position information for any
      !>     ephemeris object relative to any other in a reference frame that
      !>     is convenient for further computations.
      !>
      !>     This routine is identical in function to the routine SPKEZP
      !>     except that it allows you to refer to ephemeris objects by name
      !>     (via a character string).
      !>
      !>     Please refer to the Aberration Corrections Required Reading
      !>     abcorr.req for detailed information describing the nature and
      !>     calculation of the applied corrections.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Load a planetary ephemeris SPK, then look up a series of
      !>        geometric positions of the moon relative to the earth,
      !>        referenced to the J2000 frame.
      !>
      !>        Use the SPK kernel below to load the required Earth and
      !>        Moon ephemeris data.
      !>
      !>           de421.bsp
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      IMPLICIT NONE
      !>C
      !>C     Local constants
      !>C
      !>      CHARACTER*(*)         FRAME
      !>      PARAMETER           ( FRAME  = 'J2000' )
      !>
      !>      CHARACTER*(*)         ABCORR
      !>      PARAMETER           ( ABCORR = 'NONE' )
      !>
      !>      CHARACTER*(*)         SPK
      !>      PARAMETER           ( SPK    = 'de421.bsp' )
      !>
      !>C
      !>C     ET0 represents the date 2000 Jan 1 12:00:00 TDB.
      !>C
      !>      DOUBLE PRECISION      ET0
      !>      PARAMETER           ( ET0    = 0.0D0 )
      !>
      !>C
      !>C     Use a time step of 1 hour; look up 4 positions.
      !>C
      !>      DOUBLE PRECISION      STEP
      !>      PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>      INTEGER               MAXITR
      !>      PARAMETER           ( MAXITR = 4 )
      !>
      !>      CHARACTER*(*)         OBSRVR
      !>      PARAMETER           ( OBSRVR = 'Earth' )
      !>
      !>      CHARACTER*(*)         TARGET
      !>      PARAMETER           ( TARGET = 'Moon' )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      POS ( 3 )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Load the SPK file.
      !>C
      !>      CALL FURNSH ( SPK )
      !>
      !>C
      !>C     Step through a series of epochs, looking up a
      !>C     position vector at each one.
      !>C
      !>      DO I = 1, MAXITR
      !>
      !>         ET = ET0 + (I-1)*STEP
      !>
      !>         CALL SPKPOS ( TARGET, ET, FRAME, ABCORR, OBSRVR,
      !>     .                 POS,    LT                        )
      !>
      !>         WRITE (*,*) 'ET = ', ET
      !>         WRITE (*,*) ' '
      !>         WRITE (*,*) 'J2000 x-position (km):   ', POS(1)
      !>         WRITE (*,*) 'J2000 y-position (km):   ', POS(2)
      !>         WRITE (*,*) 'J2000 z-position (km):   ', POS(3)
      !>         WRITE (*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         ET =    0.0000000000000000
      !>
      !>         J2000 x-position (km):     -291608.38530964090
      !>         J2000 y-position (km):     -266716.83294678747
      !>         J2000 z-position (km):     -76102.487146783606
      !>
      !>         ET =    3600.0000000000000
      !>
      !>         J2000 x-position (km):     -289279.89831331203
      !>         J2000 y-position (km):     -269104.10842893779
      !>         J2000 z-position (km):     -77184.242072912006
      !>
      !>         ET =    7200.0000000000000
      !>
      !>         J2000 x-position (km):     -286928.00140550011
      !>         J2000 y-position (km):     -271469.99024601618
      !>         J2000 z-position (km):     -78259.908307700243
      !>
      !>         ET =    10800.000000000000
      !>
      !>         J2000 x-position (km):     -284552.90265547187
      !>         J2000 y-position (km):     -273814.30975274299
      !>         J2000 z-position (km):     -79329.406046598189
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     C.H. Acton         (JPL)
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 3.2.0, 01-OCT-2021 (JDR) (NJB)
      !>
      !>        Deleted include statement for frmtyp.inc.
      !>
      !>        Edited the header to comply with NAIF standard. Added complete
      !>        code example from existing fragment.
      !>
      !>        Updated $Particulars to refer to Aberration Corrections
      !>        Required Reading document, which was added to
      !>        $Required_Reading list.
      !>
      !>-    SPICELIB Version 3.1.0, 03-JUL-2014 (NJB) (BVS)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>        Updated to save the input body names and ZZBODTRN state
      !>        counters and to do name-ID conversions only if the counters
      !>        have changed.
      !>
      !>-    SPICELIB Version 3.0.3, 04-APR-2008 (NJB)
      !>
      !>        Corrected minor error in description of XLT+S aberration
      !>        correction.
      !>
      !>-    SPICELIB Version 3.0.2, 20-OCT-2003 (EDW)
      !>
      !>        Added mention that LT returns in seconds.
      !>
      !>-    SPICELIB Version 3.0.1, 29-JUL-2003 (NJB) (CHA)
      !>
      !>        Various minor header changes were made to improve clarity.
      !>
      !>-    SPICELIB Version 3.0.0, 31-DEC-2001 (NJB)
      !>
      !>        Updated to handle aberration corrections for transmission
      !>        of radiation. Formerly, only the reception case was
      !>        supported. The header was revised and expanded to explain
      !>        the functionality of this routine in more detail.
      !>
      !>-    SPICELIB Version 1.0.0, 03-MAR-1999 (WLT)
      recursive module subroutine spkpos ( ctx, targ, et, ref, abcorr, obs, ptarg, lt )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: targ  !! Target body name.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Reference frame of output position vector.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obs  !! Observing body name.
      real(wp), intent(out) :: ptarg    ( 3 )  !! Position of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      integer(ip) :: targid
      integer(ip) :: obsid
      logical :: found
      if ( .not. allocated ( ctx%spkpos_state ) ) allocate ( ctx%spkpos_state )
      associate ( svctr1 => ctx%spkpos_state%svctr1, &
                  svtarg => ctx%spkpos_state%svtarg, &
                  svtgid => ctx%spkpos_state%svtgid, &
                  svfnd1 => ctx%spkpos_state%svfnd1, &
                  svctr2 => ctx%spkpos_state%svctr2, &
                  svobsn => ctx%spkpos_state%svobsn, &
                  svobsi => ctx%spkpos_state%svobsi, &
                  svfnd2 => ctx%spkpos_state%svfnd2, &
                  first => ctx%spkpos_state%first )
      if ( ctx%failed() ) return

!
!     Initialization.
!
      if ( first ) then

!
!        Initialize counters.
!
         call zzctruin( ctx, svctr1 )
         call zzctruin( ctx, svctr2 )

         first = .false.

      end if

!
!     Starting from translation of target name to its code
!
      call zzbods2c ( ctx, svctr1, svtarg, svtgid, svfnd1, &
                      targ, targid, found    )

      if ( .not. found ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE toolkit. ' &
         //            'Alternatively you may call SPKEZP ' &
         //            'directly if you know the SPICE id-codes ' &
         //            'for both ''#'' and ''#'' '                )
         call ctx%errch  ( '#', targ                                  )
         call ctx%errch  ( '#', targ                                  )
         call ctx%errch  ( '#', obs                                   )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Now do the same for observer.
!
      call zzbods2c ( ctx, svctr2, svobsn, svobsi, svfnd2, &
                      obs, obsid, found    )

      if ( .not. found ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE toolkit. ' &
         //            'Alternatively you may call SPKEZP ' &
         //            'directly if you know the SPICE id-codes ' &
         //            'for both ''#'' and ''#'' '                )
         call ctx%errch  ( '#', obs                                   )
         call ctx%errch  ( '#', targ                                  )
         call ctx%errch  ( '#', obs                                   )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     After all translations are done we can call SPKEZP.
!
      call spkezp ( ctx, targid, et, ref, abcorr, obsid, ptarg, lt )

      return
      end associate
      end subroutine spkpos

      !> Extract a subset of the data in an SPK segment into a
      !> separate segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE,
      !>     DESCR,
      !>     IDENT    are the file handle assigned to a SPK file, the
      !>              descriptor for a segment within the file, and the
      !>              identifier for that segment. Together they determine a
      !>              complete set of ephemeris data, from which a subset is to
      !>              be extracted.
      !>
      !>     BEGIN,
      !>     END      are the initial and final epochs (ephemeris time) of the
      !>              subset.
      !>
      !>     NEWH     is the file handle assigned to the file in which the new
      !>              segment is to be written. The file must be open for write
      !>              access. NEWH and HANDLE may refer to the same file.
      !>
      !>## Detailed Output
      !>
      !>     See $Files section.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the condition
      !>
      !>            ALPHA  <=  BEGIN  <=  END  <=  OMEGA
      !>
      !>         is not satisfied (where ALPHA and OMEGA are the initial and
      !>         final epochs of the segment respectively), the error
      !>         SPICE(SPKNOTASUBSET) is signaled.
      !>
      !>     2)  If the segment type is not supported by the current version of
      !>         SPKSUB, the error SPICE(SPKTYPENOTSUPP) is signaled.
      !>
      !>## Files
      !>
      !>     A new segment, which contains a subset of the data in the
      !>     segment specified by DESCR and HANDLE, is written to the SPK
      !>     file attached to NEWH.
      !>
      !>## Particulars
      !>
      !>     Sometimes, the segments in official source files---planetary
      !>     Developmental Ephemeris (DE) files, archival spacecraft
      !>     ephemeris files, and so on---contain more data than is needed
      !>     by a particular user. SPKSUB allows a user to extract from a
      !>     segment the smallest amount of ephemeris data sufficient to
      !>     cover a specific interval.
      !>
      !>     The new segment is written with the same identifier as the
      !>     original segment, and with the same descriptor, with the
      !>     following components changed:
      !>
      !>     1)  ALPHA and OMEGA (DC(1) and DC(2)) are assigned the values
      !>         specified by BEGIN and END.
      !>
      !>     2)  The beginning and ending segment addresses (IC(5) and IC(6))
      !>         are changed to reflect the location of the new segment.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, the descriptor for each segment
      !>     in a source SPK file is examined. For each segment that covers a
      !>     specified time interval, the smallest possible subset of data
      !>     from that segment, sufficient to cover the interval, is extracted
      !>     into a custom SPK file.
      !>
      !>     Assume that the source and custom files have been opened, for
      !>     read and write access, with handles SRC and CUST respectively.
      !>
      !>        CALL DAFBFS ( SRC    )
      !>        CALL DAFFNA ( FOUND  )
      !>
      !>        DO WHILE ( FOUND )
      !>           CALL DAFGS ( DESCR )
      !>           CALL DAFUS ( DESCR, 2, 6, DC, IC )
      !>
      !>           IF ( DC(1) .LE. BEGIN  .AND.  END .LE. DC(2) ) THEN
      !>              CALL DAFGN  ( IDENT )
      !>              CALL SPKSUB ( SRC, DESCR, IDENT, BEGIN, END, CUST )
      !>           END IF
      !>
      !>           CALL DAFFNA ( FOUND )
      !>        END DO
      !>
      !>## Restrictions
      !>
      !>     1)  There is no way for SPKSUB to verify that the descriptor and
      !>         identifier are the original ones for the segment. Changing
      !>         the descriptor can cause the data in the new segment to be
      !>         evaluated incorrectly; changing the identifier can destroy
      !>         the path from the data back to its original source.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     J.M. Lynch         (JPL)
      !>     H.A. Neilan        (JPL)
      !>     W.L. Taber         (JPL)
      !>     R.E. Thurman       (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 9.1.0, 14-APR-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard. Removed
      !>        unnecessary $Revisions section. Moved SPK required reading from
      !>        $Literature_References to $Required_Reading section.
      !>
      !>-    SPICELIB Version 9.0.0, 23-DEC-2013 (NJB)
      !>
      !>        The routine was updated to handle types 19, 20 and 21. Some
      !>        minor changes were made to comments.
      !>
      !>-    SPICELIB Version 8.0.0, 12-AUG-2002 (NJB)
      !>
      !>        The routine was updated to handle type 18.
      !>
      !>-    SPICELIB Version 7.0.0, 06-NOV-1999 (NJB)
      !>
      !>        The routine was updated to handle types 12 and 13.
      !>
      !>-    SPICELIB Version 6.0.0, 30-JUN-1997 (WLT)
      !>
      !>        The routine was updated to handle types 10 and 17.
      !>
      !>-    SPICELIB Version 5.0.0, 10-MAR-1995 (KRG)
      !>
      !>        The routine was updated to handle type 14.
      !>
      !>-    SPICELIB Version 4.0.0, 07-NOV-1994 (WLT)
      !>
      !>        The routine was updated to handle type 15.
      !>
      !>-    SPICELIB Version 3.0.0, 05-AUG-1993 (NJB)
      !>
      !>        The routine was updated to handle types 08 and 09.
      !>
      !>-    SPICELIB Version 2.0.0, 01-APR-1992 (JML)
      !>
      !>        1) The routine was updated to handle type 05.
      !>
      !>        2) DESCR was being used as both an input and output
      !>           variable when it was only supposed to be used for
      !>           input. A new local variable, NDSCR, was added where DESCR
      !>           was being altered.
      !>
      !>-    SPICELIB Version 1.0.1, 22-MAR-1990 (HAN)
      !>
      !>        Literature references added to the header.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (IMU) (RET)
      module subroutine spksub ( ctx, handle, descr, ident, begin, end, newh )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of source segment.
      real(wp), intent(in) :: descr    ( 5 )  !! Descriptor of source segment.
      character(*), intent(in) :: ident  !! Identifier of source segment.
      real(wp), intent(in) :: begin  !! Beginning (initial epoch) of subset.
      real(wp), intent(in) :: end  !! End (final epoch) of subset.
      integer(ip), intent(in) :: newh  !! Handle of new segment.

      real(wp) :: alpha
      real(wp) :: dc       ( 2 )
      real(wp) :: ndscr    ( 5 )
      real(wp) :: omega

      integer(ip) :: baddr
      integer(ip) :: eaddr
      integer(ip) :: ic       ( 6 )
      integer(ip) :: type

      logical :: okay

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Unpack the descriptor.
!
      call dafus ( ctx, descr, 2, 6, dc, ic )

      alpha = dc(1)
      omega = dc(2)
      type  = ic(4)
      baddr = ic(5)
      eaddr = ic(6)

!
!     Make sure the epochs check out.
!
      okay = (        alpha <= begin &
               .and.  begin <= end &
               .and.  end   <= omega )

      if ( .not. okay ) then
         call ctx%setmsg ( 'Specified interval [#, #] is not a subset ' // &
                       'of segment interval [#, #].' )
         call ctx%errdp  ( '#', begin                    )
         call ctx%errdp  ( '#', end                      )
         call ctx%errdp  ( '#', alpha                    )
         call ctx%errdp  ( '#', omega                    )
         call ctx%sigerr ( 'SPICE(SPKNOTASUBSET)'        )

         return
      end if

!
!     Begin the new segment, with a descriptor containing the subset
!     epochs.
!
      dc(1) = begin
      dc(2) = end
      call dafps  ( ctx, 2, 6, dc, ic, ndscr )

!
!     Let the type-specific (SPKSnn) routines decide what to move.
!
      if ( type == 01 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks01 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 02 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks02 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 03 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks03 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

!
!      Type 04 has not been yet been added to SPICELIB.
!
!      ELSE IF ( TYPE .EQ. 04 ) THEN
!         CALL DAFBNA ( NEWH, NDSCR,  IDENT )
!         CALL SPKS04 ( HANDLE, BADDR, EADDR, BEGIN, END )
!         CALL DAFENA

      else if ( type == 05 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks05 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 08 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks08 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 09 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks09 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 10 ) then
         call spks10 ( ctx, handle, descr, newh, ndscr, ident )

      else if ( type == 12 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks12 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 13 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks13 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 14 ) then
         call spks14 ( ctx, handle, descr, newh, ndscr, ident )

      else if ( type == 15 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks15 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 17 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks17 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 18 ) then
         call dafbna ( ctx, newh, ndscr,  ident )
         call spks18 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 19 ) then
         call dafbna ( ctx, newh,   ndscr, ident )
         call spks19 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 20 ) then
         call dafbna ( ctx, newh,   ndscr, ident )
         call spks20 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else if ( type == 21 ) then
         call dafbna ( ctx, newh,   ndscr, ident )
         call spks21 ( ctx, handle, baddr, eaddr, begin, end )
         call dafena ( ctx )

      else
         call ctx%setmsg ( 'SPK data type # is not supported.' )
         call ctx%errint ( '#', type                           )
         call ctx%sigerr ( 'SPICE(SPKTYPENOTSUPP)'             )

         return
      end if

      return
      end subroutine spksub

      !> Return the state (position and velocity) of a target body
      !> relative to an observer, optionally corrected for light time and
      !> stellar aberration, expressed relative to an inertial reference
      !> frame. An input subroutine provides the state of the observer
      !> relative to its center of motion.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     TARG        is the NAIF ID code for a target body. The target
      !>                 and observer define a state vector whose position
      !>                 component points from the observer to the target.
      !>
      !>     ET          is the ephemeris time, expressed as seconds past
      !>                 J2000 TDB, at which the state of the target body
      !>                 relative to the observer is to be computed.  ET
      !>                 refers to time at the observer's location.
      !>
      !>     REF         is the inertial reference frame with respect to which
      !>                 the output state STARG is expressed. REF must be
      !>                 recognized by the SPICE Toolkit.  The acceptable
      !>                 frames are listed in the Frames Required Reading, as
      !>                 well as in the SPICELIB routine CHGIRF.
      !>
      !>                 Case and blanks are not significant in the string
      !>                 REF.
      !>
      !>     ABCORR      indicates the aberration corrections to be applied
      !>                 to the state of the target body to account for one-way
      !>                 light time and stellar aberration.  See the discussion
      !>                 in the Particulars section for recommendations on
      !>                 how to choose aberration corrections.
      !>
      !>                 ABCORR may be any of the following:
      !>
      !>                    'NONE'     Apply no correction. Return the
      !>                               geometric state of the target body
      !>                               relative to the observer.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "reception" case in which photons depart from the
      !>                 target's location at the light-time corrected epoch
      !>                 ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                    'LT'       Correct for one-way light time (also
      !>                               called "planetary aberration") using a
      !>                               Newtonian formulation. This correction
      !>                               yields the state of the target at the
      !>                               moment it emitted photons arriving at
      !>                               the observer at ET.
      !>
      !>                               The light time correction uses an
      !>                               iterative solution of the light time
      !>                               equation (see Particulars for details).
      !>                               The solution invoked by the 'LT' option
      !>                               uses one iteration.
      !>
      !>                    'LT+S'     Correct for one-way light time and
      !>                               stellar aberration using a Newtonian
      !>                               formulation. This option modifies the
      !>                               state obtained with the 'LT' option to
      !>                               account for the observer's velocity
      !>                               relative to the solar system
      !>                               barycenter. The result is the apparent
      !>                               state of the target---the position and
      !>                               velocity of the target as seen by the
      !>                               observer.
      !>
      !>                    'CN'       Converged Newtonian light time
      !>                               correction. In solving the light time
      !>                               equation, the 'CN' correction iterates
      !>                               until the solution converges (three
      !>                               iterations on all supported platforms).
      !>                               Whether the 'CN+S' solution is
      !>                               substantially more accurate than the
      !>                               'LT' solution depends on the geometry
      !>                               of the participating objects and on the
      !>                               accuracy of the input data. In all
      !>                               cases this routine will execute more
      !>                               slowly when a converged solution is
      !>                               computed. See the Particulars section of
      !>                               SPKEZR for a discussion of precision of
      !>                               light time corrections.
      !>
      !>                    'CN+S'     Converged Newtonian light time
      !>                               correction and stellar aberration
      !>                               correction.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "transmission" case in which photons *depart* from
      !>                 the observer's location at ET and arrive at the
      !>                 target's location at the light-time corrected epoch
      !>                 ET+LT:
      !>
      !>                    'XLT'      "Transmission" case:  correct for
      !>                               one-way light time using a Newtonian
      !>                               formulation. This correction yields the
      !>                               state of the target at the moment it
      !>                               receives photons emitted from the
      !>                               observer's location at ET.
      !>
      !>                    'XLT+S'    "Transmission" case:  correct for
      !>                               one-way light time and stellar
      !>                               aberration using a Newtonian
      !>                               formulation  This option modifies the
      !>                               state obtained with the 'XLT' option to
      !>                               account for the observer's velocity
      !>                               relative to the solar system
      !>                               barycenter. The position component of
      !>                               the computed target state indicates the
      !>                               direction that photons emitted from the
      !>                               observer's location must be "aimed" to
      !>                               hit the target.
      !>
      !>                    'XCN'      "Transmission" case:  converged
      !>                               Newtonian light time correction.
      !>
      !>                    'XCN+S'    "Transmission" case:  converged
      !>                               Newtonian light time correction and
      !>                               stellar aberration correction.
      !>
      !>     OBSSUB      is the name of an external subroutine that returns
      !>                 the geometric state of the observer relative to a
      !>                 center of motion, expressed in the inertial reference
      !>                 frame REF, at the epoch ET.
      !>
      !>                 The calling sequence of OBSSSUB is
      !>
      !>                    SUBROUTINE OBSSUB ( ET, REF, OBSCTR, STATE )
      !>
      !>                    DOUBLE PRECISION      ET
      !>                    CHARACTER*(*)         REF
      !>                    INTEGER               OBSCTR
      !>                    DOUBLE PRECISION      STATE ( 6 )
      !>
      !>                    The inputs of OBSSUB are ET and REF; the outputs
      !>                    are OBSCTR and STATE. STATE is the geometric state
      !>                    of the observer relative to the returned center of
      !>                    motion at ET, expressed in the frame REF.
      !>
      !>                 The target designated by TARG and the observer whose
      !>                 ephemeris is given by OBSSUB define a state vector
      !>                 having a position component that points from the
      !>                 observer to the target.
      !>
      !>## Detailed Output
      !>
      !>     STARG       is a Cartesian state vector representing the position
      !>                 and velocity of the target body relative to the
      !>                 specified observer. STARG is corrected for the
      !>                 specified aberrations, and is expressed with respect
      !>                 to the specified inertial reference frame.  The first
      !>                 three components of STARG represent the x-, y- and
      !>                 z-components of the target's position; last three
      !>                 components form the corresponding velocity vector.
      !>
      !>                 The position component of STARG points from the
      !>                 observer's location at ET to the aberration-corrected
      !>                 location of the target. Note that the sense of the
      !>                 position vector is independent of the direction of
      !>                 radiation travel implied by the aberration
      !>                 correction.
      !>
      !>                 Units are always km and km/sec.
      !>
      !>     LT          is the one-way light time between the observer and
      !>                 target in seconds.  If the target state is corrected
      !>                 for aberrations, then LT is the one-way light time
      !>                 between the observer and the light time corrected
      !>                 target location.
      !>
      !>     DLT         is the derivative with respect to barycentric
      !>                 dynamical time of the one way light time between
      !>                 target and observer:
      !>
      !>                    DLT = d(LT)/d(ET)
      !>
      !>                 DLT can also be described as the rate of change of
      !>                 one way light time. DLT is unitless, since LT and
      !>                 ET both have units of TDB seconds.
      !>
      !>                 If the observer and target are at the same position,
      !>                 then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the value of ABCORR is not recognized, the error
      !>        is diagnosed by a routine in the call tree of this
      !>        routine.
      !>
      !>     2) If the reference frame requested is not a recognized
      !>        inertial reference frame, the error SPICE(BADFRAME)
      !>        is signaled.
      !>
      !>     3) If the state of the target relative to the solar system
      !>        barycenter cannot be computed, the error will be diagnosed
      !>        by routines in the call tree of this routine.
      !>
      !>     4) If the observer and target are at the same position,
      !>        then DLT is set to zero. This situation could arise,
      !>        for example, when the observer is Mars and the target
      !>        is the Mars barycenter.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH.  Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any
      !>     such kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level SPK API routines that can
      !>     perform both light time and stellar aberration corrections.
      !>     User applications normally will not need to call this routine
      !>     directly.
      !>
      !>     See the header of the routine SPKEZR for a detailed discussion
      !>     of aberration corrections.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     1) This routine must not be called by routines of the SPICE
      !>        frame subsystem. It must not be called by any portion of
      !>        the SPK subsystem other than the private SPK function-based
      !>        component.
      !>
      !>     2) The input subroutine OBSSUB must not call this routine
      !>        or any of the supporting, private SPK routines
      !>
      !>           ZZSPKFAP
      !>           ZZSPKFLT
      !>
      !>     3) The kernel files to be used by ZZSPKFAO must be loaded
      !>        (normally by the SPICELIB kernel loader FURNSH) before
      !>        this routine is called.
      !>
      !>     4) Unlike most other SPK state computation routines, this
      !>        routine requires that the output state be relative to an
      !>        inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>     Last update was 15-APR-2014 (NJB)
      !>
      !>        Previous update was Version 1.0.0, 22-FEB-2012
      !>
      !>## Revisions
      !>
      !>     None.
      module subroutine zzspkfao (  ctx, targ, et, ref, abcorr, obssub, starg, lt, dlt  )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      procedure(zzspk_state) :: obssub  !! routine returning the observer's state (relative to the SSB)
      integer(ip), intent(in) :: targ  !! Target body.
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(out) :: starg    ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
!
!     Local variables
!
      real(wp) :: acc    ( 3 )
      real(wp) :: ssbobs ( 6 )
      real(wp) :: stctr  ( 6 )
      real(wp) :: stctro ( 6 )
      real(wp) :: stobs  ( 6, 2 )
      real(wp) :: t
      integer(ip) :: i
      integer(ip) :: obsctr
      integer(ip) :: refid
      logical :: attblk ( nabcor )
      if ( .not. allocated ( ctx%zzspkfao_state ) ) allocate ( ctx%zzspkfao_state )
      associate ( pass1 => ctx%zzspkfao_state%pass1, &
                  prvcor => ctx%zzspkfao_state%prvcor, &
                  usestl => ctx%zzspkfao_state%usestl )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      if (  pass1  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           USESTL is .TRUE. when stellar aberration correction is
!           specified.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         usestl  =  attblk ( stlidx )

         pass1   = .false.

      end if

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Prepare to look up the apparent state of the target
!     as seen by the observer. We'll need the geometric
!     state of the observer relative to the solar system
!     barycenter. If we're using stellar aberration
!     corrections, we'll need the observer's acceleration
!     as well.
!
!     Get the geometric state of the observer relative to the SSB,
!     which we'll call SSBOBS.
!
!     Start by looking up the state of the observer with respect
!     to its center of motion, expressed in frame REF. Add to this
!     the state of the center with respect to the solar system
!     barycenter.
!
      call obssub ( ctx, et,     ref,   obsctr, stctro )
      call spkssb ( ctx, obsctr, et,    ref,    stctr  )

      if ( ctx%failed() ) return

      ssbobs = stctro + stctr

      if ( usestl ) then
!
!        Numerically differentiate the observer velocity relative to
!        the SSB to obtain acceleration. We first evaluate the
!        geometric state of the observer relative to the solar system
!        barycenter at ET +/- DELTA.

         do i = 1, 2

            t = et + (2*i - 3)*delta

            call obssub ( ctx, t,      ref,   obsctr, stctro     )
            call spkssb ( ctx, obsctr, t,     ref,    stctr      )

            if ( ctx%failed() ) return

            stobs(:,i) = stctro + stctr

         end do

         call qderiv ( ctx, 3, stobs(4,1), stobs(4,2), delta, acc )

      else

         acc = 0.0_wp

      end if

!
!     Look up the apparent state. The light time and light
!     rate are returned as well.
!
      call spkaps ( ctx, targ,   et,  ref,   abcorr, &
                    ssbobs, acc, starg, lt,     dlt )

      return
      end associate
      end subroutine zzspkfao

      !> Given the state and acceleration of an observer relative to the
      !> solar system barycenter, return the state (position and velocity)
      !> of a target body relative to the observer, optionally corrected
      !> for light time and stellar aberration. All input and output
      !> vectors are expressed relative to an inertial reference frame. An
      !> input subroutine provides the state of the target relative to its
      !> center of motion.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     TRGSUB      is the name of an external subroutine that returns
      !>                 the geometric state of the target body relative to a
      !>                 center of motion, expressed in the inertial reference
      !>                 frame REF, at the epoch ET.
      !>
      !>                 The calling sequence of TRGSUB is
      !>
      !>                    SUBROUTINE TRGSUB ( ET, REF, TRGCTR, STATE )
      !>
      !>                    DOUBLE PRECISION      ET
      !>                    CHARACTER*(*)         REF
      !>                    INTEGER               TRGCTR
      !>                    DOUBLE PRECISION      STATE ( 6 )
      !>
      !>                    The inputs of TRGSUB are ET and REF; the outputs
      !>                    are TRGCTR and STATE. STATE is the geometric state
      !>                    of the target relative to the returned center of
      !>                    motion at ET, expressed in the frame REF.
      !>
      !>                 The target and observer define a state vector whose
      !>                 position component points from the observer to the
      !>                 target.
      !>
      !>     ET          is the ephemeris time, expressed as seconds past
      !>                 J2000 TDB, at which the state of the target body
      !>                 relative to the observer is to be computed.  ET
      !>                 refers to time at the observer's location.
      !>
      !>     REF         is the inertial reference frame with respect to which
      !>                 the input state STOBS, the input acceleration ACCOBS,
      !>                 and the output state STARG are expressed. REF must be
      !>                 recognized by the SPICE Toolkit.  The acceptable
      !>                 frames are listed in the Frames Required Reading, as
      !>                 well as in the SPICELIB routine CHGIRF.
      !>
      !>                 Case and blanks are not significant in the string
      !>                 REF.
      !>
      !>     ABCORR      indicates the aberration corrections to be applied
      !>                 to the state of the target body to account for one-way
      !>                 light time and stellar aberration. See the discussion
      !>                 in the header of SPKEZR for recommendations on
      !>                 how to choose aberration corrections.
      !>
      !>                 ABCORR may be any of the following:
      !>
      !>                    'NONE'     Apply no correction. Return the
      !>                               geometric state of the target body
      !>                               relative to the observer.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "reception" case in which photons depart from the
      !>                 target's location at the light-time corrected epoch
      !>                 ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                    'LT'       Correct for one-way light time (also
      !>                               called "planetary aberration") using a
      !>                               Newtonian formulation. This correction
      !>                               yields the state of the target at the
      !>                               moment it emitted photons arriving at
      !>                               the observer at ET.
      !>
      !>                               The light time correction uses an
      !>                               iterative solution of the light time
      !>                               equation (see Particulars for details).
      !>                               The solution invoked by the 'LT' option
      !>                               uses one iteration.
      !>
      !>                    'LT+S'     Correct for one-way light time and
      !>                               stellar aberration using a Newtonian
      !>                               formulation. This option modifies the
      !>                               state obtained with the 'LT' option to
      !>                               account for the observer's velocity
      !>                               relative to the solar system
      !>                               barycenter. The result is the apparent
      !>                               state of the target---the position and
      !>                               velocity of the target as seen by the
      !>                               observer.
      !>
      !>                    'CN'       Converged Newtonian light time
      !>                               correction. In solving the light time
      !>                               equation, the 'CN' correction iterates
      !>                               until the solution converges (three
      !>                               iterations on all supported platforms).
      !>                               Whether the 'CN+S' solution is
      !>                               substantially more accurate than the
      !>                               'LT' solution depends on the geometry
      !>                               of the participating objects and on the
      !>                               accuracy of the input data. In all
      !>                               cases this routine will execute more
      !>                               slowly when a converged solution is
      !>                               computed. See the Particulars section of
      !>                               SPKEZR for a discussion of precision of
      !>                               light time corrections.
      !>
      !>                    'CN+S'     Converged Newtonian light time
      !>                               correction and stellar aberration
      !>                               correction.
      !>
      !>                 The following values of ABCORR apply to the
      !>                 "transmission" case in which photons *depart* from
      !>                 the observer's location at ET and arrive at the
      !>                 target's location at the light-time corrected epoch
      !>                 ET+LT:
      !>
      !>                    'XLT'      "Transmission" case:  correct for
      !>                               one-way light time using a Newtonian
      !>                               formulation. This correction yields the
      !>                               state of the target at the moment it
      !>                               receives photons emitted from the
      !>                               observer's location at ET.
      !>
      !>                    'XLT+S'    "Transmission" case:  correct for
      !>                               one-way light time and stellar
      !>                               aberration using a Newtonian
      !>                               formulation  This option modifies the
      !>                               state obtained with the 'XLT' option to
      !>                               account for the observer's velocity
      !>                               relative to the solar system
      !>                               barycenter. The position component of
      !>                               the computed target state indicates the
      !>                               direction that photons emitted from the
      !>                               observer's location must be "aimed" to
      !>                               hit the target.
      !>
      !>                    'XCN'      "Transmission" case:  converged
      !>                               Newtonian light time correction.
      !>
      !>                    'XCN+S'    "Transmission" case:  converged
      !>                               Newtonian light time correction and
      !>                               stellar aberration correction.
      !>
      !>                 Neither special nor general relativistic effects are
      !>                 accounted for in the aberration corrections applied
      !>                 by this routine.
      !>
      !>                 Case and blanks are not significant in the string
      !>                 ABCORR.
      !>
      !>     STOBS       is the geometric state of the observer relative to
      !>                 the solar system barycenter at ET. STOBS is expressed
      !>                 relative to the reference frame designated by REF.
      !>                 The target and observer define a state vector whose
      !>                 position component points from the observer to the
      !>                 target.
      !>
      !>     ACCOBS      is the geometric acceleration of the observer
      !>                 relative to the solar system barycenter at ET. This
      !>                 is the derivative with respect to time of the
      !>                 velocity portion of STOBS. ACCOBS is expressed
      !>                 relative to the reference frame designated by REF.
      !>
      !>                 ACCOBS is used for computing stellar aberration
      !>                 corrected velocity. If stellar aberration corrections
      !>                 are not specified by ABCORR, ACCOBS is ignored; the
      !>                 caller need not provide a valid input value in this
      !>                 case.
      !>
      !>## Detailed Output
      !>
      !>     STARG       is a Cartesian state vector representing the position
      !>                 and velocity of the target body relative to the
      !>                 specified observer. STARG is corrected for the
      !>                 specified aberrations, and is expressed with respect
      !>                 to the inertial reference frame designated by REF.
      !>                 The first three components of STARG represent the x-,
      !>                 y- and z-components of the target's position; last
      !>                 three components form the corresponding velocity
      !>                 vector.
      !>
      !>                 The position component of STARG points from the
      !>                 observer's location at ET to the aberration-corrected
      !>                 location of the target. Note that the sense of the
      !>                 position vector is independent of the direction of
      !>                 radiation travel implied by the aberration
      !>                 correction.
      !>
      !>                 Units are always km and km/sec.
      !>
      !>     LT          is the one-way light time between the observer and
      !>                 target in seconds.  If the target state is corrected
      !>                 for light time, then LT is the one-way light time
      !>                 between the observer and the light time-corrected
      !>                 target location.
      !>
      !>     DLT         is the derivative with respect to barycentric
      !>                 dynamical time of the one way light time between
      !>                 target and observer:
      !>
      !>                    DLT = d(LT)/d(ET)
      !>
      !>                 DLT can also be described as the rate of change of
      !>                 one way light time. DLT is unitless, since LT and
      !>                 ET both have units of TDB seconds.
      !>
      !>                 If the observer and target are at the same position,
      !>                 then DLT is set to zero.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the value of ABCORR is not recognized, the error
      !>        is diagnosed by a routine in the call tree of this
      !>        routine.
      !>
      !>     2) If the reference frame requested is not a recognized
      !>        inertial reference frame, the error SPICE(BADFRAME)
      !>        is signaled.
      !>
      !>     3) If the state of the target relative to the solar system
      !>        barycenter cannot be computed, the error will be diagnosed
      !>        by routines in the call tree of this routine.
      !>
      !>     4) If the observer and target are at the same position,
      !>        then DLT is set to zero. This situation could arise,
      !>        for example, when the observer is Mars and the target
      !>        is the Mars barycenter.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH.  Application programs typically load
      !>     kernels once before this routine is called, for example during
      !>     program initialization; kernels need not be loaded repeatedly.
      !>     See the routine FURNSH and the SPK and KERNEL Required Reading
      !>     for further information on loading (and unloading) kernels.
      !>
      !>     If any of the ephemeris data used to compute STARG are expressed
      !>     relative to a non-inertial frame in the SPK files providing those
      !>     data, additional kernels may be needed to enable the reference
      !>     frame transformations required to compute the state. Normally
      !>     these additional kernels are PCK files or frame kernels. Any such
      !>     kernels must already be loaded at the time this routine is
      !>     called.
      !>
      !>## Particulars
      !>
      !>     This routine supports higher-level routines that can
      !>     perform both light time and stellar aberration corrections
      !>     and that use target states provided by subroutines rather
      !>     than by the conventional, public SPK APIs. For example, this
      !>     routine can be used for objects having fixed positions
      !>     on the surfaces of planets.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     1) This routine must not be called by routines of the SPICE
      !>        frame subsystem. It must not be called by any portion of
      !>        the SPK subsystem other than the private SPK function-based
      !>        component.
      !>
      !>     2) The input subroutine TRGSUB must not call this routine
      !>        or any of the supporting, private SPK routines
      !>
      !>           ZZSPKFAT
      !>           ZZSPKFAO
      !>           ZZSPKFZO
      !>           ZZSPKFZT
      !>
      !>     3)  When possible, the routine SPKGEO should be used instead of
      !>         this routine to compute geometric states. SPKGEO introduces
      !>         less round-off error when the observer and target have common
      !>         center that is closer to both objects than is the solar
      !>         system barycenter.
      !>
      !>     4)  Unlike most other SPK state computation routines, this
      !>         routine requires that the output state be relative to an
      !>         inertial reference frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 04-JUL-2014 (NJB)
      !>
      !>        Discussion of light time corrections was updated. Assertions
      !>        that converged light time corrections are unlikely to be
      !>        useful were removed.
      !>
      !>-    SPICELIB Version 1.0.0, 09-JAN-2011 (NJB)
      !>
      !>## Revisions
      !>
      !>     None.
      module subroutine zzspkfap (  ctx, trgsub, et, ref, abcorr, stobs, accobs, starg, lt, dlt  )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      procedure(zzspk_state) :: trgsub  !! routine returning the target's state (relative to the SSB)
      real(wp), intent(in) :: et  !! Observer epoch.
      character(*), intent(in) :: ref  !! Inertial reference frame of output state.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      real(wp), intent(in) :: stobs  ( 6 )  !! State of the observer relative to the SSB.
      real(wp), intent(in) :: accobs ( 3 )  !! Acceleration of the observer relative to the SSB.
      real(wp), intent(out) :: starg  ( 6 )  !! State of target.
      real(wp), intent(out) :: lt  !! One way light time between observer and target.
      real(wp), intent(out) :: dlt  !! Derivative of light time with respect to time.
!
!     Local variables
!
      real(wp) :: corpos ( 3 )
      real(wp) :: corvel ( 3 )
      real(wp) :: dpcorr ( 3 )
      real(wp) :: pcorr  ( 3 )
      integer(ip) :: refid
      logical :: attblk ( nabcor )
      logical :: uselt
      if ( .not. allocated ( ctx%zzspkfap_state ) ) allocate ( ctx%zzspkfap_state )
      associate ( pass1 => ctx%zzspkfap_state%pass1, &
                  prvcor => ctx%zzspkfap_state%prvcor, &
                  usestl => ctx%zzspkfap_state%usestl, &
                  xmit => ctx%zzspkfap_state%xmit )
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      if (  pass1  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any.  Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USECN indicates converged Newtonian light time correction.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         xmit    =  attblk ( xmtidx )
         uselt   =  attblk ( ltidx  )
         usestl  =  attblk ( stlidx )

         pass1   = .false.

      end if

!
!     See if the reference frame is a recognized inertial frame.
!
      call irfnum ( ctx, ref, refid )

      if ( refid == 0 ) then

         call ctx%setmsg ( 'The requested frame ''#'' is not a ' &
         //            'recognized inertial frame. '        )
         call ctx%errch  ( '#', ref                             )
         call ctx%sigerr ( 'SPICE(BADFRAME)'                    )
         return

      end if

!
!     Get the state of the target relative to the observer,
!     optionally corrected for light time.
!
      call zzspkflt ( ctx, trgsub, et,    ref, abcorr, &
                      stobs,  starg, lt,  dlt     )

      if ( ctx%failed() ) return

!
!     If stellar aberration corrections are not needed, we're
!     already done.
!
      if ( .not. usestl ) return

!
!     Get the stellar aberration correction and its time derivative.
!
      call zzstelab ( ctx, xmit, accobs, stobs(4), starg, pcorr, dpcorr )

!
!     Adding the stellar aberration correction to the light
!     time-corrected target position yields the position corrected for
!     both light time and stellar aberration.
!
      corpos = pcorr + starg(1:3)
      starg(1:3) = corpos

!
!     Velocity is treated in an analogous manner.
!
      corvel = dpcorr + starg(4:6)
      starg(4:6) = corvel

      return
      end associate
      end subroutine zzspkfap

      !> Return the state (position and velocity) of a target body
      !> relative to an observing body, optionally corrected for light
      !> time (planetary aberration) and stellar aberration.
      !>
      !>## Detailed Input
      !>
      !>     TARG     is the NAIF ID code for a target body. The target
      !>              and observer define a state vector whose position
      !>              component points from the observer to the target.
      !>
      !>     ET       is the ephemeris time, expressed as seconds past J2000
      !>              TDB, at which the state of the target body relative to
      !>              the observer is to be computed. ET refers to time at
      !>              the observer's location.
      !>
      !>     REF      is the name of the reference frame relative to which
      !>              the output state vector should be expressed. This may
      !>              be any frame supported by the SPICE system, including
      !>              built-in frames (documented in the Frames Required
      !>              Reading) and frames defined by a loaded frame kernel
      !>              (FK).
      !>
      !>              When REF designates a non-inertial frame, the
      !>              orientation of the frame is evaluated at an epoch
      !>              dependent on the selected aberration correction.
      !>              See the description of the output state vector STARG
      !>              for details.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              to the state of the target body to account for one-way
      !>              light time and stellar aberration. See the discussion
      !>              in the $Particulars section for recommendations on
      !>              how to choose aberration corrections.
      !>
      !>              ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric state of the target body
      !>                            relative to the observer.
      !>
      !>              The following values of ABCORR apply to the
      !>              "reception" case in which photons depart from the
      !>              target's location at the light-time corrected epoch
      !>              ET-LT and *arrive* at the observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the state of the target at the
      !>                            moment it emitted photons arriving at
      !>                            the observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation (see $Particulars for details).
      !>                            The solution invoked by the 'LT' option
      !>                            uses one iteration.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            state obtained with the 'LT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The result is the apparent
      !>                            state of the target---the position and
      !>                            velocity of the target as seen by the
      !>                            observer.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges (three
      !>                            iterations on all supported platforms).
      !>                            Whether the 'CN+S' solution is
      !>                            substantially more accurate than the
      !>                            'LT' solution depends on the geometry
      !>                            of the participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed. See the $Particulars section
      !>                            below for a discussion of precision of
      !>                            light time corrections.
      !>
      !>                 'CN+S'     Converged Newtonian light time
      !>                            correction and stellar aberration
      !>                            correction.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *depart* from
      !>              the observer's location at ET and arrive at the
      !>              target's location at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            state of the target at the moment it
      !>                            receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            state obtained with the 'XLT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. The position component of
      !>                            the computed target state indicates the
      !>                            direction that photons emitted from the
      !>                            observer's location must be "aimed" to
      !>                            hit the target.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time correction and
      !>                            stellar aberration correction.
      !>
      !>              Neither special nor general relativistic effects are
      !>              accounted for in the aberration corrections applied
      !>              by this routine.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     OBS      is the NAIF ID code for an observing body.
      !>
      !>## Detailed Output
      !>
      !>     STARG    is a Cartesian state vector representing the position
      !>              and velocity of the target body relative to the
      !>              specified observer. STARG is corrected for the
      !>              specified aberrations, and is expressed with respect
      !>              to the reference frame specified by REF. The first
      !>              three components of STARG represent the x-, y- and
      !>              z-components of the target's position; the last three
      !>              components form the corresponding velocity vector.
      !>
      !>              The position component of STARG points from the
      !>              observer's location at ET to the aberration-corrected
      !>              location of the target. Note that the sense of the
      !>              position vector is independent of the direction of
      !>              radiation travel implied by the aberration
      !>              correction.
      !>
      !>              The velocity component of STARG is the derivative
      !>              with respect to time of the position component of
      !>              STARG.
      !>
      !>              Units are always km and km/sec.
      !>
      !>              Non-inertial frames are treated as follows: letting
      !>              LTCENT be the one-way light time between the observer
      !>              and the central body associated with the frame, the
      !>              orientation of the frame is evaluated at ET-LTCENT,
      !>              ET+LTCENT, or ET depending on whether the requested
      !>              aberration correction is, respectively, for received
      !>              radiation, transmitted radiation, or is omitted.
      !>              LTCENT is computed using the method indicated by
      !>              ABCORR.
      !>
      !>     LT       is the one-way light time between the observer and
      !>              target in seconds. If the target state is corrected
      !>              for aberrations, then LT is the one-way light time
      !>              between the observer and the light time corrected
      !>              target location.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the reference frame REF is not a recognized reference
      !>         frame, the error SPICE(UNKNOWNFRAME) is signaled.
      !>
      !>     2)  If the loaded kernels provide insufficient data to compute the
      !>         requested state vector, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If an error occurs while reading an SPK or other kernel file,
      !>         the error  is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     4)  If any of the required attributes of the reference frame REF
      !>         cannot be determined, the error SPICE(UNKNOWNFRAME2) is
      !>         signaled.
      !>
      !>## Files
      !>
      !>     This routine computes states using SPK files that have been
      !>     loaded into the SPICE system, normally via the kernel loading
      !>     interface routine FURNSH. See the routine FURNSH and the SPK
      !>     and KERNEL Required Reading for further information on loading
      !>     (and unloading) kernels.
      !>
      !>     If the output state STARG is to be expressed relative to a
      !>     non-inertial frame, or if any of the ephemeris data used to
      !>     compute STARG are expressed relative to a non-inertial frame in
      !>     the SPK files providing those data, additional kernels may be
      !>     needed to enable the reference frame transformations required to
      !>     compute the state. Normally these additional kernels are PCK
      !>     files or frame kernels. Any such kernels must already be loaded
      !>     at the time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine is part of the user interface to the SPICE ephemeris
      !>     system. It allows you to retrieve state information for any
      !>     ephemeris object relative to any other in a reference frame that
      !>     is convenient for further computations.
      !>
      !>     Aberration corrections
      !>     ======================
      !>
      !>     In space science or engineering applications one frequently
      !>     wishes to know where to point a remote sensing instrument, such
      !>     as an optical camera or radio antenna, in order to observe or
      !>     otherwise receive radiation from a target. This pointing problem
      !>     is complicated by the finite speed of light: one needs to point
      !>     to where the target appears to be as opposed to where it actually
      !>     is at the epoch of observation. We use the adjectives
      !>     "geometric," "uncorrected," or "true" to refer to an actual
      !>     position or state of a target at a specified epoch. When a
      !>     geometric position or state vector is modified to reflect how it
      !>     appears to an observer, we describe that vector by any of the
      !>     terms "apparent," "corrected," "aberration corrected," or "light
      !>     time and stellar aberration corrected." The SPICE Toolkit can
      !>     correct for two phenomena affecting the apparent location of an
      !>     object: one-way light time (also called "planetary aberration")
      !>     and stellar aberration.
      !>
      !>     One-way light time
      !>     ------------------
      !>
      !>     Correcting for one-way light time is done by computing, given an
      !>     observer and observation epoch, where a target was when the
      !>     observed photons departed the target's location. The vector from
      !>     the observer to this computed target location is called a "light
      !>     time corrected" vector. The light time correction depends on the
      !>     motion of the target relative to the solar system barycenter, but
      !>     it is independent of the velocity of the observer relative to the
      !>     solar system barycenter. Relativistic effects such as light
      !>     bending and gravitational delay are not accounted for in the
      !>     light time correction performed by this routine.
      !>
      !>     Stellar aberration
      !>     ------------------
      !>
      !>     The velocity of the observer also affects the apparent location
      !>     of a target: photons arriving at the observer are subject to a
      !>     "raindrop effect" whereby their velocity relative to the observer
      !>     is, using a Newtonian approximation, the photons' velocity
      !>     relative to the solar system barycenter minus the velocity of the
      !>     observer relative to the solar system barycenter. This effect is
      !>     called "stellar aberration." Stellar aberration is independent
      !>     of the velocity of the target. The stellar aberration formula
      !>     used by this routine does not include (the much smaller)
      !>     relativistic effects.
      !>
      !>     Stellar aberration corrections are applied after light time
      !>     corrections: the light time corrected target position vector is
      !>     used as an input to the stellar aberration correction.
      !>
      !>     When light time and stellar aberration corrections are both
      !>     applied to a geometric position vector, the resulting position
      !>     vector indicates where the target "appears to be" from the
      !>     observer's location.
      !>
      !>     As opposed to computing the apparent position of a target, one
      !>     may wish to compute the pointing direction required for
      !>     transmission of photons to the target. This also requires
      !>     correction of the geometric target position for the effects of
      !>     light time and stellar aberration, but in this case the
      !>     corrections are computed for radiation traveling *from* the
      !>     observer to the target.
      !>
      !>     The "transmission" light time correction yields the target's
      !>     location as it will be when photons emitted from the observer's
      !>     location at ET arrive at the target. The transmission stellar
      !>     aberration correction is the inverse of the traditional stellar
      !>     aberration correction: it indicates the direction in which
      !>     radiation should be emitted so that, using a Newtonian
      !>     approximation, the sum of the velocity of the radiation relative
      !>     to the observer and of the observer's velocity, relative to the
      !>     solar system barycenter, yields a velocity vector that points in
      !>     the direction of the light time corrected position of the target.
      !>
      !>     One may object to using the term "observer" in the transmission
      !>     case, in which radiation is emitted from the observer's location.
      !>     The terminology was retained for consistency with earlier
      !>     documentation.
      !>
      !>     Below, we indicate the aberration corrections to use for some
      !>     common applications:
      !>
      !>        1) Find the apparent direction of a target for a remote-sensing
      !>           observation.
      !>
      !>              Use 'LT+S' or 'CN+S: apply both light time and stellar
      !>              aberration corrections.
      !>
      !>           Note that using light time corrections alone ('LT' or 'CN')
      !>           is generally not a good way to obtain an approximation to
      !>           an apparent target vector: since light time and stellar
      !>           aberration corrections often partially cancel each other,
      !>           it may be more accurate to use no correction at all than to
      !>           use light time alone.
      !>
      !>        2) Find the corrected pointing direction to radiate a signal
      !>           to a target. This computation is often applicable for
      !>           implementing communications sessions.
      !>
      !>              Use 'XLT+S' or 'XCN+S: apply both light time and stellar
      !>              aberration corrections for transmission.
      !>
      !>        3) Compute the apparent position of a target body relative
      !>           to a star or other distant object.
      !>
      !>              Use 'LT', 'CN', 'LT+S', or 'CN+S' as needed to match the
      !>              correction applied to the position of the distant
      !>              object. For example, if a star position is obtained from
      !>              a catalog, the position vector may not be corrected for
      !>              stellar aberration. In this case, to find the angular
      !>              separation of the star and the limb of a planet, the
      !>              vector from the observer to the planet should be
      !>              corrected for light time but not stellar aberration.
      !>
      !>        4) Obtain an uncorrected state vector derived directly from
      !>           data in an SPK file.
      !>
      !>              Use 'NONE'.
      !>
      !>        5) Use a geometric state vector as a low-accuracy estimate
      !>           of the apparent state for an application where execution
      !>           speed is critical.
      !>
      !>              Use 'NONE'.
      !>
      !>        6) While this routine cannot perform the relativistic
      !>           aberration corrections required to compute states
      !>           with the highest possible accuracy, it can supply the
      !>           geometric states required as inputs to these computations.
      !>
      !>              Use 'NONE', then apply relativistic aberration
      !>              corrections (not available in the SPICE Toolkit).
      !>
      !>     Below, we discuss in more detail how the aberration corrections
      !>     applied by this routine are computed.
      !>
      !>        Geometric case
      !>        ==============
      !>
      !>        SPKEZ begins by computing the geometric position T(ET) of the
      !>        target body relative to the solar system barycenter (SSB).
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the geometric position of the target body relative to the
      !>        observer. The one-way light time, LT, is given by
      !>
      !>                  | T(ET) - O(ET) |
      !>           LT = -------------------
      !>                          c
      !>
      !>        The geometric relationship between the observer, target, and
      !>        solar system barycenter is as shown:
      !>
      !>           SSB ---> O(ET)
      !>            |      /
      !>            |     /
      !>            |    /
      !>            |   /  T(ET) - O(ET)
      !>            V  V
      !>           T(ET)
      !>
      !>        The returned state consists of the position vector
      !>
      !>           T(ET) - O(ET)
      !>
      !>        and a velocity obtained by taking the difference of the
      !>        corresponding velocities. In the geometric case, the
      !>        returned velocity is actually the time derivative of the
      !>        position.
      !>
      !>        Reception case
      !>        ==============
      !>
      !>        When any of the options 'LT', 'CN', 'LT+S', 'CN+S' is selected
      !>        for ABCORR, SPKEZ computes the position of the target body at
      !>        epoch ET-LT, where LT is the one-way light time. Let T(t) and
      !>        O(t) represent the positions of the target and observer
      !>        relative to the solar system barycenter at time t; then LT is
      !>        the solution of the light-time equation
      !>
      !>                  | T(ET-LT) - O(ET) |
      !>           LT = ------------------------                            (1)
      !>                           c
      !>
      !>        The ratio
      !>
      !>            | T(ET) - O(ET) |
      !>          ---------------------                                     (2)
      !>                    c
      !>
      !>        is used as a first approximation to LT; inserting (2) into the
      !>        right hand side of the light-time equation (1) yields the
      !>        "one-iteration" estimate of the one-way light time ("LT").
      !>        Repeating the process until the estimates of LT converge
      !>        yields the "converged Newtonian" light time estimate ("CN").
      !>
      !>        Subtracting the geometric position of the observer O(ET) gives
      !>        the position of the target body relative to the observer:
      !>        T(ET-LT) - O(ET).
      !>
      !>           SSB ---> O(ET)
      !>            | \     |
      !>            |  \    |
      !>            |   \   | T(ET-LT) - O(ET)
      !>            |    \  |
      !>            V     V V
      !>           T(ET)  T(ET-LT)
      !>
      !>        The position component of the light time corrected state
      !>        is the vector
      !>
      !>           T(ET-LT) - O(ET)
      !>
      !>        The velocity component of the light time corrected state
      !>        is the difference
      !>
      !>           T_vel(ET-LT)*(1-dLT/dET) - O_vel(ET)
      !>
      !>        where T_vel and O_vel are, respectively, the velocities of the
      !>        target and observer relative to the solar system barycenter at
      !>        the epochs ET-LT and ET.
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated toward the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as follows:
      !>
      !>           Let r be the light time corrected vector from the observer
      !>           to the object, and v be the velocity of the observer with
      !>           respect to the solar system barycenter. Let w be the angle
      !>           between them. The aberration angle phi is given by
      !>
      !>              sin(phi) = v sin(w) / c
      !>
      !>           Let h be the vector given by the cross product
      !>
      !>              h = r X v
      !>
      !>           Rotate r by phi radians about h to obtain the apparent
      !>           position of the object.
      !>
      !>        When stellar aberration corrections are used, the rate of
      !>        change of the stellar aberration correction is accounted for
      !>        in the computation of the output velocity.
      !>
      !>        Transmission case
      !>        ==================
      !>
      !>        When any of the options 'XLT', 'XCN', 'XLT+S', 'XCN+S' is
      !>        selected, SPKEZ computes the position of the target body T at
      !>        epoch ET+LT, where LT is the one-way light time. LT is the
      !>        solution of the light-time equation
      !>
      !>                  | T(ET+LT) - O(ET) |
      !>           LT = ------------------------                            (3)
      !>                            c
      !>
      !>        Subtracting the geometric position of the observer, O(ET),
      !>        gives the position of the target body relative to the
      !>        observer: T(ET-LT) - O(ET).
      !>
      !>                   SSB --> O(ET)
      !>                  / |    *
      !>                 /  |  *  T(ET+LT) - O(ET)
      !>                /   |*
      !>               /   *|
      !>              V  V  V
      !>          T(ET+LT)  T(ET)
      !>
      !>        The position component of the light-time corrected state
      !>        is the vector
      !>
      !>           T(ET+LT) - O(ET)
      !>
      !>        The velocity component of the light-time corrected state
      !>        consists of the difference
      !>
      !>           T_vel(ET+LT)*(1+dLT/dET) - O_vel(ET)
      !>
      !>        where T_vel and O_vel are, respectively, the velocities of the
      !>        target and observer relative to the solar system barycenter at
      !>        the epochs ET+LT and ET.
      !>
      !>        If correction for stellar aberration is requested, the target
      !>        position is rotated away from the solar system barycenter-
      !>        relative velocity vector of the observer. The rotation is
      !>        computed as in the reception case, but the sign of the
      !>        rotation angle is negated. Velocities are adjusted to account
      !>        for the rate of change of the stellar aberration correction.
      !>
      !>     Precision of light time corrections
      !>     ===================================
      !>
      !>        Corrections using one iteration of the light time solution
      !>        ----------------------------------------------------------
      !>
      !>        When the requested aberration correction is 'LT', 'LT+S',
      !>        'XLT', or 'XLT+S', only one iteration is performed in the
      !>        algorithm used to compute LT.
      !>
      !>        The relative error in this computation
      !>
      !>           | LT_ACTUAL - LT_COMPUTED |  /  LT_ACTUAL
      !>
      !>        is at most
      !>
      !>            (V/C)**2
      !>           ----------
      !>            1 - (V/C)
      !>
      !>        which is well approximated by (V/C)**2, where V is the
      !>        velocity of the target relative to an inertial frame and C is
      !>        the speed of light.
      !>
      !>        For nearly all objects in the solar system V is less than 60
      !>        km/sec. The value of C is ~300000 km/sec. Thus the
      !>        one-iteration solution for LT has a potential relative error
      !>        of not more than 4e-8. This is a potential light time error of
      !>        approximately 2e-5 seconds per astronomical unit of distance
      !>        separating the observer and target. Given the bound on V cited
      !>        above:
      !>
      !>           As long as the observer and target are separated by less
      !>           than 50 astronomical units, the error in the light time
      !>           returned using the one-iteration light time corrections is
      !>           less than 1 millisecond.
      !>
      !>           The magnitude of the corresponding position error, given
      !>           the above assumptions, may be as large as (V/C)**2 * the
      !>           distance between the observer and the uncorrected target
      !>           position: 300 km or equivalently 6 km/AU.
      !>
      !>        In practice, the difference between positions obtained using
      !>        one-iteration and converged light time is usually much smaller
      !>        than the value computed above and can be insignificant. For
      !>        example, for the spacecraft Mars Reconnaissance Orbiter and
      !>        Mars Express, the position error for the one-iteration light
      !>        time correction, applied to the spacecraft-to-Mars center
      !>        vector, is at the 1 cm level.
      !>
      !>        Comparison of results obtained using the one-iteration and
      !>        converged light time solutions is recommended when adequacy of
      !>        the one-iteration solution is in doubt.
      !>
      !>        Converged corrections
      !>        ---------------------
      !>
      !>        When the requested aberration correction is 'CN', 'CN+S',
      !>        'XCN', or 'XCN+S', as many iterations as are required for
      !>        convergence are performed in the computation of LT. Usually
      !>        the solution is found after three iterations. The relative
      !>        error present in this case is at most
      !>
      !>            (V/C)**4
      !>           ----------
      !>            1 - (V/C)
      !>
      !>        which is well approximated by (V/C)**4.
      !>
      !>           The precision of this computation (ignoring round-off
      !>           error) is better than 4e-11 seconds for any pair of objects
      !>           less than 50 AU apart, and having speed relative to the
      !>           solar system barycenter less than 60 km/s.
      !>
      !>           The magnitude of the corresponding position error, given
      !>           the above assumptions, may be as large as (V/C)**4 * the
      !>           distance between the observer and the uncorrected target
      !>           position: 1.2 cm at 50 AU or equivalently 0.24 mm/AU.
      !>
      !>        However, to very accurately model the light time between
      !>        target and observer one must take into account effects due to
      !>        general relativity. These may be as high as a few hundredths
      !>        of a millisecond for some objects.
      !>
      !>     Relativistic Corrections
      !>     =========================
      !>
      !>     This routine does not attempt to perform either general or
      !>     special relativistic corrections in computing the various
      !>     aberration corrections. For many applications relativistic
      !>     corrections are not worth the expense of added computation
      !>     cycles. If however, your application requires these additional
      !>     corrections we suggest you consult the astronomical almanac (page
      !>     B36) for a discussion of how to carry out these corrections.
      !>
      !>## Examples
      !>
      !>     1)  Load a planetary ephemeris SPK; then look up a series of
      !>         geometric states of the moon relative to the earth,
      !>         referenced to the J2000 frame.
      !>
      !>               IMPLICIT NONE
      !>         C
      !>         C     Local constants
      !>         C
      !>               CHARACTER*(*)         FRAME
      !>               PARAMETER           ( FRAME  = 'J2000' )
      !>
      !>               CHARACTER*(*)         ABCORR
      !>               PARAMETER           ( ABCORR = 'NONE' )
      !>
      !>         C
      !>         C     The name of the SPK file shown here is fictitious;
      !>         C     you must supply the name of an SPK file available
      !>         C     on your own computer system.
      !>         C
      !>               CHARACTER*(*)         SPK
      !>               PARAMETER           ( SPK    = 'planet.bsp' )
      !>
      !>         C
      !>         C     ET0 represents the date 2000 Jan 1 12:00:00 TDB.
      !>         C
      !>               DOUBLE PRECISION      ET0
      !>               PARAMETER           ( ET0    = 0.0D0 )
      !>
      !>         C
      !>         C     Use a time step of 1 hour; look up 100 states.
      !>         C
      !>               DOUBLE PRECISION      STEP
      !>               PARAMETER           ( STEP   = 3600.0D0 )
      !>
      !>               INTEGER               MAXITR
      !>               PARAMETER           ( MAXITR = 100 )
      !>
      !>         C
      !>         C     The NAIF IDs of the earth and moon are 399 and 301
      !>         C     respectively.
      !>         C
      !>               INTEGER               OBSRVR
      !>               PARAMETER           ( OBSRVR = 399 )
      !>
      !>               INTEGER               TARGET
      !>               PARAMETER           ( TARGET = 301 )
      !>
      !>         C
      !>         C     Local variables
      !>         C
      !>               DOUBLE PRECISION      ET
      !>               DOUBLE PRECISION      LT
      !>               DOUBLE PRECISION      STATE ( 6 )
      !>
      !>               INTEGER               I
      !>
      !>         C
      !>         C     Load the SPK file.
      !>         C
      !>               CALL FURNSH ( SPK )
      !>
      !>         C
      !>         C     Step through a series of epochs, looking up a
      !>         C     state vector at each one.
      !>         C
      !>               DO I = 1, MAXITR
      !>
      !>                  ET = ET0 + (I-1)*STEP
      !>
      !>                  CALL SPKEZ ( TARGET, ET, FRAME, ABCORR, OBSRVR,
      !>              .                STATE,  LT                        )
      !>
      !>                  WRITE (*,*) 'ET = ', ET
      !>                  WRITE (*,*) 'J2000 x-position (km):   ', STATE(1)
      !>                  WRITE (*,*) 'J2000 y-position (km):   ', STATE(2)
      !>                  WRITE (*,*) 'J2000 z-position (km):   ', STATE(3)
      !>                  WRITE (*,*) 'J2000 x-velocity (km/s): ', STATE(4)
      !>                  WRITE (*,*) 'J2000 y-velocity (km/s): ', STATE(5)
      !>                  WRITE (*,*) 'J2000 z-velocity (km/s): ', STATE(6)
      !>                  WRITE (*,*) ' '
      !>
      !>               END DO
      !>
      !>               END
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
